(window.GIM_TS=window.GIM_TS||{})["Berakhot.1"]={"from":24,"a":[["\u0003ובפרקים\u0004 — \u0003שואל מפני הכבוד ומשיב שלום לכל אדם.\u0004 ואם כן, על פי סגנון זה אין עוד מקום לתמוה על צורת הדברים במשנה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הקורא את שמע ופגע בו רבו או גדול הימנו\u0004 (ממנו), \u0003בפרקים\u0004 — \u0003שואל מפני הכבוד ואין צריך לומר שהוא משיב, ובאמצע\u0004 — \u0003שואל מפני היראה ואין צריך לומר שהוא משיב.\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: באמצע\u0004 — \u0003שואל מפני היראה ומשיב מפני הכבוד, ובפרקים\u0004 — \u0003שואל מפני הכבוד ומשיב שלום לכל אדם.\u0004 ונמצאו איפוא הדברים שהושלמו כאן מסברא מפרשים בברייתא זו.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אחי תנא דבי\u0004 \u0005[חוזר המשניות של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא מר' חייא: בהלל וב\u0004קריאת ה\u0003מגילה\u0004 (מגילת אסתר) \u0003מהו שיפסיק\u0004 לשאלת שלום? וצדדי השאלה: האם \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003קל וחומר\u0004 זה: אם באמצע \u0003קריאת שמע\u0004 שהיא חובה \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 — \u0003פוסק\u0004 הוא לשאילת שלום, באמצע \u0003הלל\u0004 שהוא רק חובה \u0003דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003מבעיא\u0004 \u0005[צריך\u0006 לומר] שהוא פוסק?! \u0003או דלמא פרסומי ניסא\u0004 \u0005[שמא פרסום הנס]\u0006 \u0003עדיף,\u0004 ולכן אין להפסיק בהלל ובמגילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003פוסק, ואין בכך כלום. אמר רבה: ימים שהיחיד גומר בהן את ההלל,\u0004 אותם ימים שבהם קריאת ההלל היא חובה מדברי חכמים, \u0003בין פרק לפרק\u0004 היחיד יכול להיות \u0003פוסק\u0004 באמצע, אבל \u0003באמצע הפרק\u0004 — \u0003אינו פוסק, ו\u0004אילו באותם ה\u0003ימים שאין היחיד גומר בהן את ההלל,\u0004 משום שקריאת ההלל בהם היא מנהג בלבד — \u0003אפילו באמצע הפרק פוסק.\u0004","על כך שואלים: \u0003איני\u0004 \u0005[וכן הוא?!]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב בר שבא איקלע לגביה\u0004 \u0005[הזדמן לפני]\u0006 \u0003רבינא, ו\u0004באחד מן ה\u0003ימים שאין היחיד גומר\u0004 בהם \u0003את ההלל הוה\u0004 \u0005[היה]\u0006 זה, \u0003ולא פסיק ליה\u0004 \u0005[הפסיק לו,\u0006 עבורו\u0005]\u0006 רבינא בקריאת ההלל\u0005!\u0006","על כך משיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב בר שבא\u0004 ש\u0003לא חשיב עליה\u0004 \u0005[נחשב עליו,\u0006 בעיניו\u0005]\u0006 של \u0003רבינא\u0004 ולכן לא הפסיק עבורו.","מאחר שהוזכרה שאלתו של אחד התנאים (חוזרי המשניות) מביאים את מה ש\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אשיאן תנא דבי\u0004 \u0005[חוזר המשניות של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי מר' אמי:\u0004 אדם \u0003השרוי בתענית מהו שיטעום?\u0004 וצדדי השאלה: האם נאמר כי \u0003אכילה ושתיה קביל עליה\u0004 \u0005[קיבל על עצמו]\u0006 שלא לאכול — \u0003והא ליכא\u0004 \u0005[והרי אין כאן],\u0006 שאינו אלא טועם. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 איסור \u0003הנאה\u0004 ממאכלים \u0003קביל עליה\u0004 \u0005[קיבל על עצמו]\u0006 — \u0003והא איכא\u0004 \u0005[והרי יש כאן].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003טועם ואין בכך כלום.\u0004 ואכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מטעמת\u0004 (דבר שטועמים) \u0003אינה טעונה ברכה\u0004 לפניה \u0003ו\u0004אף \u0003השרוי בתענית טועם ואין בכך כלום.\u0004","על כך שואלים: \u0003עד כמה\u0004 מותר לאדם השרוי בתענית להכניס בפיו לצורך טעימה?","ומשיבים, כי \u0003ר' אמי ור' אסי\u0004 כשהיו בתענית \u0003טעמי\u0004 \u0005[היו טועמים]\u0006 \u0003עד שיעור רביעתא\u0004 \u0005[רביעית\u0006 הלוג\u0005].\u0006","\u0003אמר רב: כל הנותן שלום לחבירו קודם שיתפלל\u0004 בבוקר \u0003כאילו עשאו במה\u0004 לעבודה זרה. ורמז לדבר ממה \u0003שנאמר: \"חדלו לכם מן האדם אשר נשמה באפו כי במה נחשב הוא\"\u0004 (ישעיהו ב, כב), כלומר, כאשר אך באה הנשמה באפו של אדם בבוקר (גאונים) אין הוא צריך לפנות אל בני אדם אחרים, כי אם אל הקדוש ברוך הוא. ו\u0003אל תקרי\u0004 \u0005[תקרא],\u0006 כפי שכתוב \u0003\"במה\" אלא \"במה\".\u0004","\u0003ושמואל אמר:\u0004 אין לדרוש את הלשון \"במה\" בשונה מכפי שהוא כתוב, אלא כמשמעו של הכתוב: \u0003במה חשבתו לזה\u0004 שהקדמת את כבודו \u0003ולא לאלוה?\u0004 שוודאי שהיה עליך לכבד את הקדוש ברוך הוא בראשונה.","על עיקרם של הדברים \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת:\u0004 הרי שנינו במשנתנו ש\u0003בפרקים\u0004 בקריאת שמע \u0003שואל\u0004 בשלום \u0003מפני הכבוד ומשיב,\u0004 ואף שקריאת שמע קודמת לתפילה!","\u0003תרגמה\u0004 \u0005[תרגם אותה,\u0006 הסביר\u0005]\u0006 \u0003ר' אבא:\u0004 איסור זה לשאול בשלום חבירו בבוקר הריהו דווקא \u0003במשכים לפתחו\u0004 לומר לו שלום, אבל אם אמר לו שלום כשנפגש בו באקראי — \u0003מותר. \u0004","על אותו פסוק \u0003אמר ר' יונה אמר ר' זירא: כל העושה חפציו קודם שיתפלל\u0004 — \u0003הריהו כאלו בנה במה.\u0004 על הלכה זו \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לר' יונה: האומר: \u0003\"במה\" אמרת? אמר להו\u0004 \u0005[לו]:\u0006 \u0003לא, \"אסור\" קא אמינא\u0004 \u0005[אמרתי],\u0006 אבל לא החמרתי עד כדי קריאת הדבר בשם עשיית במה.","\u0003וכ\u0004עין דברי \u0003רב אידי בר אבין\u0004 ש\u0003אמר\u0004 בשם \u0003רב יצחק בר אשיאן: אסור לו לאדם לעשות חפציו קודם שיתפלל, שנאמר: \"צדק לפניו יהלך וישם לדרך פעמיו\"\u0004 (תהלים פה, יד), שקודם יש להתפלל ולהצדיק את בוראו, ואחר כך יכול לשים לדרך פעמיו.","\u0003ו\u0004עוד \u0003אמר רב אידי בר אבין אמר רב יצחק בר אשיאן: כל המתפלל\u0004 תחילה ורק \u0003אחר כך יוצא לדרך, הקדוש ברוך הוא עושה לו חפציו, שנאמר: \"צדק לפניו יהלך וישם לדרך פעמיו\",\u0004 כלומר, הקדוש ברוך הא יוליך לפניו צדק ויעשה לו כל רצונותיו כאשר \"ישים לדרך פעמיו\".","ואגב הזכרת שמו, מביאים עוד מה ש\u0003אמר ר' יונה אמר ר' זירא: כל הלן שבעה ימים בלא חלום נקרא \"רע\", שנאמר: \"ושבע ילין בל יפקד רע\"\u0004 (משלי יט, כג), שלדעתו כדי לפרש כתוב זה \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שבע\" אלא \"שבע\",\u0004 כלומר, אדם הלן שבעה לילות ואינו נפקד בחלום — הוא הנקרא \"רע\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' חייא אמר ר' יוחנן: כל המשביע עצמו מדברי תורה ולן\u0004 — \u0003אין מבשרין אותו בשורות רעות, שנאמר: \"ושבע ילין בל יפקד רע\".\u0004","שנינו במשנה: \u0003אלו הן בין הפרקים\u0004 בקריאת שמע בהם מותר בתנאים מסויימים להפסיק, לדעת התנא הראשון מותר להפסיק בין סוף פרשת \"ויאמר\" לבין \"אמת ויציב\", ואילו ר' יהודה אוסר.","\u0003אמר ר' אבהו אמר ר' יוחנן: הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 ש\u0003בין \"אלהיכם\" ל\"אמת ויציב\" לא יפסיק.\u0004 ועוד \u0003אמר ר' אבהו אמר ר' יוחנן: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן כבר \u0005נאמר]\u0006 צירוף מילים אלה:"],["\u0003\"וה' אלהים אמת\"\u0004 (ירמיה י, י).","מאחר שמסיימים את פרשת \"ויאמר\" ב\"ה' אלהיכם אמת\" נתעוררה השאלה האם \u0003חוזר ואומר \"אמת\"\u0004 כשהוא מתחיל \"אמת ויציב\", \u0003או אינו חוזר ואומר?\u0004","\u0003אמר ר' אבהו אמר ר' יוחנן: חוזר ואומר \"אמת\". רבה אמר: אינו חוזר ואומר \"אמת\".\u0004 ומסופר: \u0003ההוא דנחית קמיה\u0004 \u0005[\u0006אדם \u0005אחד שירד,\u0006 שעבר לפני התיבה \u0005לפני]\u0006 \u0003רבה. שמעיה\u0004 \u0005[שמעו]\u0006 \u0003רבה דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003\"אמת\" \"אמת\" תרי זימני\u0004 \u0005[שתי פעמים].\u0006 \u0003אמר רבה\u0004 עליו בלגלוג: \u0003כל \"אמת\" \"אמת\" תפסיה להאי\u0004 \u0005[תפשה את זה],\u0006 כלומר, להיטות יש לו לאדם זה אחרי האמת.","\u0003אמר רב יוסף: כמה מעליא הא שמעתתא\u0004 \u0005[מעולה\u0006 היא \u0005הלכה זו]\u0006 ששמעתי, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל לבבל סיפר: \u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 בזמן תפילת \u0003ערבית\u0004 לא את כל פרשת ציצית כולה — שהרי אין חיוב ציצית בלילה — כי אם רק קיצור הפרשה, מילים אחדות מן ההתחלה והסוף. \u0003\"דבר אל בני ישראל ואמרת אליהם אני ה' אלהיכם אמת\"\u0004 (במדבר טו, לח. שם מא).","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי מעליותא\u0004 \u0005[מה המעולה]\u0006 שבהלכה זו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אמר רב כהנא אמר רב: לא יתחיל\u0004 בערב לקרות פרשת ציצית, \u0003ואם התחיל\u0004 — \u0003גומר. וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003\"ואמרת אליהם\" לא הוי\u0004 \u0005[אינו נחשב]\u0006 כ\u0003התחלה\u0004 של פרשת ציצית — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שמואל בר יצחק אמר רב\u0004 שרק \u0003\"דבר אל בני ישראל\" לא הוי\u0004 \u0005[אינו נחשב]\u0006 כ\u0003התחלה\u0004 של פרשת ציצית, שכן גם פרשיות אחרות בתורה מתחילות כך, אבל \u0003\"ואמרת אליהם\"\u0004 הריהו כבר \u0003הוי\u0004 \u0005[נחשב]\u0006 \u0003התחלה.\u0004","\u0003על כך אמר רב פפא: קסברי במערבא\u0004 \u0005[סבורים בארץ ישראל]\u0006 ש\u0003\"ואמרת אליהם\" נמי לא הויא\u0004 \u0005[גם כן אינו נחשב]\u0006 ל\u0003התחלה עד דאמר\u0004 \u0005[שיאמר]\u0006 \u0003\"ועשו להם ציצית\". \u0004","בסיכום הדברים \u0003אמר אביי: הלכך, אנן אתחולי מתחלינן, דקא מתחלי במערבא\u0004 \u0005[על כן, אנחנו מתחילים,\u0006 בפרשת ציצית, \u0005שכן מתחילים בארץ ישראל],\u0006 \u0003וכיון דאתחלינן\u0004 \u0005[שהתחלנו]\u0006 — \u0003מגמר נמי גמרינן\u0004 \u0005[אנו גם כן גומרים].\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב כהנא אמר רב\u0004 ש\u0003לא יתחיל, ו\u0004אולם \u0003אם התחיל\u0004 כבר — \u0003גומר,\u0004 וכן אנו נוהגים.","\u0003חייא בר רב אמר: שאם אמר\u0004 בערב פרשת ציצית המסתיימת \u0003\"אני ה' אלהיכם\", צריך לומר\u0004 נוסח \u0003\"אמת\u0004 ואמונה \u0003\"\u0004וכל ברכת הגאולה, אולם אם \u0003לא אמר \"אני ה' אלהיכם\"\u0004 — \u0003אינו צריך לומר \"אמת\".\u0004","על כך שואלים: \u0003והא בעי לאדכורי\u0004 \u0005[והרי צריך להזכיר]\u0006 \u0003יציאת מצרים\u0004 גם בלילה!","ומשיבים: אין הוא אומר אז \"אמת ואמונה\", אלא \u0003דאמר הכי\u0004 \u0005[ש\u0006הוא \u0005אומר כך]\u0006 בנוסח אחר, מקוצר: \u0003\"מודים אנחנו לך ה' אלהינו שהוצאתנו מארץ מצרים ופדיתנו מבית עבדים ועשית לנו נסים וגבורות על הים ושרנו לך\",\u0004 שנוסח זה כולל את כל התכנים שבברכת \"אמת ואמונה\" במלואה.","שנינו במשנה ש\u0003אמר ר' יהושע בן קרחה: למה קדמה פרשת \"שמע\"\u0004 ל\"והיה אם שמוע\", שפרשת \"שמע\" יש בה קבלת עול מלכות שמים, וב\"והיה אם שמוע\" — \u0003קבלת עול מצוות בלבד.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אשר בה \u0003ר' שמעון בן יוחי אומר\u0004 הסבר אחר לסדר הפרשיות בקריאת שמע: \u0003בדין הוא שיקדים\u0004 פרשת \u0003\"שמע\" ל\"והיה אם שמע\", ש\u0004כן ב\u0003זה,\u0004 בפרשת \"שמע\", נזכר הציווי \u0003ללמוד, ו\u0004אילו ב\u0003זה,\u0004 בפרשת \"והיה אם שמוע\" הציווי ללמד. וכן ראוי להקדים \u0003\"והיה אם שמע\" ל\"ויאמר\", ש\u0004כן ב\u0003זה,\u0004 ב\"והיה אם שמוע\", הציווי הוא ללמד, ואילו \u0003זה,\u0004 בפרשת ציצית משמעה \u0003לעשות.\u0004","על כך שואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 פרשת \u0003\"שמע\" ללמוד אית ביה\u0004 \u0005[יש בה]\u0006 ואילו \u0003ללמד ולעשות לית ביה\u0004 \u0005[אין בה]?!\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 בה הציוויים: \u0003\"ושננתם\u0004 לבניך\u0003\"\u0004 (דברים ו, ז) — הרי כאן ללמד, וכן \u0003\"וקשרתם\u0004 לאות על ידך\u0003\"\u0004 (שם ח), וכן \u0003\"וכתבתם\u0004 על מזוזות ביתך ובשעריך\u0003\"\u0004 (שם ט) — הרי כאן לעשות. \u0003ותו\u0004 \u0005[ועוד]:\u0006 אף בפרשת \u0003\"והיה אם שמע\"\u0004 האם רק \u0003ללמד הוא דאית ביה\u0004 \u0005[שיש בה]\u0006 \u0003ו\u0004אילו \u0003לעשות לית ביה\u0004 \u0005[אין בה]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 בה: \u0003\"וקשרתם\u0004 אותם לאות על ידכם\u0003\"\u0004 (שם יא, יח)!","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לפרש את דברי ר' שמעון בן יוחאי: \u0003בדין הוא שתקדם\u0004 פרשת \u0003\"שמע\" ל\"והיה אם שמע\", ש\u0004כן \u0003זה,\u0004 פרשת \"שמע\" יש בה גם \u0003ללמוד ו\u0004גם \u0003ללמד ו\u0004גם \u0003לעשות,\u0004 מה שאין כן פרשת \"והיה אם שמוע\" שאין בה אלא ללמד ולעשות בלבד. וכן ראוי שתקדים פרשת \u0003\"והיה אם שמע\" ל\"ויאמר\" ש\u0004כן \u0003זה,\u0004 פרשת \"והיה אם שמוע\" \u0003יש בה ללמד ולעשות,\u0004 ואילו \u0003\"ויאמר\" אין בה אלא לעשות בלבד.\u0004","על כך שואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 מסקנה זו על הקדמת \"שמע\", \u0003מ\u0004דברי \u0003ר' יהושע בן קרחה!\u0004 ומשיבים: \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003ועוד קאמר\u0004 \u0005[אמר],\u0006 לא שרצה לחלוק על דברי ר' יהושע בן קרחה, אלא שזהו הינו נימוק אחד, ויש להוסיף עליו עוד ובאופן זה, \u0003חדא\u0004 \u0005[אחד]:\u0006 \u0003כדי שיקבל עליו עול מלכות שמים תחלה ואחר כך יקבל עליו עול מצות, ועוד\u0004 — \u0003משום דאית\u0004 \u0005[שיש]\u0006 \u0003בה הני מילי אחרנייתא [אותם דברים אחרים].\u0004","מסופר כי \u0003רב משי ידיה\u0004 \u0005[רחץ ידיו],\u0006 \u0003וקרא קריאת שמע, ואנח\u0004 \u0005[והניח]\u0006 \u0003תפילין וצלי\u0004 \u0005[והתפלל]\u0006 בסדר זה. על כך שאלו: \u0003והיכי עביד הכי\u0004 \u0005[וכיצד עשה כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003החופר כוך ל\u0004הכניס את ה\u0003מת\u0004 בתוך קבר משפחתו — \u0003פטור מקריאת שמע ומן התפלה ומן התפילין ומכל מצות האמורות בתורה. הגיע זמן קריאת שמע\u0004 — \u0003עולה\u0004 מן הקבר \u0003ונוטל ידיו, ומניח תפילין, וקורא קריאת שמע, ומתפלל.\u0004","עוד לפני שמבררים את הקושיה מעירים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה,\u0006 ברייתא זו, \u0005קשה],\u0006 שכן \u0003רישא\u0004 \u0005[בראשה]\u0006 \u0003אמר\u0004 שהחופר קבר \u0003פטור\u0004 מקריאת שמע, \u0003וסיפא\u0004 \u0005[ובסופה]\u0006 ש\u0003חייב\u0004 לעלות ולקרוא?!","על כך משיבים: \u0003הא לא קשיא\u0004 \u0005[זו אינו קשה],\u0006 שאפשר לפרש: \u0003סיפא\u0004 \u0005[סופה\u0006 של הברייתא\u0005]\u0006 מדבר \u0003בתרי\u0004 \u0005[בשניים]\u0006 החופרים יחד את הקבר, שאפשר שיפסיק אחד מהם לקריאת שמע. \u0003ורישא בחד\u0004 \u0005[וראשה\u0006 מדבר \u0005באחד]\u0006 החופר לבדו ואין לו להפסיק.","\u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 הדבר \u0003לרב\u0004 מבחינת סדר הדברים. ומשיבים: \u0003רב כ\u0004שיטת \u0003ר' יהושע בן קרחה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 ר' יהושע בן קרחה שראוי להקדים קבלת \u0003עול מלכות שמים תחלה ואחר כך\u0004 קבלת \u0003עול מצות,\u0004 ולכן קרא רב קודם קריאת שמע ואחר כך הניח תפילין.","על כך מקשים: \u0003אימר\u0004 \u0005[תאמר]\u0006 ש\u0003אמר ר' יהושע בן קרחה\u0004 שיש להקדים עול מלכות שמים — \u0003להקדים קריאה לקריאה,\u0004 להקדים קריאת פרשה שיש בה עול מלכות שמים לקריאה אחרת, ואולם הקדמת \u0003קריאה לעשיה מי שמעת ליה\u0004 \u0005[האם שמעת אותו]?\u0006 שיאמר הלכה כעין זו?!","\u0003ותו, מי סבר ליה\u0004 \u0005[ועוד, האם סבור הוא]\u0006 רב עצמו \u0003כר' יהושע בן קרחה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חייא בר אשי: זמנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים רבות הייתי עומד לפני]\u0006 \u0003רב, ומקדים ומשי ידיה\u0004 \u0005[ו\u0006היה \u0005רוחץ\u0006 את \u0005ידיו],\u0006 \u0003ומברך, ומתני לן פרקין, ומנח\u0004 \u0005[ושונה לנו\u0006 את \u0005פרקנו, ומניח]\u0006 \u0003תפילין, והדר קרי\u0004 \u0005[ואחר כך קורא]\u0006 \u0003קריאת שמע. וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 שהיה זה כשעדיין \u0003לא מטא\u0004 \u0005[הגיע]\u0006 \u0003זמן קריאת שמע\u0004 ולכן הקדים בתפילין, \u0003אם כן מאי אסהדתיה\u0004 \u0005[מהי עדותו]\u0006 של \u0003רב חייא בר אשי?\u0004 שאז אין בעדות—בסיפור זה ללמדנו דבר.","על כך משיבים: סיפור זה בא ללמדנו \u0003לאפוקי ממאן דאמר\u0004 \u0005[להוציא מ\u0006דברי \u0005מי שאומר]\u0006 כי \u0003ל\u0004לימוד \u0003משנה אין צריך לברך\u0004 ברכת התורה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003אף למשנה נמי\u0004 \u0005[גם כן]\u0006 \u0003צריך לברך.\u0004","ו\u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004דברי \u0003רב\u0004 מן הברייתא! ומשיבים: \u0003שלוחא\u0004 \u0005[השליח]\u0006 \u0003הוא דעוית\u0004 \u0005[שעיוות,\u0006 קלקל\u0005],\u0006 שאחר להביא את התפילין, ולכן קרא רב קריאת שמע בזמנה, ורק אחר כך הניח תפילין.","בענין זה \u0003אמר עולא: הקורא קריאת שמע בלא תפילין, כאילו מעיד עדות שקר בעצמו,\u0004 שהרי בקריאת שמע הוא מזכיר את חובת הנחת תפילין, והוא עצמו אינו מניחן (תר\"י). \u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 הקורא קריאת שמע בלא תפילין הרי הוא \u0003כאילו הקריב עולה בלא מנחה\u0004 המתלווה אליה או \u0003זבח בלא נסכים.\u0004 שאף שיצא ידי חובה — \u0003אין קרבנו מושלם.\u0004","\u0003ו\u0004עוד \u0003אמר ר' יוחנן: הרוצה שיקבל עליו עול מלכות שמים שלמה\u0004"],["ראוי לו ש\u0003יפנה\u0004 קודם לצרכיו, \u0003ויטול ידיו, ו\u0004אחר \u0003יניח תפילין, ויקרא קריאת שמע, ויתפלל, וזו היא מלכות שמים שלמה.\u0004","ובדומה לכך \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל הנפנה, ונוטל ידיו, ומניח תפילין, וקורא קריאת שמע, ומתפלל\u0004 — \u0003מעלה עליו הכתוב כאלו בנה מזבח והקריב עליו קרבן, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ארחץ בנקיון כפי ואסובבה את מזבחך ה'\"\u0004 (תהלים כו,ו). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 האם \u0003לא סבר לה מר\u0004 \u0005[סבור אדוני]\u0006 שאפשר להוסיף עוד שכל העושה כן \u0003כאילו טבל, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ארחץ בנקיון\"\u0004 שמשמעו — \u0003את כל הגוף כולו, ולא כתב\u0004 בלשון \u0003\"ארחיץ כפי\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: חזי מר האי צורבא מרבנן דאתא ממערבא\u0004 \u0005[יראה אדוני תלמיד חכם זה שבא מארץ ישראל]\u0006 \u0003ואמר\u0004 דבר תמוה: \u0003מי שאין לו מים לרחוץ ידיו\u0004 — דיו שיהא \u0003מקנח\u0004 את \u0003ידיו בעפר\u0004 או \u0003בצרור\u0004 אבן או \u0003בקסמית\u0004 \u0005[קיסם עץ].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שפיר קאמר\u0004 \u0005[יפה אמר],\u0006 שכן \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 הלשון \u0003\"ארחץ במים\"?\u0004 והלא \u0003\"בנקיון\" כתיב\u0004 \u0005[נאמר],\u0006 ומשמעו — \u0003כל מידי דמנקי\u0004 \u0005[דבר שמנקה],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב חסדא לייט אמאן דמהדר אמיא בעידן צלותא\u0004 \u0005[היה מקלל את מי שמחזר אחרי מים בזמן התפילה].\u0006","ועל כך מעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאין לחזר אחרי המים נאמרו \u0003ל\u0004צורך \u0003קריאת שמע,\u0004 שמאחר וזמנה קבוע ומוגבל, הרי שיתכן שבשל חיזורו אחר מים יעבור זמן קריאת שמע, \u0003אבל ל\u0004צורך \u0003תפלה\u0004 שזמנה כל היום — \u0003מהדר\u0004 \u0005[מחזר].\u0006 \u0003ועד כמה\u0004 הוא המרחק הראוי לו לחפש מים? — \u0003עד פרסה. והני מילי\u0004 \u0005[ודברים אלה]\u0006 שצריך ללכת פרסה אמורים דווקא כשהולך \u0003לקמיה\u0004 \u0005[לפניו],\u0006 באותה דרך שהוא הולך בה, \u0003אבל לאחוריה\u0004 \u0005[לאחוריו]\u0006 — \u0003אפילו מיל\u0004 אחד \u0003אינו חוזר. ומינה\u0004 \u0005[וממנה,\u0006 מדבר זה\u0005]\u0006 אפשר ללמוד כי \u0003מיל הוא\u0004 ש\u0003אינו חוזר, הא\u0004 \u0005[הרי]\u0006 ש\u0003פחות ממיל\u0004 — \u0003חוזר,\u0004 אפילו לאחוריו.","\u0003הקורא את\u0004 קריאת \u0003שמע ולא השמיע לאזנו\u0004 את הקריאה, משום שקרא בלחש או משום שאינו יכול לשמוע — \u0003יצא. ר' יוסי אומר: לא יצא.\u0004","כמו כן, אם \u0003קרא\u0004 את קריאת שמע \u0003ולא דקדק באותיותיה,\u0004 שהוציאן מפיו לא מפורשות כראוי, \u0003ר' יוסי אומר: יצא. ר' יהודה אומר: לא יצא.\u0004","\u0003הקורא למפרע,\u0004 שהקדים את המאוחר — \u0003לא יצא.\u0004 ומי ש\u0003קרא וטעה\u0004 בקריאתו — \u0003יחזור\u0004 שוב \u0003למקום שטעה.\u0004","שנינו במשנתינו בדינו של הקורא את שמע ולא השמיע לאוזנו אם יצא בכך. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי\u0004 שאמר שהקורא את שמע צריך להשמיע לאזנו? — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 בכתוב לשון \u0003\"שמע\",\u0004 ושלדעתו פירוש המלה הוא: שמע ממש, כלומר, \u0003השמע לאזנך מה שאתה מוציא מפיך. ו\u0004אילו ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 האומר שאף אם לא השמיע לאזנו יצא, הוא \u0003סבר\u0004 \u0005[סבור]\u0006 כי הלשון \u0003\"שמע\"\u0004 בא ללמד כי יכול אתה לקרוא את שמע \u0003בכל לשון שאתה שומע\u0004 (מבין), ואין חובה לקרוא את שמע בלשון הקודש דווקא.","\u0003ור' יוסי\u0004 מסכים גם הוא בעיקרון להלכה זו, ואולם לדעתו \u0003תרתי שמע מינה\u0004 \u0005[שתיים\u0006 יכול אתה, \u0005ללמוד ממנה],\u0006 שמאותה מלה נלמד גם היתר הקריאה בכל לשון, וגם את החובה להשמיע לאזנו.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם],\u0006 בדיני תרומות: \u0003חרש המדבר ואינו שומע\u0004 — \u0003לא יתרום,\u0004 משום שצריך לברך על הפרשת התרומה והוא אינו יכול לשמוע את הברכה. \u0003ו\u0004אולם בדיעבד \u0003אם תרם\u0004 — \u0003תרומתו תרומה.\u0004","ועל כך שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כי \u0003חרש המדבר ואינו שומע\u0004 ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 כשר, ואילו \u0003לכתחלה\u0004 — \u0003לא\u0004 ראוי שיעשה כן?","\u0003אמר רב חסדא:\u0004 דעה זו דעת \u0003ר' יוסי היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הקורא את \"שמע\" ולא השמיע לאזנו\u0004 — \u0003יצא,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: לא יצא.\u0004","והוא מפרט: \u0003עד כאן לא\u0004 שמענו במשנתנו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי\u0004 שהחרש \u0003לא יצא, אלא גבי\u0004 \u0005[אצל]\u0006 \u0003קריאת שמע\u0004 שחיוב קריאתה הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אבל\u0004 החשש ב\u0003תרומה\u0004 — \u0003משום ברכה הוא\u0004 שצריך להשמיע את קולו, \u0003ו\u0004ה\u0003ברכה דרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא \u0003ולא בברכה תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 שהפרשת התרומה בעלת תוקף גם בלא הברכה, ועל כן אם כבר עשה מעשה — \u0003יצא ידי חובתו. על ההנחה הזו מקשים:\u0004","\u0003וממאי\u0004 \u0005[וממה]\u0006 אתה מסיק כי שיטת \u0003ר' יוסי היא, דילמא\u0004 \u0005[שמא]\u0006 שיטת \u0003ר' יהודה היא? ו\u0004אף הוא \u0003אמר\u0004 כי \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קריאת שמע נמי\u0004 \u0005[גם כן]\u0006 שאם לא השמיע לאזנו רק ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 יצא, אבל \u0003לכתחלה\u0004 — גם הוא סבור כי \u0003לא\u0004 יצא, ועליו לדאוג לשמוע קולו, ושיטה זו ממש כדברי התנא בתרומות. ו\u0003תדע\u0004 שכך יש לפרש, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"הקורא\u0004 את שמע ולא השמיע לאזנו \u0003\",\u0004 ששנה התנא בסגנון ממנו משמע כי הדיון הוא רק בדרך \u0003דיעבד,\u0004 כלומר, שאדם שכבר קרא כך — \u0003אין\u0004 \u0005[כן]\u0006 יצא, ואולם באופן שיהא ראוי לעשות כן אף \u0003לכתחלה,\u0004 וכגון בסגנון \"קורא אדם את שמע ואינו משמיע לאזנו\" — \u0003לא\u0004 שנה התנא. ואם כן מכשיר ר' יהודה את שאינו שומע את קריאתו רק בדיעבד.","את ההוכחה הזאת דוחים, \u0003אמרי\u0004 \u0005[אומרים]\u0006 ביישוב הדבר: \u0003האי דקתני\u0004 \u0005[זה ששנינו]\u0006 בלשון \u0003\"הקורא\"\u0004 אינו מוכיח שגם ר' יהודה סבור שאין לעשות כן לכתחילה, אלא \u0003להודיעך כחו\u0004 של \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 שב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצא. \u0003דאי\u0004 \u0005[שאם]\u0006 לשיטת \u0003ר' יהודה\u0004 היא, אם כן \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 \u0003יצא.\u0004","על מסקנה זו מקשים אם כן \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת, את המשנה\u0005]\u0006 בדיני תרומות — \u0003כר' יוסי,\u0004 שלדעתו מי שאינו שומע לא יצא אף בדיעבד, \u0003ואלא הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יברך אדם ברכת המזון בלבו, ואם\u0004 עבר ו\u0003בירך\u0004 בלבו — \u0003יצא,\u0004","\u0003מני\u0004 \u0005[\u0006דעת מי היא\u0005]\u0006? אינה \u0003לא\u0004 כשיטת \u0003ר' יוסי ולא\u0004 כשיטת \u0003ר' יהודה. דאי\u0004 \u0005[שאם]\u0006 תאמר ששיטת \u0003ר' יהודה\u0004 היא — \u0003הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר,\u0004 לפי האופן שפירשנו את דעתו כי \u0003לכתחלה נמי\u0004 \u0005[גם כן]\u0006 \u0003יצא\u0004 ואינו צריך להשמיע קולו, ואם כן, מדוע לא יברך לכתחילה בלבו? \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 תאמר ששיטת \u0003ר' יוסי\u0004 היא, הרי לדעתו ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצא! אלא יש לשוב להסבר כי ר' יהודה היא המצריך לכתחילה להשמיע לאוזנו, ולפי זה אף ברייתא זו בברכת המזון שיטת ר' יהודה היא.","על כך מקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר כי שיטת \u0003ר' יהודה\u0004 היא, \u0003ו\u0004אם עשה כן ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 יצא, ואולם \u0003לכתחלה\u0004 — \u0003לא,\u0004","\u0003אלא הא דתני\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]\u0006 בשם \u0003ר' יהודה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: חרש המדבר ואינו שומע\u0004 — \u0003תורם לכתחלה,\u0004 ברייתא זו \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]?\u0006","לפי מה שאמרנו אינה \u0003לא\u0004 כדעת \u0003ר' יהודה ולא\u0004 כדעת \u0003ר' יוסי.\u0004 שכן \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יהודה\u0004 היא — \u0003הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר\u0004 כי ב\u0003דיעבד אין\u0004 \u0005[כן]\u0006 יצא אף שלא השמיע לאוזנו, ואולם \u0003לכתחלה לא\u0004 יצא. ו\u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יוסי\u0004 היא — \u0003הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר\u0004 כי ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 אם לא השמיע לאוזנו \u0003לא\u0004 יצא, ואם כן, ברייתא זו מי אמרה?","\u0003 אלא\u0004 יש לשוב לסברה הקודמת אם כי בשינוי מה, ולומר כי \u0003לעולם\u0004 כדעת \u0003ר' יהודה\u0004 היא, והוא מתיר לחרש לתרום \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן].\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 אין סתירה בין המשנה לברייתא זו, שכן \u0003הא\u0004 — \u0003דידיה, הא\u0004 — \u0003דרביה\u0004 \u0005[זו\u0006 — שיטתו \u0005שלו,\u0006 ו\u0005זו\u0006 — \u0005של רבו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: הקורא את \"שמע\" צריך שישמיע לאזנו, שנאמר: \"שמע ישראל\",\u0004 ומשמעו — צריך בלבד, אבל אם לא עשה כן — יצא בדיעבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' מאיר: הרי הוא אומר \"אשר אנכי מצוך היום על לבבך\"\u0004 וכוונת הדברים לדעתו — \u0003אחר כונת הלב הן הן הדברים,\u0004 והרי שאף לכתחילה אינו צריך לקרוא את שמע בקול רם.","ואולם מאחר שהובאה ברייתא זו אומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן],\u0006 שהובאה שיטת ברייתא זו, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003ר' יהודה כרביה סבירא ליה\u0004 \u0005[כרבו סבור הוא],\u0006 שהחרש כשר רק בדיעבד. \u0003ו\u0004בכל זאת \u0003לא קשיא\u0004 \u0005[קשה]\u0006 להסביר את הברייתות השונות; כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה לחרש אף לכתחילה, שיטת \u0003ר' מאיר\u0004 היא, ו\u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת לכתחילה ומתירה בדיעבד, שיטת \u0003ר' יהודה\u0004 היא.","ומעין בירור דברים זה מובא עוד ענין קרוב בדבר קריאת מגילת אסתר. \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת מגילה: \u0003הכל כשרים לקרות את המגילה, חוץ מחרש, שוטה וקטן. ור' יהודה מכשיר בקטן.\u0004","ומבררים את הענין: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כי \u0003חרש\u0004 ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 כשר? \u0003אמר רב מתנה:\u0004 דעה זו שיטת \u0003ר' יוסי היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הקורא את \"שמע\" ולא השמיע לאזנו\u0004 — \u0003יצא, דברי ר' יהודה.\u0004 ואילו \u0003ר' יוסי אומר: לא יצא.\u0004","על כך שואלים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה שהמשנה במסכת מגילה שיטת \u0003ר' יוסי היא ו\u0004ב\u0003דיעבד נמי\u0004 הוא \u0005[גם כן]\u0006 \u0003לא\u0004 כשר,"],["\u0003דילמא\u0004 \u0005[שמא]\u0006 שיטת \u0003ר' יהודה היא, ולכתחלה הוא\u0004 ש\u0003לא\u0004 יקרא החרש, \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 אם כבר קרא ב\u0003דיעבד\u0004 — \u0003שפיר דמי\u0004 \u0005[ראוי הוא].\u0006","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \"חרש שוטה וקטן\" בביטוי אחד, הרי ש\u0003חרש דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שוטה וקטן. מה שוטה וקטן\u0004 הכל מודים שב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 הם \u0003לא\u0004 כשרים — \u0003אף חרש\u0004 ב\u0003דיעבד\u0004 הוא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 כשר.","את הקושיה הזאת דוחים: \u0003ודילמא הא כדאיתא והא כדאיתא\u0004 \u0005[ושמא זה כמו שיש\u0006 בו, \u0005וזה כמו שיש\u0006 בו\u0005],\u0006 כלומר, אין הוכחה גמורה מצירוף הדברים וכל פרט עומד לעצמו ואין דיניהם זהים.","על כן, מקשים מצד אחר: \u0003ומי מצית לאוקמה כר' יהודה? והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003ר' יהודה מכשיר בקטן, מכלל\u0004 הדברים אתה למד כי ה\u0003רישא לאו\u0004 \u0005[ההתחלה\u0006 של המשנה \u0005לא]\u0006 בשיטת \u0003ר' יהודה היא?!\u0004","ושוב דוחים אף קושיה זו: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 כל המשנה \u0003כולה\u0004 שיטת \u0003ר' יהודה היא ו\u0004מדובר כאן ב\u0003תרי גווני\u0004 \u0005[מיני]\u0006 \u0003קטן, וחסורי מחסרא, והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה בסגנון דבריה, \u0005וכך\u0006 יש \u0005לשנות] :\u0006 \u0003הכל כשרין לקרות את המגילה, חוץ מחרש שוטה וקטן. במה דברים אמורים\u0004 — \u0003בקטן ש\u0004עדיין \u0003לא הגיע ל\u0004גיל \u0003חנוך,\u0004 שבו חובה לחנכו למצוות. \u0003אבל קטן שהגיע לחנוך\u0004 — \u0003אפילו לכתחלה כשר,\u0004 אלו \u0003דברי ר' יהודה, שר' יהודה מכשיר בקטן,\u0004 שדבריו באו להוסיף כאן ולא לחלוק.","על כך מקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את המשנה, \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ופירשת שלדעתו ב\u0003דיעבד אין\u0004 \u0005[כן],\u0006 הוא כשר, ואולם \u0003לכתחלה\u0004 הוא \u0003לא\u0004 כשר. ו\u0003אלא\u0004 אם כן \u0003הא דתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנה]\u0006 \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי,\u0004 ש\u0003חרש המדבר ואינו שומע\u0004 — \u0003תורם לכתחלה,\u0004","\u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 \u0003לא\u0004 שיטת היא \u0003ר' יהודה ולא\u0004 שיטת \u0003ר' יוסי\u0004 היא. שכן \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יהודה\u0004 היא, הלא פירשנו שדעתו היא שחרש ב\u0003דיעבד אין\u0004 \u0005[כן]\u0006 כשר הוא ואולם \u0003לכתחילה\u0004 הוא \u0003לא\u0004 כשר. ו\u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יוסי\u0004 היא, הלא דעתו היא שב\u0003דיעבד\u0004 הוא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 כשר!","קושיה זו דוחים: \u0003אלא מאי\u0004 \u0005[מה\u0006 תפרש\u0005]\u0006 שברייתא זו כשיטת \u0003ר' יהודה\u0004 היא, \u0003ואפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 מתיר הוא בחרש, ו\u0003אלא הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]:\u0006 \u0003לא יברך אדם ברכת המזון בלבו, ואם בירך\u0004 — \u0003יצא, מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006","הלא \u0003לא\u0004 שיטת \u0003ר' יהודה\u0004 היא \u0003ולא\u0004 שיטת \u0003ר' יוסי\u0004 היא. שכן \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יהודה\u0004 היא, \u0003הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר\u0004 ש\u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 יכול אדם לברך בלבו, \u0003ואי\u0004 \u0005[ואם]\u0006 שיטת \u0003ר' יוסי\u0004 היא, \u0003הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד\u0004 הוא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יוצא!","ומשיבים: \u0003לעולם\u0004 אפשר לפרש שהברייתא \"חרש תורם לכתחילה\" שיטת \u0003ר' יהודה היא, ו\u0004לשיטתו \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 מותר. \u0003ו\u0004מה שראינו שבקריאת שמע אינו מתיר קריאה כזו לכתחילה \u0003לא קשיא\u0004 \u0005[קשה]\u0006 שכן \u0003הא\u0004 \u0005[זו]\u0006 — \u0003דידיה\u0004 \u0005[שלו],\u0006 \u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 — \u0003דרביה\u0004 \u0005[של רבו].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: הקורא את \"שמע\" צריך שישמיע לאזנו,\u0004 לפי \u0003שנאמר: \"שמע ישראל\". אמר לו ר' מאיר: הרי הוא אומר\u0004 בפסוק \u0003\"אשר אנכי מצוך היום על לבבך\",\u0004 והרי ש\u0003אחר כונת הלב הן הן הדברים\u0004 ולא אחרי הקריאה בפה. ואם כן, השיטה שבדיעבד מותר לחרש לקרוא — \u0003שיטת ר' אלעזר בן עזריה היא. \u0004","ואולם \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך],\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003ר' יהודה כרביה סבירא ליה\u0004 \u0005[כרבו סבור הוא],\u0006 ואף על פי כן, \u0003לא קשיא\u0004 \u0005[קשה],\u0006 לא תהיה סתירה, שכן \u0003הא\u0004 \u0005[זה]\u0006 — כשיטת \u0003ר' יהודה\u0004 ו\u0003הא\u0004 \u0005[זה]\u0006 — כשיטת \u0003ר' מאיר.\u0004 שאותם מקומות שבהם נראה שחרש פסול מתחילה וכשר בדיעבד — \u0003כשיטת ר' יהודה הם, והברייתא המתירה חרש לכתחילה\u0004 — \u0003כשיטת ר' מאיר היא.\u0004","\u0003אמר רב חסדא אמר רב שילא: הלכה כ\u0004שיטת \u0003ר' יהודה שאמר משום ר' אלעזר בן עזריה, והלכה כ\u0004שיטת \u0003ר' יהודה\u0004 בדבריו במשנתנו.","ומסבירים: \u0003וצריכא\u0004 \u0005[ונצרך]\u0006 לומר שני דברים אלה, אף שלכאורה הם כפל דברים, שכן \u0003אי אשמעינן\u0004 \u0005[אילו השמיע לנו]\u0006 רק ש\u0003הלכה כ\u0004שיטת \u0003ר' יהודה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 (כדרך שהועלתה אפשרות פירוש כזו) ש\u0003אפילו לכתחלה\u0004 מתיר ר' יהודה, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003הלכה כר' יהודה שאמר משום\u0004 רבו \u0003ר' אלעזר בן עזריה\u0004 שלכתחילה צריך להשמיע לאזנו.","\u0003ואי אשמעינן\u0004 \u0005[ואילו השמיע לנו]\u0006 רק את הפסק ש\u0003הלכה כר' יהודה שאמר משום ר' אלעזר בן עזריה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ומפרש ש\"צריך שישמיע לאזנו\" משמעו ש\u0003צריך\u0004 לעשות כן לכתחילה \u0003ואין לו תקנה\u0004 בדיעבד אם לא עשה. ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003הלכה כר' יהודה\u0004 שלכתחילה צריך, ובדיעבד — \u0003מותר.\u0004","\u0003אמר רב יוסף: מחלוקת\u0004 זו אם חרש יוצא ידי חובה, הרי היא רק \u0003בקריאת שמע, אבל בשאר מצות, דברי הכל\u0004 — \u0003לא יצא\u0004 אם אינו שומע דכתיב [שנאמר]: \u0003\"הסכת ושמע ישראל\"\u0004 (דברים כז, ט), שיש להקשיב ולשמוע.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003לא יברך אדם ברכת המזון בלבו, ואם בירך\u0004 — \u0003יצא.\u0004 הרי שאף בשאר מצוות חובת השמיעה אינה אלא לכתחילה! \u0003אלא\u0004 על כן יש לתקן את דברי רב יוסף ולומר כי \u0003אי אתמר\u0004 \u0005[אם נאמר]\u0006 — \u0003הכי אתמר\u0004 \u0005[כך נאמר]\u0006 ש\u0003אמר רב יוסף:\u0004 ה\u0003מחלוקת\u0004 בחרש היא רק לגבי \u0003קריאת שמע, דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"שמע ישראל\", אבל בשאר מצות\u0004 — \u0003דברי הכל\u0004 שהחרש \u0003יצא\u0004 ידי חובה.","על כך מקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"הסכת ושמע ישראל\"!\u0004","ומשיבים: הפסוק \u0003ההוא בדברי תורה כתיב\u0004 \u0005[נאמר],\u0006 שיש לשים לב לכתוב בתורה.","שנינו במשנה שאם \u0003קרא ולא דקדק באותיותיה\u0004 מחלוקת תנאים היא, שלדעת ר' יוסי יצא ולדעת ר' יהודה לא יצא. וכן נחלקו בענין הקורא את שמע בלא להשמיע לאזנו, שלדעת התנא קמא יצא ואילו לדעת ר' יוסי לא יצא.","ועל כך \u0003אמר ר' טבי אמר ר' יאשיה: הלכה כדברי שניהם להקל. \u0004","אגב שהובאו דברים בשמו של חכם זה מביאים דבר נוסף בשמו. \u0003ואמר ר' טבי אמר ר' יאשיה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שלש הנה לא תשבענה... שאול ועצר רחם\"\u0004 (משלי ל, טו–טז). וכן יש לתמוה: \u0003וכי מה ענין שאול אצל רחם? אלא\u0004 סמיכות זו באה \u0003לומר לך: מה רחם מכניס ומוציא, אף שאול\u0004 (הקבר) \u0003מכניס ומוציא\u0004 בתחיית המתים.","\u0003והלא דברים קל וחומר: ומה רחם שמכניסין בו בחשאי, מוציאין ממנו בקולי קולות\u0004 בשעת הלידה. \u0003שאול שמכניסין בו\u0004 את המת \u0003בקולי קולות\u0004 בשעת קבורתו, \u0003אינו דין שמוציאין ממנו בקולי קולות?\u0004 ו\u0003מכאן תשובה\u0004 (סתירה) \u0003לאומרים\u0004 ש\u0003אין תחיית המתים מן התורה,\u0004 שהרי בפסוק זה מרומזת תחיית המתים.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' אושעיא קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא\u0004 ברייתא זו: מה שנאמר \u0003\"וכתבתם\u0004 על מזוזות ביתך ובשעריך\u0003\"\u0004 (דברים ו, ט) יש לפרשו כאילו היה כתוב \"וכתבת תם\" — בשלימות, ו\u0003הכל\u0004 צריך להיות \u0003בכתב, אפילו צואות.\u0004 שיש לכתוב במזוזה או בתפילין לא רק את הפסוקים המדברים בתוכן הפרשה, אלא גם את הציווי לכתוב תפילין ומזוזות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: זה ש\u0003אמר לך\u0004 ברייתא זו, \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 — שיטת \u0003ר' יהודה היא.\u0004 ש\u0003אמר\u0004 ר' יהודה \u0003גבי\u0004 \u0005[אצל]\u0006 ענין \u0003סוטה\u0004 ש\u0003אלות\u0004 (קללות) הוא \u0003כותב,\u0004 ואולם \u0003צואות אינו כותב.\u0004 שלדעתו יש לכתוב במגילת הסוטה רק את הקללות ולא את הצוואות—ההוראות כיצד משקים את הסוטה. ולשיטתו יש טעם ללמדנו שבמזוזה יש לכתוב אף את הצוואות. וטעם ההבדל, שכן \u0003התם\u0004 \u0005[שם]\u0006 בסוטה \u0003הוא דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכתב את האלות האלה\u0004 הכהן בספר\u0003\"\u0004 (במדבר ה, כג), ומשמע שרק את האלות הוא כותב, ולא יותר, \u0003אבל הכא דכתיב\u0004 \u0005[כאן,\u0006 במצות מזוזה \u0005שנאמר]\u0006 \u0003\"וכתבתם\",\u0004 יש לכתוב הכל, ולכך \u0003אפילו צואות נמי\u0004 \u0005[גם כן]\u0006 כותב.","על כך מקשים: \u0003אטו טעמיה\u0004 \u0005[האם טעמו]\u0006 של \u0003ר' יהודה\u0004 הוא \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת סוטה הלשון \u0003\"וכתב\"\u0004 ולא \"וכתבתם\"? והלא \u0003טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' יהודה משום דכתיב\u0004 \u0005[ש\u0006בסוטה \u0005נאמר]\u0006 \"את \u0003האלות\u0004 האלה\", והכוונה שרק \u0003אלות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 צריך לכתוב, ואולם \u0003צואות\u0004 — \u0003לא.\u0004 ואם כן, אין צורך כלל להדגיש את המלה \"וכתבתם\" במצוות מזוזה.","על כך משיבים: \u0003אצטריך\u0004 \u0005[צריך],\u0006 כן שמא \u0003סלקא דעתך אמינא נילף\u0004 \u0005[יעלה על דעתך לומר\u0006 ש\u0005נלמד]\u0006 \u0003\"כתיבה\" \"כתיבה\"\u0004 בגזירה שווה \u0003מהתם\u0004 \u0005[משם]\u0006 ונאמר כך: \u0003מה התם\u0004 \u0005[שם]\u0006 \u0003אלות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003צואות לא, אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 — \u0003צואות לא.\u0004 על כן \u0003כתב רחמנא\u0004 היה צורך להדגיש \u0003\"וכתבתם\"\u0004 — \u0003אפילו צואות\u0004 כתיבה תמה, שלימה.","מעין דברים אלה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב עובדיה קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא:\u0004 מה שנאמר \u0003\"ולמדתם\u0004 אותם את בניכם\u0003\"\u0004 (דברים יא, יט), הרי זה בא ללמד \u0003שיהא למודך תם\u0004 — \u0003שיתן ריוח בין הדבקים,\u0004 כלומר, שיפריד בין המילים ויאמר כל אחת מהן בבהירות.","\u0003עני\u0004 \u0005[ענה]\u0006 \u0003רבא בתריה\u0004 \u0005[אחריו]\u0006 בהסבר: \u0003כגון\u0004 שידגיש \u0003\"על לבבך\"\u0004 ולא יקראנה כמלה אחת, וכן \u0003\"על לבבכם\", \"בכל לבבך\", \"בכל לבבכם\", \"עשב בשדך\", \"ואבדתם מהרה\", \"הכנף פתיל\",\u0004 וכן \u0003\"אתכם מארץ\",\u0004 שמתוך דמיון המבטא בין ההברה האחרונה והראשונה נעלם מובן המילים.","באותו ענין \u0003אמר ר' חמא בר' חנינא: כל הקורא קריאת שמע ומדקדק באותיותיה מצננין לו גיהנם, שנאמר: \"בפרש שדי מלכים בה תשלג בצלמון\"\u0004 (תהלים סח, טו), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בפרש\" אלא \"בפרש\",\u0004 כלומר, כאשר אתה מפרש ומבטא כראוי את שם ה' (\"שדי\") — \u0003יקויים בך \"תשלג בצלמון\", ואל תקרי\u0004 \u0005[תקרי]\u0006 \u0003\"בצלמון\" אלא \"בצלמות\",\u0004 בגיהנום, כלומר, זכות זו תצנן לך את הגיהנום.","\u0003ו\u0004עוד \u0003אמר ר' חמא בר' חנינא: למה נסמכו\u0004"],["\u0003אהלים לנחלים\u0004 בפסוק \"\u0003כנחלים נטיו כגנות עלי נהר כאהלים נטע ה'\u0004, כארזים עלי מים\" (במדבר כד, ו) — \u0003לומר לך: מה נחלים מעלין את האדם מטומאה לטהרה\u0004 כשהוא טובל במימיהם — \u0003אף אהלים\u0004 של תורה \u0003מעלין את האדם מכף חובה לכף זכות.\u0004","שנינו במשנתינו \u0003\"הקורא למפרע לא יצא,\u0004 קרא וטעה יחזור למקום שטעה\",","\u0003ובענין זה של טעות בקריאת שמע מסופר: ר' אמי ור' אסי הוו קא קטרין ליה גננא\u0004 \u0005[היו קושרים לו חופה,\u0006 עוסקים בצרכי חופתו] של \u0003ר' אלעזר. אמר להו\u0004 \u0005[להם]:\u0006 \u0003אדהכי והכי איזיל\u0004 \u0005[בין כה וכה\u0006 עד שתסיימו אלך ] \u0003ואשמע מלתא דבי מדרשא\u0004 \u0005[דבר בבית המדרש],\u0006 \u0003ואיתי ואימא לכו\u0004 \u0005[ואבוא ואומר לכם].\u0006 \u0003אזל אשכחיה\u0004 \u0005[הלך\u0006 ומצאו] \u0003לתנא (\u0004חוזר המשניות) \u0003דקתני קמיה\u0004 \u0005[ש\u0006הוא \u0005שונה\u0006 ואומר \u0005לפני]\u0006 \u0003ר' יוחנן\u0004 תוספתא זו:","\u0003קרא\u0004 קריאת שמע \u0003וטעה ואינו יודע להיכן\u0004 בדיוק \u0003טעה,\u0004 אם היה המקום שנזכר בו \u0003באמצע הפרק\u0004 — \u0003יחזור לראש\u0004 (לתחילת) הקריאה. ואם היה זה \u0003בין פרק לפרק,\u0004 אך אינו זוכר בין איזה פרקים — \u0003יחזור לפרק\u0004 (ההפסק) ה\u0003ראשון.\u0004 וכן אם \u0003טעה בין כתיבה לכתיבה,\u0004 בין הפסוק \"וכתבתם על מזוזות ביתך ובשעריך\" שבפרשה הראשונה (דברים ו, ט) לפסוק \"וכתבתם על מזוזות ביתך ובשעריך\" שבפרשה השניה (שם יא, כ) — \u0003יחזור לכתיבה ראשונה.\u0004","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: לא שנו\u0004 דבר זה \u0003אלא\u0004 במקרה \u0003שלא פתח ב\"למען ירבו ימיכם\"\u0004 (שם יא כא), \u0003אבל\u0004 אם \u0003פתח\u0004 כבר \u0003ב\"למען ירבו ימיכם\" — סרכיה נקט ואתי\u0004 \u0005[\u0006את \u0005שגרתו אחז והלך],\u0006 שיש לשער שמתוך שיגרת הקריאה הגיע כבר לפרשה שניה ובה טעה,","\u0003אתא\u0004 \u0005[בא]\u0006 ר' אלעזר \u0003ואמר להו\u0004 \u0005[להם]\u0006 מה ששמע. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אלו לא באנו אלא לשמוע דבר זה\u0004 — \u0003דיינו.\u0004","השאלה מה מידת הריכוז לכוונה הראויה בשעת קריאת שמע היא עניינה של משנה זו. \u0003האומנין\u0004 כשהם עסוקים במלאכתם — \u0003קורין\u0004 (קוראים) קריאת שמע אם הם עומדים \u0003בראש האילן ובראש הנדבך\u0004 (שורת אבנים או עצים) בבנין שהם בונים. \u0003מה שאינן רשאין לעשות כן בתפלה\u0004 הדורשת כוונת הלב.","ובנושא אחר אמרו: \u0003חתן פטור מקריאת שמע לילה הראשונה של\u0004 נישואיו (שהיה כרגיל אור ליום חמישי) \u0003ועד מוצאי שבת אם\u0004 עדיין \u0003לא עשה מעשה\u0004 (ביאה), משום שהוא מוטרד במחשבה על הביאה ועל כל הקשור בכך. \u0003ו\u0004אולם סיפרו \u0003מעשה ברבן גמליאל שנשא אשה וקרא\u0004 קריאת שמע אף ב\u0003לילה הראשונה. אמרו לו תלמידיו:\u0004 והלא \u0003למדתנו רבינו שחתן פטור מקריאת שמע?\u0004 ענה להם: אף על פי כן, \u0003איני שומע לכם\u0004 שלא לקרוא קריאת שמע, ובכך \u0003לבטל הימני\u0004 (ממני\u0005)\u0006 קבלת עול \u0003מלכות שמים אפילו שעה אחת.\u0004","ובענין זה של האומנים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003האומנין\u0004 כשהם עסוקים במלאכתם — \u0003קורין\u0004 קריאת שמע אם הם עומדים \u0003בראש האילן ובראש הנדבך\u0004 שהם בונים. \u0003ו\u0004מותר להם שיהיו \u0003מתפללין\u0004 כאשר הם עומדים \u0003בראש הזית ובראש התאנה\u0004, שענפי עצים אלה מרובים וסמוכים, והאומן יכול לעמוד שם ולהתפלל בכוונה. \u0003ו\u0004אילו ב\u0003שאר כל האילנות\u0004 — \u0003יורדים למטה ומתפללין. ו\u0004אולם \u0003בעל הבית בין כך ובין כך\u0004 בין בעץ זית בין בשאר אילנות, \u0003יורד למטה ומתפלל, לפי שאין דעתו מיושבת עליו\u0004 כראוי. ואף על פי שלפועלים התירו, בעל הבית היכול להרשות לעצמו לרדת מן האילן — \u0003לא התירו לו בכך.\u0004","\u0003רמי ליה\u0004 \u0005[הקשה לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב מרי ברה\u0004 \u0005[בנה]\u0006 של \u0003בת שמואל לרבא, תנן\u0004 \u0005[שנינו\u0006 במשנתינו\u0005]:\u0006 \u0003האומנין קורין בראש האילן ובראש הנדבך, אלמא\u0004 \u0005[מכאן ]\u0006 ש\u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003כונה,\u0004 ודיו בקריאה בלבד. \u0003ורמינהי\u0004 \u0005[ואנו משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003הקורא את שמע צריך שיכוין את לבו, שנאמר: \"שמע ישראל\". ולהלן\u0004 בספר דברים \u0003הוא אומר \"הסכת ושמע ישראל\"\u0004 (כז, ט), ו\u0003מה להלן ב\"הסכת\"\u0004 (הקשבה ותשומת לב) \u0003אף כאן ב\"הסכת\".\u0004","\u0003אשתיק\u0004 \u0005[שתק]\u0006 רבא, שלא מצא לכך תשובה, ואולם \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003מידי שמיע לך בהא\u0004 \u0005[שמעת דבר ב\u0006ענין \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת: והוא\u0004 שהתירו לאומנים לקרוא בראש האילן רק כ\u0003שבטלין ממלאכתן וקורין,\u0004 שאז ביכולתם לכוון לבם.","על כך מקשים: \u0003והתניא\u0004 \u0005[והלא שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003בית הלל אומרים\u0004 שהעובדים \u0003עוסקים במלאכתן וקורין!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שצריכים להפסיק ממלאכתם — הרי זה מדובר \u0003בפרק ראשון\u0004 של קריאת שמע, \u0003והא\u0004 \u0005[זה]\u0006 \u0003שעוסקים במלאכתם וקוראים\u0004 — \u0003בפרק שני.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003הפועלים שהיו עושין מלאכה אצל בעל הבית,\u0004 הריהם חייבים להיות \u0003קורין קריאת שמע ומברכין\u0004 את הברכות ש\u0003לפניה ולאחריה. ו\u0004כן כש\u0003אוכלין פתן מברכין\u0004 את הברכות ש\u0003לפניה ולאחריה\u0004, \u0003ו\u0004כן \u0003מתפללין תפלה של שמונה עשרה. אבל אין\u0004 הם \u0003יורדין לפני התיבה\u0004 כשליחי ציבור, \u0003ו\u0004הכהנים שביניהם \u0003אין נושאין כפיהם,\u0004 כדי שלא להיבטל מן המלאכה.","על כך מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 שהפועלים מתפללים תפילה קצרה שהיא \u0003מעין שמונה עשרה,\u0004 ואין הם מתפללים תפילת שמונה עשרה שלימה! ומשיבים: אין זה קשה, \u0003הא\u0004 \u0005[זה]\u0006 המחייב להתפלל שמונה עשרה - הוא \u0003רבן גמליאל\u0004, שלדעתו יש תמיד להתפלל שמונה עשרה ברכות שלמות. \u0003הא\u0004 \u0005[זה]\u0006 המתיר לקצר - הוא \u0003ר' יהושע\u0004, המתיר להתפלל אף \"מעין\" שמונה עשרה.","על כך מקשים: \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יהושע\u0004 היא ברייתא זו, אם כן \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 שיאמר דווקא ב\u0003פועלים?\u0004 אף \u0003כל אדם נמי\u0004 \u0005[גם כן]\u0006 מתפלל מעין שמונה עשרה!","\u0003אלא\u0004 יש לומר כי \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 כשיטת \u0003רבן גמליאל, ולא קשיא\u0004 \u0005[קשה]\u0006 מזו על זו, שכך יש לפרש: \u0003כאן\u0004 שצריכים הפועלים להתפלל רק מעין שמונה עשרה, הרי זה מדובר \u0003ב\u0004פועלים ה\u0003עושין\u0004 (העובדים) \u0003בשכרן\u0004 ומקבלים משכורת שלימה מבעל הבית מלבד סעודתם על חשבונו. ו\u0003כאן\u0004 שחייבום להתפלל שמונה עשרה שלמות, הרי זה מדובר \u0003ב\u0004פועלים ה\u0003עושין רק ב\u0004שכר \u0003סעודתן,\u0004 שצריכים אלו להתפלל שמונה עשרה ברכות שלמות.","\u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הפועלים שהיו עושים\u0004 ב\u0003מלאכה אצל בעל הבית\u0004 — \u0003קורין קריאת שמע ומתפללין. ו\u0004כש\u0003אוכלין פתן\u0004 — \u0003אין מברכים לפניה,\u0004 שהברכה שלפני האוכל היא מדברי חכמים, \u0003אבל מברכין לאחריה,\u0004 כיון שהיא מן התורה, ואולם רק \u0003שתים,\u0004 כלומר, רק שתי ברכות מתוך שלש ברכותיה של ברכת המזון \u0003כיצד? ברכה ראשונה\u0004 מברכים \u0003כתקונה\u0004 בשלימותה , ובברכה ה\u0003שניה פותח בברכת הארץ\u0004 כרגיל \u0003ו\u0004אולם \u0003כוללין\u0004 את \u0003\"בונה ירושלים\" בברכת הארץ,\u0004 ואין מברכים יותר.","\u0003במה דברים אמורים\u0004 — \u0003ב\u0004שהיו הפועלים \u0003עושין בשכרן, אבל\u0004 אם היו \u0003עושין בסעודתן או שהיה בעל הבית מיסב עמהן\u0004 — \u0003הרי בגללו מברכין\u0004 כולה \u0003כתיקונה.\u0004","שנינו במשנה ש\u0003חתן פטור מקריאת שמע\u0004 בלילה הראשון לנישואיו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא מקור להלכה זו: מה שנאמר בקריאת שמע \"בשבתך בביתך ובלכתך בדרך\", מפרשים: \u0003\"בשבתך בביתך\"\u0004 הרי זה בא למעט — \u0003פרט לעוסק במצוה,\u0004 שאינו יושב במנוחה בביתו. \u0003\"ובלכתך בדרך\"\u0004 — \u0003פרט לחתן.\u0004 ו\u0003מכאן אמרו: הכונס\u0004 (נושא) \u0003את הבתולה\u0004 — \u0003פטור\u0004 מקריאת שמע, \u0003ו\u0004הנושא \u0003את האלמנה\u0004 — \u0003חייב.\u0004","על כך שואלים בגמרא: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003משמע,\u0004 כיצד למדים מן הפסוק הלכה זו בחתן? \u0003אמר רב פפא:\u0004 למדים זאת מן ההשוואה \u0003כי\u0004 \u0005[כמו]\u0006 \u0003דרך, מה דרך\u0004 הריהי \u0003רשות,\u0004 שכן בידו ללכת או שלא ללכת כרצונו, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 החובה לקרוא בכל עיסוק של \u0003רשות, אבל העסוק בענין של מצוה כגון החתן\u0004 — \u0003פטור. על כך מקשים:\u0004","\u0003מי לא עסקינן דקאזיל\u0004 \u0005[האם אין אנו עוסקים\u0006 בפסוק אף \u0005שהיה הולך]\u0006 \u0003לדבר מצוה, ואפילו הכי אמר רחמנא\u0004 \u0005[כך אמרה התורה]:\u0006 \u0003ליקרי\u0004 \u0005[שיקרא],\u0006 שמעצם לשון הכתוב נראה שבכל דרך שהולך בה — \u0003רשות או מצוה\u0004 — \u0003חייב לקרוא. ומסבירים:\u0004","\u0003אם כן, לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"בלכת\"\u0004 (\"ובלכת בדרך\"), \u0003מאי\u0004 \u0005[מהו]\u0006 הביטוי המודגש \u0003\"בלכתך\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003בלכת\u0004 \u0005[בהליכה]\u0006 \u0003דידך\u0004 \u0005[שלך]\u0006 \u0003הוא דמחייבת\u0004 \u0005[שאתה מחוייב],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם זו הליכה של \u0003מצוה\u0004 — \u0003פטירת\u0004 \u0005[פטור אתה].\u0006"],["על כך מקשים: \u0003אי הכי מאי איריא\u0004 \u0005[אם כך, מה שייך\u0006 דווקא\u0005]\u0006 שיהא פטור זה \u0003הכונס את הבתולה? אפילו כונס את האלמנה נמי\u0004 \u0005[גם כן]\u0006 הרי הוא עושה מצווה וצריך להיות פטור.","על כך משיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 הנושא בתולה — \u0003טריד\u0004 \u0005[טרוד\u0006 במחשבתו\u0005],\u0006 \u0003והכא\u0004 \u0005[כאן]\u0006 הנושא אלמנה — \u0003לא טריד\u0004 \u0005[אינו מוטרד].\u0006","על כך מקשים: \u0003אם משום טרדא\u0004 אתה פוטרו מלקרוא, אם כן \u0003אפילו טבעה ספינתו בים נמי\u0004 יהיה פטור מן הקריאה, שהרי בוודאי מחשבתו מוטרדת, ו\u0003אלמה\u0004 \u0005[משום מה]\u0006 \u0003אמר ר' אבא בר זבדא אמר רב: אבל חייב בכל מצות האמורות בתורה, חוץ מן התפילין שהרי נאמר בהן\u0004 בתפילין לשון \u0003\"פאר\", שנאמר\u0004 ביחזקאל שחובה היתה עליו שלא להתאבל \u0003\"פארך חבוש עליך\"\u0004 (יחזקאל כד, יז). ואם האבל שוודאי מוטרד וכואב חייב לקרוא קריאת שמע, הרי שאין טירדה קובעת כלל לענין זה!","על כך משיבים: \u0003התם\u0004 \u0005[שם]\u0006 ה\u0003טרדא\u0004 היא של \u0003רשות,\u0004 שטרדת האבל באבלו אינה מצוה כשלעצמה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בחתן ה\u0003טרדא\u0004 מקורה ב\u0003מצוה\u0004 עצמה.","עוד מסופר על דבר יוצא דופן שעשה רבן גמליאל ש\u0003רחץ לילה הראשון שמתה אשתו. אמרו לו תלמידיו:\u0004 והלא \u0003למדתנו רבינו שאבל אסור לרחוץ?\u0004 ענה להם: אני \u0003איני כשאר בני אדם, אסטניס\u0004 \u0005[מעודן]\u0006 \u0003אני,\u0004 וחוסר רחיצה הריהו בשבילי כאב גופני ממש, ואף האבל אינו צריך לסבול כאבים בשל אבלו.","\u0003ו\u0004עוד דבר יוצא דופן ספרו עליו ש\u0003כשמת טבי עבדו קבל עליו תנחומים,\u0004 כדרך שמקבלים על קרוב משפחה. \u0003אמרו לו תלמידיו:\u0004 והלא \u0003למדתנו רבינו שאין מקבלים תנחומים על העבדים? אמר להם\u0004 רבן גמליאל לתלמידיו: \u0003אין טבי עבדי כשאר כל העבדים,\u0004 אלא \u0003כשר היה\u0004 וראוי לכבדו כאילו היה קרובי.","לענין קריאת שמע בליל החתונה, אמרו חכמים ש\u0003חתן אם רוצה\u0004 בכל זאת \u0003לקרות קריאת שמע\u0004 ב\u0003לילה הראשון\u0004 — \u0003קורא,\u0004 ואילו \u0003רבן שמעון בן גמליאל אומר: לא כל הרוצה ליטול את השם\u0004 (הפרסום, הכבוד) שהוא ירא שמים \u0003יטול,\u0004 ולא כל אדם רשאי לעשות כן.","\u0003ובענין זה של רבן גמליאל שרחץ לילה ראשון שמתה\u0004 אשתו שואלים \u0003: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן גמליאל\u0004 שלא נהג באבלות ורחץ בלילה הראשון לאבלו? ומשיבים: \u0003קסבר\u0004 \u0005[הוא סבור],\u0006 שהאבל החמור על המת ביום הראשון (הנקרא אנינות), אינו אלא ביום המוות בלבד, אבל \u0003אנינות לילה\u0004 שלאחר מכן — אינה אלא \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004והפכתי חגיכם לאבל וכל שיריכם לקינה והעליתי על כל מתנים שק ועל כל ראש קרחה, ושמתיה כאבל יחיד \u0003ואחריתה כיום מר\"\u0004 (עמוס ח, י), הרי שאף אבל כבד עיקרו רק באותו יום (\"כיום מר\") ואנינות הלילה הינה אך מדברי חכמים. \u0003ובמקום איסטניס לא גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 שיצער את עצמו באנינות.","שנינו במשנה ש\u0003כשמת טבי עבדו\u0004 של רבן גמליאל קיבל עליו תנחומים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: על \u0003עבדים ושפחות\u0004 שמתו \u0003אין עומדין עליהם בשורה\u0004 לנחם אבלים, \u0003ואין אומרים עליהם ברכת אבלים\u0004 או \u0003תנחומי אבלים.\u0004","מסופר \u0003מעשה ומתה שפחתו של ר' אליעזר נכנסו תלמידיו לנחמו\u0004 על מותה. \u0003כיון שראה אותם\u0004 שהם נכנסים \u0003עלה לעלייה\u0004 (לקומה השניה), \u0003ועלו\u0004 הם \u0003אחריו. נכנס לאנפילון\u0004 (מסדרון קטן), \u0003נכנסו אחריו. נכנס לטרקלין\u0004 (חדר מטות מקושט), ו\u0003נכנסו אחריו.\u0004 כיון שראה שהם מלוים אותו לכל מקום \u0003אמר להם: כמדומה אני שאתם נכוים בפושרים,\u0004 כלומר, דייכם ברמז בלבד, וכשעליתי לעליה הייתם צריכים להבין שאיני רוצה לקבל מכם תנחומים, \u0003עכשיו\u0004 רואה אני ש\u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם נכוים אפילו בחמי חמין,\u0004 וכי \u0003לא כך שניתי לכם: עבדים ושפחות אין עומדים עליהם בשורה, ואין אומרים עליהם\u0004 לאדוניהם לא \u0003ברכת אבלים ולא תנחומי אבלים?\u0004 שכן אין שייכותם לבעליהם כשייכות משפחתית כלל. \u0003אלא מה אומרים עליהם?\u0004 — \u0003כשם שאומרים לו לאדם על שורו ועל חמורו שמתו — \"המקום ימלא לך חסרונך\", כך אומרים לו על עבדו ועל שפחתו\u0004 שמתו \u0003\"המקום ימלא לך חסרונך\",\u0004 שהרי אינם קשורים לבעליהם אלא בקשר ממוני בלבד.","\u0003תניא אידך\u0004 \u0005[שנינו\u0006 בברייתא \u0005אחרת]:\u0006 \u0003עבדים ושפחות אין מספידים אותן. ר' יוסי אומר: אם עבד כשר הוא\u0004 — \u0003אומרים עליו\u0004 מעין הספד: \u0003\"הוי איש טוב ונאמן ונהנה מיגיעו\". אמרו לו: אם כן, מה הנחת לכשרים?\u0004 ששבחים אלה אף ישראלי כשר דיו להשתבח בהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין קורין\u0004 (קוראים) \u0003\"אבות\" אלא לשלשה\u0004 (אברהם, יצחק ויעקב) ולא לבני יעקב, \u0003ואין קורין \"אמהות\" אלא לארבע\u0004 (שרה, רבקה, רחל ולאה).","על כך שואלים: \u0003אבות מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דלא ידעינן אי\u0004 \u0005[שאיננו יודעים אם]\u0006 \u0003מראובן קא אתינן\u0004 \u0005[באנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משמעון קא אתינן\u0004 \u0005[באנו]\u0006 ולכן אי אפשר לומר על דרך משל \"אבינו ראובן\", ואם כן הרי \u0003אמהות נמי לא ידעינן אי\u0004 \u0005[איננו יודעים אם]\u0006 \u0003מרחל קא אתינן\u0004 \u0005[באנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מלאה קא אתינן\u0004 \u0005[באנו],\u0006 ואם כן אף רחל ולאה לא תיקראנה בפינו \"אמהות\"! \u0003אלא\u0004 יש לומר שלא מתוך ספק אין נחשבים בני יעקב ל\"אבות\", אלא \u0003עד הכא חשיבי, טפי לא חשיבי\u0004 \u0005[עד כאן,\u0006 עד יעקב, חשובים הם להיקרא אבות, יותר, כלומר, מכאן והלאה, אינם חשובים להיקרא כך\u0005].\u0006","דבר זה היה הקדמה, לומר שאף על פי שבדרך כבוד קראו לאדם מבוגר \"אבא פלוני\" מכל מקום לענין עבדים \u0003תניא אידך\u0004 \u0005[שנינו\u0006 בברייתא \u0005אחרת]:\u0006 \u0003עבדים ושפחות אין קורין אותם\u0004 לא \u0003\"אבא פלוני\" ו\u0004לא \u0003\"אמא פלונית\". ו\u0004אולם העבדים \u0003של רבן גמליאל היו קורים\u0004 אותם \u0003\"אבא פלוני\" ו\"אמא פלונית\".\u0004","על כך שואלים: וכי מביאים \u0003מעשה\u0004 באותו הקשר על מנת \u0003לסתור\u0004 את ההלכה אשר הובאה קודם לכן?! ומשיבים: אין זו סתירה, אלא עבדי רבן גמליאל \u0003משום דחשיבי\u0004 \u0005[ש\u0006היו \u0005חשובים]\u0006 פנו גם אליהם בלשון כבוד.","מענין תפילה וקריאת שמע שדנו בהם, מביאים דברי אגדה. \u0003אמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה משמעו של הכתוב \u0003\"כן אברכך בחיי בשמך אשא כפי\"\u0004 (תהלים סג, ה)? \u0003\"כן אברכך בחיי\"\u0004 — \u0003זו קריאת שמע\u0004, \u0003\"בשמך אשא כפי\"\u0004 — \u0003זו תפלה\u0004 הנקראת נשיאת כפיים אל ה'. \u0003ואם עושה כן\u0004 (קורא ומתפלל) — \u0003עליו הכתוב אומר: \"כמו חלב ודשן תשבע נפשי\"\u0004 (שם שם, ו). \u0003ולא עוד אלא\u0004 שניתן לו שכר על כך \u0003שנוחל שני עולמים\u0004 — \u0003העולם הזה והעולם הבא, שנאמר: \"ושפתי רננות יהלל פי\"\u0004 (שם), ו\"רננות\" משמעו שתי רננות — בעולם הזה ובעולם הבא.","מסופר כי \u0003ר' אלעזר בתר\u0004 \u0005[אחר]\u0006 שהיה \u0003מסיים צלותיה\u0004 \u0005[תפילתו]\u0006 היה מוסיף עוד תפילה פרטית ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו, שתשכן בפורינו\u0004 (בגורלנו\u0005)\u0006 \u0003אהבה ואחוה ושלום וריעות. ותרבה גבולנו בתלמידים ותצליח סופנו\u0004 שתהא לנו \u0003אחרית\u0004 טובה \u0003ותקוה. ותשים חלקנו בגן עדן, ותקננו בחבר טוב ויצר טוב בעולמך. ונשכים ונמצא יחול לבבנו (\u0004רצוננו ותקותנו) שנגיע \u0003ליראה את שמך, ותבא לפניך קורת נפשנו\u0004 (כלומר, תשים לב לבקשתנו שתהא לנו נחת רוח בעולם הזה) \u0003לטובה\".\u0004","וכן מסופר כי \u0003ר' יוחנן בתר\u0004 \u0005[אחר]\u0006 שהיה \u0003מסיים צלותיה\u0004 \u0005[תפילתו]\u0006 היה מוסיף עוד תפילה פרטית ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו, שתציץ בבשתנו, ותביט ברעתנו, ותתלבש ברחמיך, ותתכסה בעזך, ותתעטף בחסידותך, ותתאזר בחנינותך, ותבא לפניך מדת טובך וענותנותך\".\u0004","וכן מסופר כי \u0003ר' זירא בתר\u0004 \u0005[אחר]\u0006 שהיה \u0003מסיים צלותיה\u0004 \u0005[תפילתו]\u0006 היה מוסיף עוד תפילה ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו, שלא נחטא ולא נבוש ולא נכלם מאבותינו\".\u0004 כלומר, שמעשינו לא יביישו את מעשי האבות, ולא נצטרך להתבייש מהם.","\u0003ר' חייא בתר\u0004 \u0005[אחר]\u0006 \u0003דמצלי\u0004 \u0005[שהתפלל]\u0006 היה מוסיף עוד תפילה ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו, שתהא תורתך אומנותנו, ואל ידוה לבנו, ואל יחשכו עינינו\".\u0004","\u0003רב בתר צלותיה\u0004 \u0005[אחר תפילתו]\u0006 היה מתפלל עוד ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו שתתן לנו חיים ארוכים, חיים של שלום, חיים של טובה, חיים של ברכה, חיים של פרנסה, חיים של חלוץ עצמות,\u0004 כלומר חיים שתהיה בהם אפשרות לנוע ממקום למקום ולא להיות כבולים למקום אחד בלבד, \u0003חיים שיש בהם יראת חטא, חיים שאין בהם בושה וכלימה, חיים של עושר וכבוד, חיים שתהא בנו אהבת תורה ויראת שמים, חיים שתמלא לנו את כל משאלות לבנו לטובה\".\u0004","\u0003רבי בתר צלותיה\u0004 \u0005[אחר תפילתו]\u0006 היה מתפלל עוד ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו ואלהי אבותינו, שתצילנו מעזי פנים ומעזות פנים\u0004 בכלל, \u0003מאדם רע, מפגע רע, מיצר רע, מחבר רע, משכן רע, ומשטן המשחית, ומדין קשה ומבעל דין קשה, בין שהוא בן ברית\u0004 (יהודי) \u0003בין שאינו בן ברית\".\u0004","ומעירים שתפילה זו היה רבי מתפלל בכל יום \u0003ואף על גב דקיימי קצוצי עליה\u0004 \u0005[שהיו עומדים שוטרים\u0006 מטעם המלכות לשמור עליו] על \u0003רבי\u0004 ביקש שלא להגיע לקטטה ולמכשול מעזות פנים.","\u0003רב ספרא בתר צלותיה\u0004 \u0005[אחר תפילתו]\u0006 היה מתפלל עוד ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"יהי רצון מלפניך ה' אלהינו, שתשים שלום\u0004"],["\u0003בפמליא של מעלה\u0004 בין מלאכי מרום שכל אחד מהם הוא שר של אומה מיוחדת (עיין דניאל י), והמריבה ביניהם גורמת למלחמה למטה. \u0003ו\u0004כן שיהיה שלום \u0003בפמליא של מטה\u0004 בין תלמידי החכמים, \u0003ובין התלמידים העוסקים בתורתך בין\u0004 שהם \u0003עוסקין לשמה\u0004 ו\u0003בין עוסקין שלא לשמה. וכל העוסקין\u0004 בתורה \u0003שלא לשמה יהי רצון שיהו עוסקין\u0004 בה \u0003לשמה\".\u0004","\u0003ר' אלכסנדרי בתר צלותיה\u0004 \u0005[אחר תפילתו]\u0006 היה מבקש ו\u0003אמר הכי\u0004 \u0005[כך]: \"\u0006\u0003יהי רצון מלפניך ה' אלהינו, שתעמידנו בקרן אורה,\u0004 בפינה במקום אור, \u0003ואל תעמידנו בקרן חשכה, ואל ידוה\u0004 (יכאב) \u0003לבנו, ואל יחשכו עינינו\". איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003הא\u0004 \u0005[\u0006תפילה \u0005זו]\u0006 \u0003רב המנונא מצלי לה\u0004 \u0005[היה מתפלל אותה].\u0006 \u0003ור' אלכסנדרי בתר דמצלי\u0004 \u0005[אחר שהתפלל]\u0006 \u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"רבון העולמים, גלוי וידוע לפניך שרצוננו לעשות רצונך, ומי מעכב?\u0004 — \u0003שאור שבעיסה\u0004 (החמץ שבבצק), כלומר, היצר הרע בתוכנו מצד אחד, \u0003ושעבוד מלכיות\u0004 מן הצד השני. \u0003יהי רצון מלפניך שתצילנו מידם,\u0004 מיד שני אלה וממילא \u0003נשוב לעשות חוקי רצונך בלבב שלם\".\u0004","\u0003רבא בתר צלותיה\u0004 \u0005[אחר תפילתו]\u0006 היה מבקש ו\u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"אלהי, עד שלא נוצרתי איני כדאי,\u0004 כלומר, לא היה לי כל ערך, \u0003ו\u0004אולם \u0003עכשיו ש\u0004כבר \u0003נוצרתי\u0004 — \u0003כאלו לא נוצרתי\u0004 ולא נוספה לי חשיבות. \u0003עפר אני\u0004 אף \u0003בחיי, קל וחומר\u0004 שאהיה עפר \u0003במיתתי, הרי אני לפניך ככלי מלא בושה וכלימה.\u0004 ובכן \u0003יהי רצון מלפניך ה' אלהי, שלא אחטא עוד ומה שחטאתי לפניך — מרק\u0004 ונקה \u0003ברחמיך הרבים, אבל\u0004 ש\u0003לא\u0004 יהיה מירוק העוונות \u0003על ידי יסורין וחלאים רעים\u0004 כי אם בדרך שקל יהיה לסובלה \u0003\". והיינו\u0004 \u0005[וזהו],\u0006 דברים אלה היו ה\u0003וידוי\u0004 של \u0003רב המנונא זוטי\u0004 (הקטן) \u0003ביומא דכפורי\u0004 \u0005[ביום הכיפורים].\u0006","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא כי הוה\u0004 \u0005[כאשר היה]\u0006 \u0003מסיים צלותיה\u0004 \u0005[תפילתו]\u0006 \u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"אלהי, נצור לשוני מרע ושפתותי מדבר מרמה, ולמקללי נפשי תדום, ונפשי כעפר לכל תהיה. פתח לבי בתורתך, ובמצותיך תרדוף נפשי. ותצילני מפגע רע, מיצר הרע, ומאשה רעה, ומכל רעות המתרגשות לבא בעולם. וכל החושבים עלי רעה מהרה הפר עצתם וקלקל מחשבותם. יהיו לרצון אמרי פי והגיון לבי לפניך ה' צורי וגואלי\".\u0004","על \u0003רב ששת\u0004 מסופר \u0003כי הוה יתיב בתעניתא, בתר דמצלי\u0004 \u0005[כאשר היה יושב בתענית, לאחר שהתפלל]\u0006 \u0003אמר הכי\u0004 \u0005[כך]:\u0006 \u0003\"רבון העולמים, גלוי לפניך בזמן שבית המקדש\u0004 היה \u0003קיים,\u0004 אם היה \u0003אדם חוטא\u0004 — היה \u0003מקריב קרבן. ואין מקריבין ממנו,\u0004 מן הקרבן על המזבח, \u0003אלא\u0004 את \u0003חלבו ודמו, ו\u0004על ידי זה \u0003מתכפר לו\u0004 לחוטא. \u0003ועכשיו\u0004 כאשר \u0003ישבתי בתענית ונתמעט חלבי ודמי\u0004 שלי על ידי כך, \u0003יהי רצון מלפניך שיהא חלבי ודמי שנתמעט כאילו הקרבתיו לפניך על גבי המזבח, ותרצני\".\u0004 מאחר שהוזכרו כאן דברי חכמים בסוף תפילותיהם מביאים דברים נוספים שהיו חכמים אומרים בהזדמנויות שונות.","\u0003ר' יוחנן כי הוה\u0004 \u0005[כאשר היה]\u0006 \u0003מסיים\u0004 את \u0003ספרא\u0004 \u0005[ספר]\u0006 \u0003איוב, אמר הכי\u0004 \u0005[כך]:\u0006 \u0003סוף אדם למות וסוף בהמה לשחיטה, והכל למיתה הם עומדים.\u0004 ואם כן לא המות עצמו הוא הכאב הגדול כי אם עיקר הוא \u0003אשרי מי שגדל בתורה ועמלו בתורה, ועושה נחת רוח ליוצרו, וגדל בשם טוב ונפטר בשם טוב מן העולם,\u0004 שחי את חייו בשלימות האפשרית, \u0003ועליו אמר שלמה: \"טוב שם משמן טוב ויום המות מיום הולדו\"\u0004 (קהלת ז, א), שאדם שהיה שלם בחייו מגיע ביום מותו לשלב גבוה יותר מראשיתו.","\u0003מרגלא בפומיה\u0004 \u0005[רגיל היה בפיו]\u0006 של \u0003ר' מאיר\u0004 פתגם זה: \u0003\"גמור\u0004 (למד) \u0003בכל לבבך ובכל נפשך לדעת את דרכי, ולשקוד על דלתי תורתי. נצור תורתי בלבך, ונגד עיניך תהיה יראתי. שמור פיך מכל חטא, וטהר וקדש עצמך מכל אשמה ועון. ו\u0004אם תעשה כך \u0003אני\u0004 (ה') \u0003אהיה עמך בכל מקום\".\u0004","\u0003מרגלא בפומייהו דרבנן\u0004 \u0005[רגיל היה בפיהם של החכמים]\u0006 ב\u0003יבנה\u0004 לומר כך: \u0003\"אני\u0004 הלומד תורה \u0003בריה, וחברי\u0004 העוסק בעבודה אחרת אף הוא \u0003בריה. אני מלאכתי בעיר והוא מלאכתו בשדה. אני משכים למלאכתי, ו\u0004אף \u0003הוא משכים למלאכתו.\u0004 ו\u0003כשם שהוא אינו מתגדר במלאכתי\u0004 ואינו יכול לעסוק בה, הרי \u0003כך אני איני מתגדר\u0004 ועוסק \u0003במלאכתו\u0004 שלו, ואין לי איפוא יתרון עליו. \u0003ושמא תאמר: אני מרבה\u0004 לעסוק בתורה, \u0003והוא ממעיט\u0004 ולכן מעולה אני ממנו — על כך כבר \u0003שנינו: אחד המרבה ואחד הממעיט ובלבד שיכוין לבו לשמים\"\u0004 (רה\"ג, ערוך).","\u0003מרגלא בפומיה\u0004 \u0005[רגיל היה בפיו]\u0006 של \u0003אביי: \"לעולם יהא אדם ערום ביראה,\u0004 כלומר, שיעשה בכל דרך של חכמה כדי להגיע ליראת ה' ולמצוות, ויקיים בעצמו מאמר הכתוב: \u0003\"מענה רך משיב חמה\"\u0004 (משלי טו, א). \u0003ו\u0004יהא \u0003מרבה שלום\u0004 באמירה ובמעשה \u0003עם אחיו ועם קרוביו ועם כל אדם ואפילו עם גוי בשוק,\u0004 אף על פי שאינו חשוב לו ואינו מכירו כלל (מאירי), \u0003כדי ש\u0004על ידי כך \u0003יהא אהוב למעלה\u0004 בעיני ה' \u0003ונחמד למטה\u0004 בעיני הבריות, \u0003ויהא מקובל על הבריות\". ומסופר בדרך אגב כי\u0004","\u0003אמרו עליו על רבן יוחנן בן זכאי שלא הקדימו אדם\u0004 לומר לו \u0003שלום מעולם, ואפילו גוי בשוק\u0004 היה רבן יוחנן מקדים לו שלום.","\u0003מרגלא בפומיה\u0004 \u0005[רגיל היה בפיו]\u0006 של \u0003רבא: \"תכלית חכמה\u0004 בתורה — להגיע ל\u0003תשובה ומעשים טובים,\u0004 כדי \u0003שלא\u0004 יקרה ש\u0003יהא אדם קורא\u0004 בתורה \u0003ושונה\u0004 במשנה ומתוך כך מגיע לגאווה \u0003ובועט באביו ובאמו וברבו ובמי שהוא גדול ממנו בחכמה\u0004 או \u0003במנין\u0004 (במנין התלמידים הבאים אליו) \u0003שנאמר: \"ראשית חכמה יראת ה' שכל טוב לכל עושיהם\"\u0004 (תהלים קיא, י), \u0003\"לעושים\"\u0004 סתם \u0003לא נאמר, אלא \"לעושיהם\"\u0004 — לעושים את הדברים כמו שהם צריכים להיות, והכוונה: \u0003לעושים לשמה ולא לעושים שלא לשמה.\u0004 ועוד אמר: \u0003וכל העושה שלא לשמה, נוח לו שלא נברא\".\u0004","\u0003מרגלא בפומיה\u0004 \u0005[רגיל היה בפיו]\u0006 של \u0003רב: \"לא כעולם הזה העולם הבא.\u0004 כי \u0003העולם הבא אין בו לא אכילה ולא שתיה ולא פריה ורביה ולא משא ומתן ולא קנאה ולא שנאה ולא תחרות, אלא צדיקים יושבין ועטרותיהם בראשיהם ונהנים מזיו השכינה, שנאמר: \"ויחזו את האלהים ויאכלו וישתו\"\u0004 (שמות כד, יא), כלומר, שראיית פני ה' היא להם כאכילה ושתיה.","אמרו: \u0003גדולה הבטחה שהבטיחן הקדוש ברוך הוא לנשים\u0004 לעתי \u0003ד לבוא יותר מן האנשים, שנאמר: \"נשים שאננות קמנה שמענה קולי בנות בטחות האזנה אמרתי\"\u0004 (ישעיהו לב, ט), והבטחה זו של שאננות ובטחה לא נאמרה לאנשים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לר' חייא: נשים במאי זכיין\u0004 \u0005[במה\u0006 הן זוכות\u0005]\u0006 לקבלת שכר זה? ענה לו: \u0003באקרויי בנייהו לבי כנישתא\u0004 \u0005[בהבאת בניהן לקרוא\u0006 במקרא ב\u0005בית הכנסת],\u0006 \u0003ובאתנויי גברייהו בי רבנן\u0004 \u0005[ובשליחת בעליהן לשנות בבית החכמים,\u0006 בית המדרש\u0005],\u0006 \u0003ונטרין לגברייהו עד דאתו מבי רבנן\u0004 \u0005[והמתנה לבעליהן עד ש\u0006הם \u0005באים מבית החכמים,\u0006 בית המדרש \u0005].\u0006","\u0003כי הוו מפטרי רבנן מבי\u0004 \u0005[כאשר היו נפטרים החכמים,\u0006 הלומדים בבית מדרשו, \u0005מבית]\u0006 מדרשו של \u0003ר' אמי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003מבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חנינא, אמרי ליה הכי\u0004 \u0005[היו אומרים לו כך]\u0006 ברכה זו: \u0003\"עולמך תראה בחייך,\u0004 כלומר, שיהיה לך כל טוב המצוי בעולם, \u0003ואחריתך\u0004 תהיה \u0003לחיי העולם הבא, ותקותך\u0004 תשאר \u0003לדור דורים. לבך יהגה תבונה, פיך ידבר חכמות ולשונך ירחיש רננות, עפעפיך יישירו נגדך, עיניך יאירו במאור תורה, ופניך יזהירו כזוהר הרקיע, שפתותיך יביעו דעת, וכליותיך תעלוזנה מישרים, ופעמיך ירוצו לשמוע דברי עתיק יומין,\u0004 הוא הקדוש ברוך הוא \u0003\" (עיין דניאל ז).\u0004","\u0003כי הוו מפטרי רבנן מבי\u0004 \u0005[כאשר היו נפטרים,\u0006 נפרדים החכמים מבית מדרשו\u0005]\u0006 של \u0003רב חסדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה מבית מדרשו של \u0003ר' שמואל בר נחמני, אמרו ליה הכי\u0004 \u0005[היו אומרים לו כך]\u0006 כדברי הפסוק: \u0003\"אלופינו מסבלים\u0004 אין פרץ ואין יוצאת ואין צווחה ברחובותינו\u0003\"\u0004 (תהלים קמד יד).","בפירוש הלשון \u0003\"אלופינו מסבלים\"\u0004 נחלקו \u0003רב ושמואל, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שנחלקו בכך \u0003ר' יוחנן ור' אלעזר, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"אלופינו\"\u0004 — \u0003בתורה, ו\"מסבלים\"\u0004 — \u0003במצות. וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"אלופינו\"\u0004 — \u0003בתורה ובמצות, ו\"מסבלים\"\u0004 — \u0003ביסורים.\u0004"],["\u0003\"אין פרץ\"\u0004 — \u0003שלא תהא סיעתנו\u0004, סיעת התלמידים, \u0003כסיעתו של דוד שיצא ממנו אחיתופל\u0004 שפרץ את מלכות בית דוד. \u0003\"ואין יוצאת\"\u0004 — \u0003שלא תהא סיעתנו כסיעתו של שאול שיצא ממנו דואג האדומי\u0004 לתרבות רעה. \u0003\"ואין צוחה\"\u0004 — \u0003שלא תהא סיעתנו כסיעתו של אלישע שיצא ממנו גחזי\u0004. \u0003\"ברחובותינו\" — שלא יהא לנו בן או תלמיד שמקדיח תבשילו ברבים\u0004, כלומר, מתקלקל ומקלקל אחרים באופן הידוע ומפורסם לכל \u0003כגון ישו הנוצרי.\u0004","מאחר שהובאו דברים של מחלוקת בפירוש פסוק ואין אנו יודעים אם נחלקו בדבר רב ושמואל או ר' יוחנן ור' אלעזר, מביאים פסוק אחר שאף בו יש מחלוקת מעין זו. נאמר: \u0003\"שמעו אלי אבירי לב הרחוקים מצדקה\"\u0004 (ישעיהו מו, יב), ואף כי לדעת שניהם בפסוק זה מדובר בצדיקים, מכל מקום נחלקו בפירושו \u0003רב ושמואל, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שנחלקו בכך \u0003ר' יוחנן ור' אלעזר. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 בני \u0003כל העולם כולו נזונים בצדקה,\u0004 כלומר, לא משום שמגיע לאנשים לחיות, כי אם משום שהקדוש ברוך הוא עושה עימם צדקה, \u0003והם\u0004 הצדיקים שהם רחוקים מצדקתו של הקדוש ברוך הוא (\"רחוקים\") \u0003ניזונים בזרוע,\u0004 כלומר, בזכות שיכולים לתבעה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כל העולם כולו ניזון בזכותם, והם אפילו בזכות עצמם אין\u0004 הם \u0003ניזונין.\u0004 ו\u0003כ\u0004פי שאמר \u0003רב יהודה אמר רב,\u0004","ש\u0003אמר רב יהודה אמר רב: בכל יום ויום בת קול יוצאת מהר חורב ואומרת: כל העולם כולו נזונין בשביל\u0004 (בזכות) \u0003חנינא בני\u0004 (הוא ר' חנינא בן דוסא), \u0003וחנינא בני די לו בקב חרובים מערב שבת לערב שבת.\u0004","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 פרשנות זו על דברי \u0003רב יהודה.\u0004 ש\u0003אמר רב יהודה מאן\u0004 \u0005[מי הם]\u0006 \u0003\"אבירי לב\"\u0004 — הגוים בני האומה \u0003גובאי טפשאי\u0004 \u0005[הטפשים].\u0006 \u0003אמר רב יוסף: תדע\u0004 שכן הוא, \u0003דהא\u0004 \u0005[שהרי]\u0006 מעולם \u0003לא איגייר גיורא מינייהו\u0004 \u0005[התגייר גר מהם].\u0006","ומעין זה \u0003אמר רב אשי: הגוים בני\u0004 העיר \u0003מתא מחסיא \"אבירי לב\" נינהו\u0004 \u0005[הם],\u0006 \u0003דקא חזו יקרא דאורייתא תרי זמני בשתא\u0004 \u0005[ש\u0006כן \u0005הם רואים\u0006 את \u0005כבוד התורה שתי פעמים בשנה ],\u0006 בירחי כלה, באדר ואלול, שהיו באים אלפי אנשים ללמוד תורה ברבים, \u0003ולא קמגייר גיורא מינייהו\u0004 \u0005[ואין מתגייר גר מהם].\u0006","שנינו במשנה ש\u0003חתן אם רוצה\u0004 הוא \u0003לקרות\u0004 (לקרוא) קריאת שמע בלילה הראשון לנישואיו הריהו רשאי לעשות כן. ורבן שמעון בן גמליאל אומר שיש לחוש בדבר זה משום יוהרה.","על כך שואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 כי \u0003רבן שמעון בן גמליאל חייש ליוהרא ורבנן לא חיישי ליוהרא\u0004 \u0005[חושש,\u0006 לדבר הנראה \u0005כגאווה, וחכמים אינם חוששים לגאוה],\u0006 \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי ההיפך שמענו להם,\u0006 שהם אומרים\u0005]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקום שנהגו\u0004 בו \u0003לעשות מלאכה בתשעה באב\u0004 — \u0003עושין,\u0004 מותר לעשות. וב\u0003מקום שנהגו שלא לעשות\u0004 — \u0003אין עושין. וכל מקום תלמידי חכמים בטלים\u0004 ממלאכתם. ועל כך \u0003רבן שמעון בן גמליאל אומר: לעולם יעשה כל אדם את עצמו\u0004 לענין ביטול מלאכה בתשעה באב \u0003כתלמיד חכם.\u0004","ואם כן \u0003קשיא דרבנן אדרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים, על\u0006 דברי \u0005חכמים]\u0006 וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבן שמעון בן גמליאל\u0004 על דברי \u0003רבן שמעון בן גמליאל! \u0004","על כך \u0003אמר ר' יוחנן: מוחלפת השיטה,\u0004 כלומר, יש מן באחד המקומות להחליף את שמות החכמים כדי להגיע לשיטה אחידה. ואילו \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: לעולם לא תחליף,\u0004 אין צורך להחליף, כי \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[\u0006מדברי \u0005חכמים, על\u0006 דברי \u0005חכמים לא קשה]\u0006 משום שב\u0003קריאת שמע, כיון דכולי עלמא קרו, ואיהו נמי קרי\u0004 — \u0003לא מיחזי\u0004 \u0005[שהכל קוראים, והוא גם כן קורא\u0006 — אין הוא מתבלט, ו\u0005אין\u0006 זה נראה\u0005]\u0006 \u0003כיוהרא. הכא\u0004 \u0005[כאן]\u0006 בענין תשעה באב \u0003כיון דכולי עלמא עבדי\u0004 \u0005[שהכל עושים]\u0006 \u0003מלאכה ואיהו לא קא עביד\u0004 \u0005[והוא אינו עושה]\u0006 — הרי זה \u0003מיחזי\u0004 \u0005[נראה]\u0006 \u0003כיוהרא,\u0004 שהרי הוא מתבלט מתוך כולם.","וכן מדברי \u0003רבן שמעון בן גמליאל\u0004 על דברי \u0003רבן שמעון בן גמליאל לא קשיא\u0004 \u0005[קשה],\u0006 אין סתירה, שכן \u0003התם\u0004 \u0005[שם]\u0006 בענין קריאת שמע הלא \u0003בכונה תליא מילתא, ואנן סהדי דלא מצי לכווני דעתיה\u0004 \u0005[תלוי הדבר, ואנו עדים,\u0006 כלומר, הכל יודעים, \u0005שאין\u0006 הוא \u0005יכול לכוון\u0006 את \u0005דעתו].\u0006 ואם הוא קורא בכל זאת, הרי בכך הוא מראה את גאוותו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בענין תשעה באב\u0005,\u0006 \u0003הרואה\u0004 שאיננו עושה מלאכה, \u0003אומר: מלאכה הוא\u0004 ש\u0003אין לו\u0004 וממילא אינו מתבלט מן האחרים. \u0003פוק חזי כמה בטלני איכא בשוקא\u0004 \u0005[צא וראה כמה בטלנים יש בשוק],\u0006 אפילו בימים המותרים במלאכה.","\u0003הדרן עלך היה קורא\u0004","\u0003מי ש\u0004מת לו מת, ו\u0003מתו מוטל לפניו\u0004 — \u0003פטור מקריאת שמע ומן התפלה ומן התפילין, ומכל מצוות\u0004 עשה \u0003האמורות בתורה\u0004 עד שיקבור את מתו.","ואילו \u0003נושאי המטה וחלופיהן,\u0004 האנשים המחליפים אותם, \u0003וחלופי חלופיהן, את\u0004 אותם \u0003ש\u0004נמצאים \u0003לפני המטה\u0004 ולפי התור יהיו הם שישאו אחר כך את ארון המת, \u0003ואת\u0004 אלה \u0003ש\u0004נמצאים \u0003לאחר המטה. את שלפני המטה\u0004 ולמטה \u0003צורך בהם,\u0004 שצריכים הם לשאתה — \u0003פטורים\u0004 מקריאת שמע, \u0003ואת שלאחר המטה\u0004 אף שלמטה עדיין \u0003צורך בהם,\u0004 מאחר שכבר נשאו את המת — \u0003חייבין\u0004 הם מעתה בקריאת שמע. \u0003ו\u0004אף על פי כן \u0003אלו ואלו פטורים מן התפלה,\u0004 מפני שהם טרודים בדבר ואינם יכולים לכוון דעתם ולהתפלל כראוי.","לאחר ש\u0003קברו את המת וחזרו, אם יכולין להתחיל\u0004 לקרוא קריאת שמע \u0003ולגמור עד שלא יגיעו לשורה\u0004 של אנשים שיוצרים המלווים, ודרכה משפחת האבל עוברים להתנחם — \u0003יתחילו\u0004 לקרוא קריאת שמע. \u0003ו\u0004אולם \u0003אם לאו\u0004 \u0005[לא],\u0006 שאינם יכולים להספיק להתחיל ולגמור קריאת שמע — \u0003לא יתחילו.\u0004","ו\u0003העומדים בשורה\u0004 עצמה, האנשים \u0003הפנימיים\u0004 שהאבל עובר ביניהם ממש שעומדים לפנים והם מנחמים אותו — \u0003פטורים\u0004 מקריאת שמע, \u0003ו\u0004אילו \u0003החיצונים\u0004 שהם המצטרפים רק לשם הכבוד — \u0003חייבים. נשים ועבדים וקטנים פטורים מקריאת שמע ומן התפילין, וחייבין בתפלה ובמזוזה ובברכת המזון.\u0004","שנינו במשנה שמי שמתו מוטל לפניו הריהו פטור מקריאת שמע ומשאר מצוות עשה, ונדייק: כשהמת \u0003מוטל לפניו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 פטור הוא, \u0003ו\u0004אולם כ\u0003שאינו מוטל לפניו\u0004 ממש — \u0003לא\u0004 יפטר מן המצוות.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לדבר\u0005]\u0006 ממה ששנינו בברייתא: \u0003מי שמתו מוטל לפניו\u0004 — \u0003אוכל בבית\u0004 (חדר) \u0003אחר, ואם אין לו בית אחר\u0004 — \u0003אוכל בבית חבירו, ואם אין לו בית חבירו,\u0004 שאין אדם שהוא יכול לאכול אצלו — \u0003עושה מחיצה\u0004 בינו לבין המת, \u0003ואוכל. ואם אין לו דבר\u0004 שבאמצעותו הוא יכול \u0003לעשות מחיצה\u0004 — \u0003מחזיר פניו\u0004 מן המת לצד אחר \u0003ואוכל. ו\u0004בכל אופן \u0003אינו מיסב ואוכל,\u0004 שהדבר נראה כדרך סעודה חגיגית. \u0003ו\u0004אף \u0003אינו אוכל בשר ואינו שותה יין, ואינו מברך\u0004 ברכה לפני האוכל, \u0003ואינו מזמן,\u0004 מברך ברכת המזון לאחריו."],["\u0003ואין מברכין,\u0004 כלומר, אין צורך שיברכו אחרים \u0003עליו\u0004 (בשבילו), \u0003ואין מזמנין עליו, ופטור מקריאת שמע ומן התפלה ומן התפילין ומכל\u0004 ה\u0003מצות האמורות בתורה. ו\u0004אילו \u0003בשבת\u0004 הריהו \u0003מיסב\u0004 לסעודות שבת כדרכו, \u0003ואוכל בשר ושותה יין, ומברך ומזמן, ומברכין עליו ומזמנין עליו, וחייב בכל\u0004 ה\u0003מצות האמורות בתורה. רבן שמעון בן גמליאל אומר: מתוך שנתחייב\u0004 בשבת \u0003באלו\u0004 המצוות הכרוכות בסעודות שבת — \u0003נתחייב ב\u0004כל המצוות \u0003כולן.\u0004","\u0003ואמר ר' יוחנן: מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם,\u0006 בין רבן שמעון בן גמליאל והתנא הראשון\u0005],\u0006 שלכאורה זהים דבריהם — \u0003תשמיש המטה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005].\u0006 שרבן שמעון בן גמליאל סבור שמאחר שאין אבילות בשבת, חייב האבל לקיים בשבת גם את מצוות עונה עם אשתו, אף על פי שאם ימנע מכך לא ייראה הדבר לרבים כאבילות, שהרי אין זו אבילות בפרהסיה.","\u0003קתני מיהת\u0004 \u0005[מכל מקום שנינו]\u0006 ש\u0003פטור מקריאת שמע ומן התפלה ומן התפילין ומכל מצות האמורות בתורה,\u0004 והדברים סותרים לכאורה את שיטת משנתנו שאינו פטור אלא כאשר מתו מוטל לפניו! וכדי לתרץ את הסתירה \u0003אמר רב פפא: תרגמא\u0004 \u0005[הסבר אותה,\u0006 את הברייתא\u0005]\u0006 במקרה המיוחד ש\u0003מחזיר פניו ואוכל,\u0004 שאף שמחזיר פניו, בעצם מתו מוטל לפניו, ואולם בשאר המקרים, וכגון שהוא בבית אחר — חייב בכל המצוות. \u0003רב אשי אמר:\u0004 יש לפרש את הביטוי \"מתו מוטל לפניו\" לאו דווקא במשמעותו המילולית, אלא \u0003כיון שמוטל עליו לקוברו\u0004 ועדיין לא נקבר, הרי זה \u0003כמוטל לפניו דמי\u0004 \u0005[נחשב].\u0006 כפי \u0003שנאמר: \"ויקם אברהם מעל פני מתו\"\u0004 (בראשית כג, ג), \u0003ו\u0004גם כאשר מדבר אברהם עם בני חת \u0003נאמר: \"ואקברה מתי מלפני\"\u0004 (שם ד), הרי ש\u0003כל זמן שמוטל עליו לקברו\u0004 הריהו \u0003כמוטל לפניו דמי\u0004 \u0005[נחשב].\u0006","מן המשנה אפשר להבין כי \u0003מתו\u0004 דווקא, כלומר, אדם מבני משפחתו — \u0003אין\u0004 \u0005[כן],\u0006 הריהו פטור מן המצוות, \u0003אבל\u0004 אם אינו קרובו אלא שהוא רק \u0003משמרו\u0004 למת — \u0003לא\u0004 נפטר בכגון זה מן המצוות.","ועל כך מקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003המשמר את המת, אף על פי שאינו מתו\u0004 — \u0003פטור מקריאת שמע ומן התפלה ומן התפילין ומכל מצות האמורות בתורה!\u0004 על כך משיבים שאין לראות דברים אלה כסותרים, כי אם כמשלימים זה את זה. וכן יש להבינם: \u0003משמרו,\u0004 המשמר את המת, \u0003אף על פי שאינו מתו,\u0004 וכן באופן שהוא \u0003מתו אף על פי שאינו משמרו\u0004 — שניהם פטורים.","ועוד מקשים: הגענו איפוא למסקנה ש\u0003מתו,\u0004 אם מת לו מת, או שהיה \u0003משמרו\u0004 את המת — \u0003אין\u0004 \u0005[כן],\u0006 הוא פטור מן המצוות, \u0003אבל המהלך בבית הקברות\u0004 — \u0003לא\u0004 יהא פטור. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003לא יהלך אדם בבית הקברות ותפילין בראשו וספר תורה בזרועו וקורא\u0004 בו. \u0003ואם עושה כן\u0004 — \u0003עובר משום \"לועג לרש חרף עושהו\"\u0004 (משלי יז, ה), שהמת אינו יכול לקיים מצוות, והוא בקיום המצוה בפניו נראה כלועג למת.","על כך מתרצים: \u0003התם\u0004 \u0005[שם,\u0006 העובר בבית הקברות\u0005]\u0006 \u0003תוך ארבע אמות\u0004 לקבר המת \u0003הוא\u0004 ש\u0003אסור,\u0004 אבל \u0003חוץ לארבע אמות\u0004 מן המת — \u0003חייב\u0004 בתפילה ובתפילין. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מת תופס ארבע אמות ל\u0004ענין הפטור מ\u0003קריאת שמע\u0004 למהלך באותן ארבע אמות. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 שהיה זה מתו או שהיה משמר את המת \u0003חוץ לארבע אמות נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004","מעתה באים לדון באותה ברייתא \u0003גופא\u0004 \u0005[לגופה].\u0006 שנינו בה ש\u0003המשמר את המת אף על פי שאינו מתו\u0004 — \u0003פטור מקריאת שמע ומן התפלה ומן התפילין ומכל מצות האמורות בתורה.\u0004 ובהמשך דבריה אומרת הברייתא שאם \u0003היו שנים,\u0004 שני אנשים, משמרים את המת — \u0003זה,\u0004 אחד מהם, \u0003משמר\u0004 אותו, \u0003וזה,\u0004 האחר, \u0003קורא,\u0004 ואחר כך מתחלפים \u0003וזה משמר וזה קורא\u0004. \u0003בן עזאי אומר:\u0004 אם \u0003היו באים בספינה\u0004 עם המת — \u0003מניחו,\u0004 מותר להם להניחו \u0003בזוית זו,\u0004 פינה אחת של הספינה, \u0003ומתפללין שניהם בזוית אחרת\u0004 שלה.","על כך שואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]?\u0006 \u0003אמר רבינא:\u0004 מחלוקתם בבעיה אם \u0003חוששין לעכברים\u0004 גם בתוך הספינה \u0003איכא בינייהו\u0004, ש\u0003מר סבר\u0004 \u0005[החכם\u0006 הראשון \u0005סבור]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 לעכברים בכל מקום, ועל כן אין ראוי להניח את המת בלא שמירה כשהוא בספינה שמא יאכלוהו העכברים. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[החכם\u0006 השני, בן עזאי, \u0005סבור]:\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שבספינה אין לחוש לכך.","ומתוך הדברים באים לדון בנושאים אחרים הקשורים בכבוד המת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוליך עצמות ממקום למקום, הרי זה לא יתנם בדיסקיא\u0004 (שק כפול שמניחים על החמור) \u0003ויתנם על גבי חמור, וירכב עליהם, מפני שנוהג בהם מנהג בזיון. ו\u0004אולם \u0003אם היה מתירא מפני גוים\u0004 או \u0003מפני ליסטים\u0004 וצריך למהר — \u0003מותר\u0004 אף באופן זה. \u0003וכדרך שאמרו בעצמות כך אמרו בספר תורה.\u0004","על הפיסקה האחרונה שואלים: \u0003אהייא\u0004 \u0005[להיכן]?\u0006 על איזה קטע מן הברייתא מוסבת התוספת \"וכן בספר תורה...\"? \u0003אי לימא\u0004 \u0005[אם תאמר]\u0006 כי הוא מוסבת \u0003ארישא\u0004 \u0005[על ראש\u0006 הברייתא\u0005]\u0006 — הלא זהו \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 שכן \u0003מי גרע\u0004 \u0005[האם גרוע]\u0006 \u0003ספר תורה מעצמות\u0004 המת? ובוודאי אסור לנהוג בו מנהג בזיון. אלא יש לומר שקטע זה מוסב \u0003אסיפא\u0004 \u0005[על הסוף]\u0006 שבשעת סכנה מותר לרכב אף על גבי ספר תורה. \u0003אמר\u0004","\u0003רחבה אמר רב יהודה: כל הרואה\u0004 את \u0003המת ואינו מלוהו עובר משום \"לועג לרש חרף עשהו\". ואם הלווהו\u0004 (ליווהו) \u0003מה שכרו? אמר רב אסי, עליו הכתוב אומר: \"מלוה ה' חונן דל\u0004 וגמולו ישלם לו\u0003\"\u0004 (משלי יט, יז), וכן \u0003\"\u0004עושק דל חרף עושהו \u0003ומכבדו חונן אביון\"\u0004 (שם יד, לא).","מסופר כי \u0003ר' חייא ור' יונתן הוו שקלי ואזלי\u0004 \u0005[היו מהלכים]\u0006 \u0003בבית הקברות. הוה קשדיא תכלתא\u0004 \u0005[היתה זרוקה תכלת\u0006 ציציתו\u0005]\u0006 של \u0003ר' יונתן\u0004 ונגררת על גבי הקברים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא: דלייה\u0004 \u0005[הרימנה],\u0006 \u0003כדי שלא יאמרו\u0004 המתים: \u0003למחר,\u0004 לכשיבוא יומם הם \u0003באין אצלנו\u0004 להיקבר, \u0003ועכשיו\u0004 הם \u0003מחרפין\u0004 (מבזים) \u0003אותנו\u0004 במעשיהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יונתן: \u0003ומי ידעי כולי האי\u0004 \u0005[והאם יודעים\u0006 הם המתים כל כך]? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"והמתים אינם יודעים מאומה\"\u0004 (קהלת ט, ה)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003אם קרית\u0004 את המקרא — \u0003לא שנית\u0004 פעם אחרת. ו\u0003אם שנית\u0004 — \u0003לא שלשת,\u0004 ו\u0003אם שלשת\u0004 — \u0003לא פרשו לך\u0004 כראוי. וכך צריך לפרש את הפסוק \u0003\"כי החיים יודעים שימותו\u0004 והמתים אינם יודעים מאומה ואין עוד להם שכר כי נשכח זכרם\" (שם): \"כי החיים יודעים שימותו\" — \u0003אלו הצדיקים ש\u0004אף \u0003במיתתן נקראו \"חיים\"\u0004 ורמז לדבר ממה \u0003שנאמר: \"ובניהו בן יהוידע בן איש חי רב פעלים מקבצאל הוא הכה את שני אראל מואב והוא ירד והכה את הארי בתוך הבור ביום השלג\"\u0004 (שמואל ב' כג, כ)."],["וכך יש להסביר: הכתוב קורא לו \u0003\"בן איש חי\",\u0004 ותמיהה היא: \u0003אטו כולי עלמא בני מתי נינהו\u0004 \u0005[וכי כל העולם בני מתים הם]\u0006 שייחדו הכתוב בכינוי זה? \u0003אלא\u0004 כך יש לפרש: \u0003\"בן איש חי\"\u0004 — שהוא חי תמיד, \u0003שאפילו במיתתו\u0004 הוא \u0003קרוי \"חי\". \"רב פעלים מקבצאל\"\u0004 — \u0003שריבה וקבץ פעלים ל\u0004מען ה\u0003תורה. \"והוא הכה את שני אראל מואב\"\u0004 — \u0003שלא הניח\u0004 (השאיר אחריו) אדם גדול \u0003כמותו לא במקדש ראשון ולא במקדש שני,\u0004 שכן המקדש נקרא \"אריאל\" (ראה ישעיהו כט, א), ו\"שני אריאל\" הינם איפוא שני בתי מקדש.","והמשך הכתוב \u0003\"והוא ירד והכה את הארי בתוך הבור ביום השלג\",\u0004 ובפירושו נחלקו חכמים, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהפירוש הוא: \u0003דתבר גזיזי דברדא, ונחת\u0004 \u0005[ששבר גושי קרח, וירד]\u0006 \u0003וטבל\u0004 במים לטהרתו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בפירוש הכתוב: \u0003דתנא סיפרא דבי רב ביומא דסיתוא\u0004 \u0005[ששנה\u0006 את כל \u0005ספר בית\u0006 מדרשו של \u0005רב,\u0006 תורת כהנים, \u0005ביום חורף\u0006 אחד\u0005].\u0006","ובניגוד לצדיק הנקרא \"חי\" אף לאחר מותו, נאמר בפירוש הכתוב \u0003\"והמתים אינם יודעים מאומה\"\u0004 — \u0003אלו רשעים, ש\u0004אף \u0003בחייהם\u0004 הריהם \u0003קרויין \"מתים\", שנאמר\u0004 על מלך ישראל בעודו חי: \u0003\"ואתה חלל רשע נשיא ישראל\"\u0004 (יחזקאל כא, ל). \u0003ואי בעית אימא, מהכא\u0004 \u0005[ואם תרצה אמור,\u0006 הבא ראיה לדבר \u0005מכאן],\u0006 ממה שנאמר: \u0003\"על פי שנים עדים או על פי שלשה עדים יומת המת\"\u0004 (דברים יז, ו), והדבר תמוה שהלא עדיין \u0003חי הוא\u0004 כל עוד לא פסקו את דינו למיתה! \u0003אלא\u0004 שאדם זה שהוא רשע, הינו נחשב \u0003מת מעיקרא\u0004 \u0005[מתחילה].\u0006","בנושא זה מסופר: \u0003בני ר' חייא נפוק לקרייתא\u0004 \u0005[יצאו אל הכפרים]\u0006 להשגיח על הפועלים\u0005.\u0006 \u0003אייקר להן תלמודייהו\u0004 \u0005[השתכח מהם תלמודם].\u0006 \u0003הוו קא מצערי לאדכוריה\u0004 \u0005[והיו מצטערים להיזכר בו].\u0006 \u0003אמר ליה חד לחבריה\u0004 \u0005[לו אחד לחברו]:\u0006 האם \u0003ידע אבון בהאי צערא\u0004 \u0005[יודע אבינו\u0006 שמת כבר \u0005בצער הזה\u0006 שלנו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחיו: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003ידע? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"יכבדו בניו ולא ידע\u0004 ויצערו ולא יבין למו\u0003\"\u0004 (איוב יד, כא), והרי שהמתים אינם יודעים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אחיו: \u0003ו\u0004כי המת \u0003לא ידע\u0004 \u0005[אינו יודע]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אך בשרו עליו יכאב ונפשו עליו תאבל\"\u0004 (שם כב) \u0003ו\u0004על סמך פסוק זה \u0003אמר ר' יצחק: קשה רמה\u0004 (התולעת המכרסמת) \u0003למת כ\u0004דקירת \u0003מחט בבשר החי,\u0004 והרי שלמתים יש הרגשה וידיעה!","על כן, כדי ליישב את הסתירה \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003בצערא דידהו\u0004 — \u0003ידעי, בצערא דאחרינא\u0004 — \u0003לא ידעי\u0004 \u0005[בצערם שלהם\u0006 — הם \u0005יודעים, בצערם של אחרים\u0006 — \u0005אינם יודעים].\u0006","ומקשים: \u0003ולא?\u0004 וכי אין המתים יודעים בצערם של אחרים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה בחסיד אחד שנתן דינר לעני בערב ראש השנה בשני בצורת, והקניטתו\u0004 (והכעיסתו) \u0003אשתו\u0004 על שנתן סכום כה גדול בשנים כה קשות, ולא מצא לו החסיד מנוחה בביתו, \u0003והלך ולן בבית הקברות.\u0004 ובאותו לילה \u0003שמע\u0004 בחלומו (ריטב\"א, הכותב, מהרש\"א) \u0003שתי רוחות שמספרות\u0004 (משוחחות) \u0003זו לזו. אמרה חדא\u0004 \u0005[אחת]\u0006 \u0003לחברתה: חברתי, בואי ונשוט\u0004 (נשוטט) \u0003בעולם, ונשמע מאחורי הפרגוד\u0004 (המסך המבדיל בין השכינה והעולם) \u0003מה\u0004 (איזו) \u0003פורענות בא לעולם\u0004 בשנה זו? \u0003אמרה לה חברתה:\u0004 אני \u0003איני יכולה\u0004 ללכת עמך \u0003ש\u0004כן \u0003אני קבורה במחצלת של קנים. אלא לכי את, ומה שאת שומעת אמרי לי. הלכה היא ושטה ובאה\u0004 בחזרה. \u0003ואמרה לה חברתה: חברתי, מה שמעת מאחורי הפרגוד? אמרה לה: שמעתי שכל הזורע\u0004 בשנה זו \u0003ברביעה\u0004 (עונת המטר)\u0003 ראשונה\u0004 סופו שה\u0003ברד\u0004 יורד ו\u0003מלקה\u0004 (מקלקל) \u0003אותו,\u0004 את תבואתו. כיון שכך, \u0003הלך הוא\u0004 אותו חסיד \u0003וזרע ברביעה שניה.\u0004 ואכן בסופו של דבר, יבול שדותיו \u0003של כל העולם כולו לקה,\u0004 ואילו יבולו \u0003שלו לא לקה.\u0004","\u0003לשנה האחרת הלך\u0004 \u0005אותו חסיד\u0006 בכוונה \u0003ולן\u0004 שוב \u0003בבית הקברות\u0004 בערב ראש השנה, ושמע שוב \u0003אותן שתי רוחות שמספרות זו עם זו. אמרה חדא\u0004 \u0005[אחת]\u0006 \u0003לחברתה: בואי ונשוט בעולם ונשמע מאחורי הפרגוד מה פורענות בא לעולם. אמרה לה: חברתי, לא כך אמרתי לך\u0004 כבר ש\u0003איני יכולה\u0004 לפי \u0003שאני קבורה במחצלת של קנים?! אלא לכי את, ומה שאת שומעת בואי ואמרי לי. הלכה ושטה ובאה. ואמרה לה חברתה: חברתי, מה שמעת מאחורי הפרגוד? אמרה לה: שמעתי שכל הזורע ברביעה שניה\u0004 ה\u0003שדפון\u0004 (יובש) \u0003מלקה אותו. הלך\u0004 אותו חסיד \u0003וזרע ברביעה ראשונה,\u0004 ומכיון שהכל זרעו בשניה, קרה שוב \u0003ש\u0004יבולו של \u0003כל העולם נשדף ושלו לא נשדף. \u0004","\u0003אמרה לו אשתו: מפני מה אשתקד של כל העולם כולו לקה ושלך לא לקה, ועכשיו\u0004 בשנה זו \u0003של כל העולם כולו נשדף ושלך לא נשדף? סח\u0004 (סיפר) \u0003לה כל הדברים הללו. אמרו לא היו ימים מועטים\u0004 לאחר זמן \u0003עד שנפלה קטטה בין אשתו של אותו חסיד ובין אמה של אותה ריבה\u0004 (נערה) שהיתה קבורה שם. ו\u0003אמרה לה\u0004 אשת החסיד בזלזול: \u0003לכי ואראך בתך שהיא קבורה במחצלת של קנים.\u0004","\u0003לשנה האחרת\u0004 שוב \u0003הלך\u0004 החסיד \u0003ולן בבית הקברות ושמע\u0004 שוב \u0003אותן רוחות שמספרות זו עם זו. אמרה לה: חברתי, בואי ונשוט בעולם ונשמע מאחורי הפרגוד מה פורענות בא לעולם. אמרה לה: חברתי, הניחיני,\u0004 שכן \u0003דברים ש\u0004נאמרו \u0003ביני לבינך כבר נשמעו בין החיים. אלמא ידעי\u0004 \u0005[מכאן\u0006 שהמתים \u0005יודעים]\u0006 מה קורה ומתחדש בעולם.","על כך עונים: אין זו ראיה, \u0003דילמא איניש אחרינא שכיב, ואזל\u0004 \u0005[אולי אדם אחר\u0006 ששמע את שנאמר משמם, ו\u0005מת, והלך]\u0006 \u0003ואמר להו\u0004 \u0005[להם]\u0006 שכך שמע.","ובענין זה של ידיעת המתים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, שכן מסופר: \u0003זעירי הוה מפקיד זוזי גביה אושפיזיכתיה\u0004 \u0005[היה מפקיד\u0006 את \u0005כספו אצל בעלת האכסניה שלו].\u0006 \u0003עד דאתי ואזיל לבי רב, שכיבה\u0004 \u0005[בתוך הזמן שבא והלך לבית רבו, מתה],\u0006 ולא ידע איש היכן הניחה את הכסף. \u0003אזל בתרה\u0004 \u0005[הלך אחריה]\u0006 \u0003לחצר מות\u0004 (בית הקברות), \u0003אמר לה: זוזי היכא\u0004 \u0005[היכן הדינרים]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקלינהו מתותי בצינורא דדשא בדוך פלן\u0004 \u0005[לך וקח אותם מתחת ציר הדלת במקום פלוני],\u0006 \u0003ואימא לה לאמא תשדר לי, מסרקאי וגובתאי דכוחלא בהדי פלניתא דאתיא למחר\u0004 \u0005[ואמור לה לאמי\u0006 ש\u0005תשלח לי את מסרקי וקופסא של כחול עם פלונית שתבוא\u0006 הנה לאחר מותה \u0005מחר].\u0006 \u0003אלמא\u0004 \u0005[הרי נלמד\u0006 מכאן\u0005]\u0006 שהמתים \u0003ידעי\u0004 \u0005[יודעים]\u0006 מה מתרחש בעולם החיים!","ודוחים הוכחה זו: \u0003דילמא\u0004 \u0005[שמא]\u0006 המלאך \u0003דומה\u0004 הממונה על המתים \u0003קדים\u0004 \u0005[מקדים]\u0006 \u0003ומכריז להו\u0004 \u0005[להם]\u0006 שמחר יבוא פלוני\u0005,\u0006 אבל בעצמם אינם יודעים.","ומביאים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה אחרת לדבר, שכן מסופר: \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל הוו קא מפקדי גביה זוזי דיתמי\u0004 \u0005[היו מופקדים אצלו כספי יתומים].\u0006 \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 מת\u0005]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003שמואל גביה\u0004 \u0005[אצלו,\u0006 לידו\u0005]\u0006 ולא יכול היה לספר לו היכן הכספים, ומאחר שלא החזירם \u0003הוו קא קרו ליה \"בר אכיל זוזי דיתמי\"\u0004 \u0005[היו קוראים לו \"בן אוכל כספי יתומים\"].\u0006 \u0003אזל אבתריה\u0004 \u0005[הלך אחריו,\u0006 אחרי אביו\u0005]\u0006 \u0003לחצר מות. אמר להו\u0004 \u0005[להם,\u0006 למתים שם\u0005]:\u0006 \u0003בעינא\u0004 \u0005[רוצה אני\u0006 את\u0005]\u0006 \u0003אבא! אמרו ליה\u0004 \u0005[לו]\u0006 המתים: \u0003אבא טובא איכא הכא\u0004 \u0005[רבים יש כאן].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בעינא\u0004 \u0005[רוצה אני]\u0006 את \u0003אבא בר אבא. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אבא בר אבא נמי טובא איכא הכא\u0004 \u0005[גם כן רבים יש כאן].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בעינא\u0004 \u0005[רוצה אני]\u0006 את \u0003אבא בר אבא אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל היכא\u0004 \u0005[היכן\u0006 הוא\u0005]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003סליק למתיבתא דרקיעא\u0004 \u0005[עלה לישיבה שברקיע].\u0006 \u0003אדהכי חזיה\u0004 \u0005[בתוך כך\u0006 שעלה ראהו] את \u0003לוי\u0004 חבירו \u0003דיתיב אבראי\u0004 \u0005[שיושב מחוץ]\u0006 לישיבה של שאר המתים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי יתבת אבראי\u0004 \u0005[מדוע אתה יושב בחוץ]?\u0006 \u0003מאי טעמא לא סלקת\u0004 \u0005[מה טעם אינך עולה\u0006 לישיבה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003לי: כל הנך שני\u0004 \u0005[אותן\u0006 מספר \u0005שנים]\u0006 ש\u0003לא סליקת למתיבתא\u0004 \u0005[עלית\u0006 נכנסת, \u0005לישיבה]\u0006 בראשותו של \u0003ר' אפס ואחלישתיה לדעתיה\u0004 \u0005[והחלשת\u0006 גגם את דעתו, גרמת לו לחולשת הדעת\u0005],\u0006 \u0003לא מעיילינן לך למתיבתא דרקיעא\u0004 \u0005[נכניס אותך לישיבה שברקיע].\u0006","\u0003אדהכי והכי אתא אבוה\u0004 \u0005[בין כה וכה בא אביו],\u0006 \u0003חזיה דהוה קא בכי ואחיך\u0004 \u0005[ראה אותו\u0006 שמואל \u0005שהיה בוכה וצוחק].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לאביו: \u0003מאי טעמא קא בכית\u0004 \u0005[מה טעם בוכה אתה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: משום \u0003דלעגל קא אתית\u0004 \u0005[שבמהרה תבוא לכאן],\u0006 והוסיף שמואל לשאול אותו: \u0003מאי טעמא אחיכת\u0004 \u0005[מה טעם צוחק אתה]?\u0006 ענה לו אביו: משום \u0003דחשיבת בהאי עלמא טובא\u0004 \u0005[שחשוב אתה בעולם הזה ביותר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי חשיבנא\u0004 \u0005[אם חשוב אני]\u0006 — \u0003נעיילוה\u0004 \u0005[יכניסוהו]\u0006 \u0003ללוי\u0004 לישיבה. ואכן כך היה ש\u0003עיילוהו\u0004 \u0005[הכניסוהו]\u0006 \u0003ללוי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לאביו: \u0003זוזי דיתמי היכא\u0004 \u0005[כספי היתומים היכן\u0006 הם\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקלינהו באמתא דרחיא\u0004 \u0005[לך\u0006 ו\u0005קח אותם בבית הריחיים],\u0006 ושם תמצא שהכספים \u0003עילאי ותתאי\u0004 \u0005[העליונים והתחתונים]\u0006 — הם \u0003דידן\u0004 \u0005[שלנו],\u0006 \u0003ומיצעי דיתמי\u0004 \u0005[והאמצעיים של היתומים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003מאי טעמא עבדת הכי\u0004 \u0005[מה טעם עשית כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי גנובי\u0004 \u0005[\u0006ש\u0005אם יגנבו]\u0006 — \u0003מגנבו מדידן\u0004 \u0005[יגנבו משלנו],\u0006 שהם העליונים הנראים לעיני הגנב, \u0003אי אכלה ארעא\u0004 \u0005[אם תאכלם, תבלעם הארץ]\u0006 — \u0003אכלה מדידן\u0004 \u0005[תאכל,\u0006 תבלע \u0005משלנו],\u0006 את התחתונים שהם סמוכים לה, ולא משל היתומים. ומסיקים מסיפור זה, \u0003אלמא דידעי\u0004 \u0005[מכאן שיודעים]\u0006 הם המתים מתי ימותו אחרים, ומאחר שאין זה למחרת, הרי אף המלאך דומה אינו יכול לספר להם (תוספות). על כך עונים: \u0003דילמא שאני\u0004 \u0005[אולי שונה]\u0006 \u0003שמואל,\u0004 ש\u0003כיון דחשיב\u0004 \u0005[ש\u0006הוא \u0005חשוב],\u0006 \u0003קדמי ומכרזי\u0004 \u0005[מקדימים ומכריזים]:\u0006 \u0003פנו מקום שיבוא.\u0004","על כל פנים ולעצם הבעיה \u0003אף ר' יונתן הדר ביה\u0004 \u0005[חזר בו],\u0006 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מנין למתים שמספרים\u0004 (משוחחים) \u0003זה עם זה\u0004 — \u0003שנאמר: \"ויאמר ה' אליו זאת הארץ אשר נשבעתי לאברהם ליצחק וליעקב לאמר\u0004 לזרעך אתננה\u0003\"\u0004 (דברים לד, ד), \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"לאמר\"?\u0004 — ש\u0003אמר הקדוש ברוך הוא למשה: לך אמור להם לאברהם ליצחק וליעקב\u0004 שה\u0003שבועה שנשבעתי לכם כבר קיימתיה לבניכם.\u0004"],["\u0003ואי סלקא דעתך דלא ידעי, כי אמר להן מאי הוי\u0004 \u0005[ואם עולה על דעתך שאין\u0006 המתים \u0005יודעים, אם יאמר להם מה יהיה]?\u0006 ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר — \u0003דידעי\u0004 \u0005[ש\u0006הם \u0005יודעים]?\u0006 אם כן \u0003למה ליה למימר להו\u0004 \u0005[לו לומר להם]?!\u0006 על כך משיבים: זו אינה קושיה, שכן הוא אומר להם כדי \u0003לאחזוקי ליה טיבותא\u0004 \u0005[שיחזיקו לו טובה]\u0006 \u0003למשה.\u0004","באותו נושא \u0003אמר ר' יצחק: כל המספר\u0004 בגנותו של אדם \u0003אחרי המת\u0004 (מותו), אין בכך כלום ו\u0003כאילו\u0004 הוא \u0003מספר אחר האבן.\u0004 ולכך ניתנו שני הסברים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהסיבה לכך היא משום שהמתים \u0003לא ידעי\u0004 \u0005[יודעים],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003דידעי\u0004 \u0005[ש\u0006אכן המתים \u0005יודעים]\u0006 ואולם \u0003לא איכפת להו\u0004 \u0005[להם]\u0006 שמדברים בגנותם.","על כך שואלים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב פפא: חד אישתעי מילתא בתריה\u0004 \u0005[אחד סיפר דברים\u0006 של גנאי \u0005אחרי]\u0006 \u0003מר שמואל\u0004 לאחר מותו \u0003ונפל קניא מטללא\u0004 \u0005[קנה מן התקרה]\u0006 \u0003ובזעא לארנקא דמוחיה\u0004 \u0005[ושבר את גולגלתו],\u0006 והרי שאיכפת למתים כאשר מדברים בגנותם!","ודוחים: זו אינה ראיה שהמתים איכפת להם בדבר, אלא \u0003שאני צורבא מרבנן, דקודשא בריך הוא תבע ביקריה\u0004 \u0005[שונה תלמיד חכם, שהקדוש ברוך הוא\u0006 עצמו \u0005תובע את כבודו].\u0006","מעין הדברים האלה \u0003אמר ר' יהושע בן לוי: כל המספר\u0004 דברי גנאי \u0003אחר מטתן של תלמידי חכמים,\u0004 שמבזה אותם לאחר מותם, סופו שהוא \u0003נופל בגיהנם, שנאמר: \"והמטים עקלקלותם יוליכם ה' את פעלי האון שלום על ישראל\"\u0004 (תהלים קכה, ה). כלומר, \u0003אפילו בשעה ששלום על ישראל,\u0004 כשאותו אדם שמספרים עליו כבר מת ואין מי שיריב לכבודו ושלום על ישראל (תוספות), אף על פי כן \u0003\"יוליכם ה' את פעלי האון\".\u0004","ובהקשר לכך \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אם ראית תלמיד חכם שעבר עבירה בלילה\u0004 — \u0003אל תהרהר אחריו ביום\u0004 שהוא חוטא, \u0003שמא עשה\u0004 בינתיים \u0003תשובה.\u0004 על כך מקשים רק \u0003\"שמא\"\u0004 עשה תשובה \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? והלא יש לדונו לכף זכות! \u0003אלא\u0004 יש לומר ש\u0003ודאי עשה תשובה.\u0004 ומעירים על כך: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שצריך לדון תלמיד חכם לכף זכות ולומר שודאי עשה תשובה — דווקא \u0003בדברים שבגופו, אבל\u0004 אם ראהו שחטא \u0003בממונא\u0004 \u0005[בממון]\u0006 חבירו, אין חובה לדונו לכף זכות \u0003עד\u0004 שיראוהו \u0003דמהדר למריה\u0004 \u0005[שמחזיר\u0006 את הממון \u0005לבעליו].\u0006","מאחר שהוזכרו דברים בכבוד תלמידי חכמים דנים עוד בנושא ומביאים את מה ש\u0003אמר ר' יהושע בן לוי: בעשרים וארבעה מקומות\u0004 (מקרים) \u0003בית דין מנדין על כבוד הרב, וכולן שנינו במשנתנו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר: היכא\u0004 \u0005[היכן]\u0006 מצאנו אותם מקרים של נידוי על כבוד הרב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכי תשכח\u0004 \u0005[כאשר תמצא],\u0006 כלומר, חפש ותמצא.","\u0003נפק דק, ואשכח תלת\u0004 \u0005[יצא, דייק, ומצא שלוש]\u0006 דוגמאות, והם: \u0003המזלזל בנטילת ידים, והמספר אחר מטתן של תלמידי חכמים, והמגיס דעתו\u0004 (מתנהג בגסות) \u0003כלפי מעלה.\u0004","ופירוט מקור הדברים: לגבי \u0003המספר אחר מטתן של תלמידי חכמים מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — מזה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הוא,\u0004 עקביא בן מהללאל \u0003היה אומר:\u0004 אשה שחשד בה בעלה שנסתרה עם אחר ולדבריו יתכן וסוטה היא, \u0003אין משקין\u0004 אותה במי סוטה (עיין במדבר ה) בכמה מקרים, והם: \u0003לא את הגיורת, ולא את\u0004 השפחה \u0003המשוחררת. וחכמים אומרים:\u0004 גם את אלה \u0003משקין. ואמרו לו\u0004 חכמים כראיה לשיטתם: \u0003מעשה בכרכמית,\u0004 שהיתה \u0003שפחה משוחררת בירושלים\u0004 וגזרו עליה \u0003והשקוה\u0004 מי סוטה על פי הוראת \u0003שמעיה ואבטליון! אמר להם\u0004 עקביא בן מהללאל לחכמים: \u0003דוגמא השקוה,\u0004 כלומר, מאחר שאף שמאי ואבטליון היו ממשפחת גרים — השקוה, שכן אותה שפחה היא כדוגמתם. \u0003ו\u0004משום שהשתמש עקביא בן מהללאל בביטוי שיש בו כדי להעליב תלמידי חכמים שמתו, \u0003נידוהו ומת בנדויו. ו\u0004כדין המת בנידויו בלא התרה \u0003סקלו בית דין את ארונו.\u0004 ואם כן למדים מכאן שהמבזה תלמידי חכמים לאחר מותם דינו בנידוי.","\u0003ו\u0004לגבי \u0003המזלזל בנטילת ידים מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — למדים מהמשך אותה משנה, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003אמר ר' יהודה:\u0004 אותו סיפור שסופר אודות נידויו של עקביא בן מהללאל איננו נכון כלל, \u0003חס ושלום שעקביא בן מהללאל נתנדה, ש\u0004כן \u0003אין עזרה ננעלת על כל אדם בישראל,\u0004 כלומר, גם באותם הימים כאשר כל העם בא לרגל להקרבת קרבן הפסח והיו נועלים את העזרה, ודאי לא היה שם אדם שיהיה מושלם \u0003בחכמה ובטהרה וביראת חטא כעקביא בן מהללאל. אלא את מי נדו?\u0004 — \u0003את אלעזר בן חנוך\u0004 וזאת משום \u0003שפקפק\u0004 וזלזל \u0003ב\u0004תקנת \u0003נטילת ידים. וכשמת, שלחו בית דין והניחו אבן גדולה על ארונו,\u0004 כדי \u0003ללמדך\u0004 בכך \u0003שכל המתנדה ומת בנדויו\u0004 — \u0003בית דין סוקלים את ארונו,\u0004 ואבן זו הריהי כסקילה סמלית, ומכאן שהמפקפק בנטילת ידים דינו נידוי.","הפרט השלישי \u0003המגיס דעתו כלפי מעלה מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 מסופר כי חוני המעגל עג עוגה, עמד בתוכה ואמר שלא יצא מתוכה עד שירד מטר, והיה מפציר ואומר מדי פעם באיזה אופן הוא רוצה שירד הגשם. לאחר שירדו גשמים \u0003שלח לו שמעון בן שטח\u0004 ראש הסנהדרין \u0003לחוני המעגל:\u0004 לאמיתו של דבר, בשל הדברים שאמרת \u0003צריך אתה להתנדות, ואלמלא חוני אתה גוזרני\u0004 (הייתי גוזר) \u0003עליך נדוי, אבל מה אעשה שאתה מתחטא\u0004 (מתפנק ומטריח) \u0003לפני המקום\u0004 (ה') \u0003ועושה לך\u0004 את \u0003רצונך,\u0004 שהרי ירדו גשמים כבקשתך, \u0003כבן שמתחטא לפני אביו ו\u0004אביו \u0003עושה לו רצונו\u0004 ואינו מקפיד. \u0003ועליך הכתוב אומר: \"ישמח אביך ואמך ותגל יולדתך\"\u0004 (משלי כג, כה), הרי שכרגיל הגסת דעת כלפי מעלה עונשה נידוי.","על כך מקשים: \u0003ותו ליכא\u0004 \u0005[ויותר אין]\u0006 מקרים של נידוי או איום בנידוי? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 מקרים נוספים וכגון זה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף:\u0004 מסופר ש\u0003תודוס איש רומי\u0004 היה ראש קהילתו ו\u0003הנהיג את בני רומי להאכילן גדיים מקולסין\u0004 (צלויים כשמעיהם מונחים על ראשם, כדרך שהיו נוהגים לצלות את קרבן הפסח] \u0003בלילי פסחים\u0004 כעין המקדש, ו\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003שמעון בן שטח: אלמלא תודוס אתה,\u0004 שאדם חשוב אתה, \u0003גוזרני עליך נדוי, ש\u0004כן נראה הדבר כאילו \u0003אתה מאכיל את ישראל קדשים בחוץ\u0004 (מחוץ לתחום המקדש), שכן כך עושים במקדש בלבד.","על כך משיבים: אין למנות מקרה זה, שכן אמר ר' יהושע בן לוי שהם עשרים וארבעה מקרים \u0003במשנתנו, והא\u0004 \u0005[ו\u0006אילו \u0005זו]\u0006 \u0003ברייתא היא\u0004 בלבד.","ושואלים: \u0003ובמתניתין ליכא\u0004 \u0005[ובמשנתנו אין]?\u0006 \u0003והא איכא הא\u0004 \u0005[והרי יש\u0006 את \u0005זו]\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 תנור של חרס ש\u0003חתכו חוליות\u0004 חוליות \u0003ונתן חול בין חוליא לחוליא, ר' אליעזר מטהר\u0004 תנור זה מלקבל עוד טומאה, שלעומתו אין התנור נחשב כבר ככלי שלם אלא כמורכב משברים, וכלי חרס שבור אינו מקבל טומאה. \u0003וחכמים מטמאים,\u0004 שהם סבורים כי מאחר שהתנור ממלא את תפקידו בשלמות גם כך, הריהו נחשב כיחידה אחת וככלי שלם. \u0003וזהו\u0004 הנקרא \u0003תנורו של עכנאי.\u0004","על כך שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"עכנאי\"?\u0004 משום מה קראוהו כך? \u0003אמר רב יהודה אמר שמואל: מלמד שהקיפוהו\u0004 חכמים את ר' אליעזר \u0003הלכות\u0004 וראיות \u0003כעכנאי\u0004 (נחש) \u0003זה, וטמאוהו\u0004 את התנור ומה שבתוכו.","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003אותו היום הביאו\u0004 את \u0003כל\u0004 ה\u0003טהרות שטיהר ר' אליעזר\u0004 בתנור זה \u0003ושרפום לפניו,\u0004 ומאחר שלא קבל על עצמו את הכרעת הרוב, \u0003לבסוף ברכוהו\u0004 (לשון נקיה להחרמה). ואם כן הרי לפנינו עוד מקרה ששנו שסופו נידוי.","ועונים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 בכל זאת \u0003נדוי במתניתין\u0004 \u0005[במשנה]\u0006 \u0003לא תנן\u0004 \u0005[שנינו].\u0006 ושואלים: אם כן, מה שאמר ר' יהושע בן לוי שדבר זה מצוי \u0003בעשרים וארבעה מקומות היכא משכחת לה\u0004 \u0005[היכן\u0006 כיצד \u0005אתה מוצא\u0006 דבר \u0005זה]?\u0006 ומשיבים: \u0003ר' יהושע בן לוי מדמה מילתא למילתא\u0004 \u0005[דבר לדבר],\u0006 שכאשר היה לומד במשנה על ביטוי של מחלוקת או דיבור שאינו ראוי של חכם אחד כלפי חכמים אחרים, היה מבין שראוי היה שינדו אותו בשל כך. ואילו \u0003ר' אלעזר לא מדמה מילתא למילתא\u0004 \u0005[דבר לדבר]\u0006 ומצא רק שלושה מקרים מפורשים.","שנינו במשנה ש\u0003נושאי המטה וחלופיהן פטורים מקריאת שמע. \u0004בענין זה מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין מוציאים את המת\u0004 לקבורה \u0003סמוך ל\u0004זמן \u0003קריאת שמע,\u0004 אלא אחר כך. \u0003ו\u0004אולם \u0003אם התחילו\u0004 כבר להוציאו— \u0003אין מפסיקין\u0004 בקריאת שמע. על כך מקשים \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יוסף אפקוהו\u0004 \u0005[הוציאוהו]\u0006 לקבורה \u0003סמוך ל\u0004זמן \u0003קריאת שמע!\u0004 ומתרצים: \u0003אדם חשוב שאני\u0004 \u0005[שונה],\u0006 והקילו לגביו כדי להוסיף כבוד בקבורתו.","שנינו במשנה את דין נושאי המיטה לענין חובת קריאת שמע, ושם חילקו בין אלו \u0003שלפני המטה ו\u0004אלו \u0003שלאחר המטה. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003העוסקים בהספד, בזמן שהמת מוטל לפניהם נשמטים אחד אחד\u0004 מן ההספד \u0003וקורין\u0004 קריאת שמע במקום אחר. ואם \u0003אין המת מוטל לפניהם, הם\u0004 המספידים \u0003יושבין וקורין\u0004 קריאת שמע, \u0003והוא\u0004 האבל \u0003יושב ודומם. הם עומדים ומתפללין, והוא עומד ומצדיק עליו,\u0004 על עצמו, \u0003את הדין, ואומר\u0004 נוסח זה: \u0003\"ריבון העולמים, הרבה חטאתי לפניך, ולא נפרעת ממני אחד מני אלף, יהי רצון מלפניך ה' אלהינו, שתגדור פרצותינו ופרצות כל עמך בית ישראל ברחמים\".\u0004","על כך \u0003אמר אביי: לא מבעי ליה לאינש למימר הכי\u0004 \u0005[אין אדם צריך לומר כך],\u0006 שכן \u0003אמר ר' שמעון בן לקיש, וכן תנא משמיה\u0004 \u0005[שנו משמו]\u0006 של \u0003ר' יוסי: לעולם אל יפתח אדם פיו לשטן,\u0004 כלומר, שלא יתן מקום ואפשרות לאסון או רעה. ומנוסח זה נשמע שלא נפרעו ממנו כדי כל חטאותיו, ובכך הוא פותח מקום שיפרעו ממנו יותר.","\u0003ואמר רב יוסף: מאי קראה\u0004 \u0005[מהו המקרא]\u0006 המסייע לדבר זה — \u0003שנאמר: \"כמעט כסדם היינו\u0004 לעמורה דמינו\u0003\"\u0004 (ישעיהו א, ט), ומיד לאחר שנפתחה אפשרות השוואה לסדום, \u0003מאי אהדר להו\u0004 \u0005[מה השיב להם]\u0006 ה\u0003נביא —\u0004 נאמר כבר \u0003\"שמעו דבר ה' קציני סדם\u0004 האזינו תורת אלוהינו עם עמורה\" \u0005(ישעיהו א, י)\u0006.","שנינו במשנה שאם \u0003קברו את המת וחזרו,\u0004 אם יכולים להתחיל ולסיים את כל קריאת שמע לפני שמגיעים לעשות שורה של מנחמים — יעשו כן. מכאן מדייקים בגמרא: דווקא \u0003אם יכולים להתחיל ולגמור את כולה, אין אבל\u0004 אם יש אפשרות לסיים רק \u0003פרק אחד או פסוק אחד\u0004 — \u0003לא\u0004 יפסיקו. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לדבר ממה ששנינו בברייתא: \u0003קברו את המת וחזרו, אם יכולים להתחיל ולגמור אפילו פרק אחד או פסוק אחד\u0004 — יתחילו!","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר]\u0006 התנא במשנה, כך יש להסיק מדבריו: \u0003אם יכולים להתחיל ולגמור אפילו פרק אחד או אפילו פסוק אחד עד שלא יגיעו לשורה\u0004 — \u0003יתחילו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לא יתחילו.\u0004"],["שנינו במשנה ששורת המנחמים \u0003העומדים בשורה\u0004 הפנימית פטורים מקריאת שמע, והאחרים חייבים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא את הדברים בנוסח מורחב קצת יותר: \u0003שורה\u0004 של מנחמים \u0003הרואה פנימה\u0004 — \u0003פטורה, ושאינה רואה פנימה\u0004 — \u0003חייבת.\u0004 ו\u0003ר' יהודה\u0004 מוסיף ו\u0003אומר:\u0004 שורת המנחמים \u0003הבאים מחמת האבל\u0004 — \u0003פטורין,\u0004 והבאים \u0003מחמת עצמן,\u0004 מתוך סקרנות — \u0003חייבין\u0004 בקריאת שמע.","שנינו שיש ממנחמי האבלים הפטורים מקריאת שמע משום כבוד המת. ומכאן באים לדיון העוסק בשאלה הכללית באיזו מדה דוחה כבוד הבריות מצוות הכתובות בתורה. \u0003אמר רב יהודה אמר רב: המוצא כלאים בבגדו,\u0004 שגילה שבגדו או חלק ממנו עשוי שעטנז, צמר ופשתים יחדיו — \u0003פושטן אפילו בשוק.\u0004 ואין מניחים אותו להישאר בבגדו זה עד שיגיע לביתו, \u0003מאי טעמא\u0004 \u0005[מהו טעם\u0006 הדבר\u0005]\u0006 — כאמור: \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה'\"\u0004 (משלי כא, ל), ומכאן הגיעו לכלל ש\u0003כל מקום שיש\u0004 בו \u0003חלול ה' אין חולקים כבוד לרב.\u0004 על הכללה זו מקשים ממקורות אחדים.","\u0003מתיבי\u0004 \u0005[הקשו]\u0006 על כך ממה ששנינו בברייתא: לאחר ש\u0003קברו\u0004 מלווי המת \u0003את המת וחזרו, ולפניהם\u0004 יש \u0003שתי דרכים, אחת טהורה ואחת טמאה,\u0004 שהדרך עוברת בבית הקברות וכדומה, אם \u0003בא\u0004 האבל \u0003ב\u0004דרך ה\u0003טהורה\u0004 — \u0003באין עמו בטהורה,\u0004 ואם \u0003בא ב\u0004דרך ה\u0003טמאה\u0004 — \u0003באין\u0004 כל המלוווים אתו \u0003ב\u0004דרך ה\u0003טמאה משום כבודו.\u0004 ו\u0003אמאי\u0004 \u0005[מדוע]\u0006 יעשו כן? \u0003לימא\u0004 \u0005[נאמר]\u0006 גם כאן \u0003\"אין חכמה ואין תבונה... לנגד ה'\"!\u0004","ו\u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003ר' אבא\u0004 שמדובר כאן בדרך שאינה טמאה מדין תורה כי אם רק \u0003בבית הפרס\u0004 הטמא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים].\u0006 ששדה שידוע שהיה בו קבר, וחרשו את השדה ונעלם הקבר שבתוכו — השדה כולו נחשב טמא מדברי חכמים, מחשש שמא פיזרה המחרשה את עצמות המת בכל חלקי השדה. ומכיון שטומאה זו היא מגזירת חכמים בלבד, מותר לעבור בשדה מפני כבוד הבריות.","וראיה לדבר שאין דין בית הפרס כדין טומאה מן התורה — ש\u0003אמר רב יהודה אמר שמואל: מנפח אדם בית הפרס והולך,\u0004 שהעובר בבית הפרס ורוצה להשאר בטהרה, צריך לנפח — לנשוף באבק לפני כל צעד שהוא צועד, שכן אם יש שם עצם — תגלה הנשיפה את העצם מן האבק שנצטבר עליה. ועל בדיקה מסוג זה לא היו סומכים אילו היה האיסור מדברי תורה. \u0003ו\u0004כן \u0003אמר רב יהודה בר אשי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: בית הפרס שנדש\u0004 ברגלים ונעשה בו שביל — \u0003טהור,\u0004 ואין חוששים עוד לעצמות, הרי שכל איסורו לא היה אלא משום גזירה וחומרת חכמים.","ומנסים להביא ראיה אחרת לשאלה זו עד כמה כבוד הבריות דוחה מצוות הכתובות בתורה. \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר ר' אלעזר בר צדוק\u0004 הכהן: \u0003מדלגין היינו\u0004 אני ושאר הכהנים \u0003על גבי ארונות של מתים,\u0004 כדי למהר להגיע \u0003לקראת\u0004 (לקבל פני) \u0003מלכי ישראל. ולא לקראת מלכי ישראל בלבד אמרו\u0004 שמותר לעשות כן \u0003אלא אפילו לקראת מלכי אומות העולם, שאם יזכה\u0004 לראות בגאולת ישראל, \u0003יבחין בין מלכי ישראל למלכי אומות העולם.\u0004 הרי שלכבוד המלך עובר הכהן על האיסור מן התורה להטמא למתים, ו\u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003לימא\u0004 \u0005[נאמר]\u0006 אף כאן: \u0003\"\u0004אין חכמה ואין תבונה ואין עצה לנגד ה'\"!","ומתרצים שיש להבין זאת על פי דברי \u0003רבא.\u0004 ש\u0003אמר רבא: דבר תורה, אהל\u0004 שהוא כיסוי על המת, \u0003כל שיש בו חלל טפח\u0004 בין המת לבין הדבר המכסה אותו — הרי מכסה זה \u0003חוצץ בפני הטומאה\u0004 ואין המת מטמא את שלמעלה מן הכיסוי. \u0003ושאין בו חלל טפח\u0004 בין המת לדבר המכסה את המת — \u0003אינו חוצץ בפני הטומאה\u0004 והטומאה (\"טומאה רצוצה\") בוקעת ועולה עד לרקיע.","\u0003ורוב ארונות\u0004 המתים \u0003יש בהן חלל טפח,\u0004 ולכן על גבי הארון אין טומאה כלל. אלא \u0003גזרו\u0004 חכמים \u0003על\u0004 ארונות \u0003שיש בהן\u0004 חלל \u0003משום\u0004 הארונות \u0003שאין בהן\u0004 חלל טפח. ואולם \u0003משום כבוד מלכים לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים],\u0006 והכהנים דילגו על הארונות — שהרי מותר מדברי תורה לעשות כן. ואין איפוא ללמוד מכאן אם כבוד הבריות דוחה דברי תורה.","ומנסים להביא ראיה אחרת ממה ששנינו בברייתא. \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]:\u0006 \u0003גדול כבוד הבריות שדוחה [את]\u0004 מצוות \u0003לא תעשה שבתורה.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 אף כאן את דברי הכתוב \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה'\" תרגמה\u0004 \u0005[הסביר\u0006 זאת\u0005]\u0006 \u0003רב בר שבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב כהנא:\u0004 המדובר הוא \u0003בלאו\u0004 (מצוות לא תעשה) של \"על פי התורה אשר יורוך ועל המשפט אשר יאמרו לך תעשה \u0003לא תסור\u0004 מן הדבר אשר יגידו לך ימין ושמאל\" (דברים יז, יא), ואיסור זה הוא שאפשר לבטלו משום כבוד הבריות. \u0003אחיכו עליה\u0004 \u0005[צחקו עליו]\u0006 בני הישיבה, שהרי ה\u0003לאו\u0004 של \u0003\"לא תסור\" דאורייתא היא\u0004 \u0005[מן התורה הוא]\u0006 כשאר איסורים ומדוע יהא קל משאר איסורי תורה לעבור עליו בשל כבוד הבריות?!","\u0003אמר\u0004 להם \u0003רב כהנא: גברא רבה אמר מילתא, לא תחיכו עליה\u0004 \u0005[אדם גדול אמר דבר, אל תצחקו עליו],\u0006 שכן \u0003כל מילי דרבנן אסמכינהו\u0004 \u0005[דברי חכמים סמכום]\u0006 \u0003על לאו\u0004 של \u0003\"לא תסור\", ומשום כבודו שרו רבנן\u0004 \u0005[התירו חכמים],\u0006 שהרי תוקפן של כל גזירות ותקנות חכמים הינו מכוח ציווי התורה לשמוע אל השופט שיהיה בכל דור ודור ולא לסור מדבריו. ולכן כאשר החכמים מוותרים על תקנה שלהם משום כבוד הבריות, הרי שבעקיפין דוחה כבוד הבריות לא תעשה שבתורה. ומכל מקום רק תקנות מדברי חכמים הוא דוחה.","ושוב מנסים להביא ראיה אחרת ממה ששנינו בברייתא. \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]:\u0006 בדיני אבידה נאמר \"לא תראה את שור אחיך או את שיו נידחים והתעלמת מהם השב תשיבם לאחיך\". (דברים כב, א) ובברייתא מסבירים כי מן הביטוי \u0003\"והתעלמת מהם\"\u0004 יש להבין כהוראת היתר ש\u0003פעמים שאתה מתעלם מהם\u0004 מאבידה, \u0003ופעמים שאין אתה מתעלם מהם.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 כגון \u0003אם היה\u0004 המוצא \u0003כהן, והיא,\u0004 האבידה, \u0003בבית הקברות, או\u0004 אם \u0003היה זקן ואינה לפי כבודו\u0004 לטפל באבידה מסוג זה, \u0003או שהיתה מלאכתו מרובה משל חברו,\u0004 שאינו רוצה לבטל את מלאכתו המרובה כשנמצא אדם אחר שיוכל לדאוג לאבידה, \u0003לכך נאמר, \"והתעלמת\"\u0004 להתיר את ההתעלמות. \u0003אמאי\u0004 \u0005[מדוע],\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 גם כאן שאף שאין האבידה לפי כבודו מכל מקום \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה'\"!\u0004","ומשיבים: \u0003שאני התם, דכתיב\u0004 \u0005[שונה שם, שנאמר]\u0006 \u0003\"והתעלמת מהם\",\u0004 שבכך יש רמז שלפעמים מותר להתעלם מן האבידה. ראינו אפוא שבמקרה מיוחד זה שכבוד הבריות דוחה מצווה יש ראיה מן התורה, ושואלים: \u0003וליגמר מינה\u0004 \u0005[ונלמד ממנה]\u0006 מהלכה זו שבכלל דוחה כבוד הבריות אף מצוה שבתורה. אפשרות זו דוחים: \u0003איסורא מממונא לא ילפינן\u0004 \u0005[\u0006דברים של \u0005איסור מ\u0006דיני \u0005ממונות אין אנו למדים].\u0006 והאבידה הלא היא אך הפסד כספי, מה שאין כן בשאר מצוות שאינן קשורות בממון.","על כן מביאים ראיה נוספת ממה ששנינו בברייתא אחרת. \u0003תא שמע\u0004 \u0005[בא\u0006 ושמע], נאמר במקרא על הנזיר: \"לאביו ולאמו לאחיו ולאחותו לא יטמא להם במותם כי נזר אלוהיו על ראשו\" (במדבר ו, ז), ומאחר שנכתב כבר בנזיר \"על נפש מת לא יבוא\" מה טעם יש לפירוט נוסף זה, שהרי כולם מצויים בכללו של הכתוב הקודם?! ולמדו חכמים בדרך מדרש ההלכה שכל אחד מיחסי הקירבה הללו בא ללמדנו הדגשה מיוחדת בדינים אלה.","וכך למדו: מהמלה \u0003\"ולאחתו\"\u0004 למדים אנו שכל אדם (תוספות) \u0003שהיה הולך לשחוט את פסחו,\u0004 או שהיה הולך \u0003למול את בנו\u0004, שבשניהם, אם ימנע אדם ולא יעשה אותם הריהו מתחייב בכך כרת \u0003ושמע שמת לו מת, יכול,\u0004 כלומר, האם אפשר לחשוב ש\u0003יחזור\u0004 מדרכו \u0003ויטמא\u0004 למתו? — \u0003אמרת:\u0004 בודאי במקרה זה לא יעקור מצוה חמורה של התורה בשל מתו, ו\u0003לא יטמא.\u0004","\u0003יכול\u0004 היית לחשוב: \u0003כשם שאינו מטמא להם\u0004 לקרוביו \u0003כך אינו מטמא למת מצוה\u0004 שהוא מת הנמצא בדרך ואין איש לקוברו — על כך אמרו \u0003תלמוד לומר\u0004 שיש להבין את ההדגשה \u0003\"ולאחותו\"\u0004 במובן זה: \u0003לאחותו הוא\u0004 ש\u0003אינו מטמא,\u0004 שכן יש בדרך כלל מי שידאג לקבורתה,"],["\u0003אבל מטמא הוא למת מצוה.\u0004 ואף כאן יש לשאול: ו\u0003אמאי\u0004 \u0005[מדוע]\u0006, \u0003לימא\u0004 \u0005[שיאמר]\u0006 שאף קבורתו של מת מצוה, שהיא משום כבוד הבריות שלא יתנבל אדם בהיותו מושלך בלא קבורה, אינה דוחה מצוות המפורשות בתורה, וכפי שנאמר: \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה'\"!\u0004","על כך עונים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006, \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 במפורש בענין אלה שאסור לו להיטמא להם \u0003\"ולאחותו\",\u0004 ומזה נלמד שלמת מצווה הוא כן נטמא.","ומקשים: \u0003וליגמר מינה\u0004 \u0005[ונלמד ממנה]\u0006 מהלכה זו שבמת מצוה להתיר גם במקרים אחרים! ומשיבים: מקרה זה מיוחד הוא, שכן \u0003שב ואל תעשה שאני\u0004 \u0005[שונה],\u0006 שכן בהמנעות מקבורת המת אינו עושה פעולה ישירה העוקרת את המצוה, אלא שמכללה מתבטלת יכולתו לעשות את המצוה בשל כבוד הבריות ואינו דומה לעקירה בפועל של דבר מצוה.","בהקשר למצוה שלא לחוש אם צריך לוותר על כבוד אדם מפני כבוד המקום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: מאי שנא\u0004 \u0005[במה שונים]\u0006 \u0003ראשונים דאתרחיש להו ניסא\u0004 \u0005[שהתרחשו להם נסים],\u0006 \u0003ומאי שנא אנן דלא מתרחיש לן ניסא\u0004 \u0005[ובמה שונים אנו שאין מתרחשים לנו נסים]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום תנויי\u0004 \u0005[לימוד],\u0006 הרי \u0003בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003רב יהודה כולי תנויי\u0004 \u0005[כל לימודם]\u0006 \u0003ב\u0004סדר \u0003נזיקין הוה\u0004 \u0005[היה],\u0006 \u0003ואנן קא מתנינן שיתא סדרי\u0004 \u0005[ואנחנו שונים\u0006 את כל \u0005ששת הסדרים].\u0006 ועוד, \u0003וכי הוה מטי\u0004 \u0005[וכאשר היה מגיע]\u0006 \u0003רב יהודה ב\u0004מסכת \u0003עוקצין\u0004 הדנה בשאלה באיזו מדה עוקציהם (קצותיהם של פירות וירקות שונים) מצטרפים עם הירק עצמו בקבלת טומאה, להלכה על \u0003האשה שכובשת ירק בקדרה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכאשר היה מגיע להלכה ש\u0003זיתים שכבשן בטרפיהן\u0004 (עליהם) \u0003טהורים,\u0004 שהעלים אינם נחשבים עוד כמכשירים להרים את הירק, היה מתקשה בדבר ו\u0003אמר: הויות\u0004 \u0005[\u0006את \u0005מחלוקות]\u0006 \u0003רב ושמואל קא חזינא הכא\u0004 \u0005[אני רואה כאן],\u0006 שהיו הדברים קשים עליו בהבנת המחלוקת בין רבותיו הגדולים. \u0003ו\u0004אילו \u0003אנן קא מתנינן בעוקצין תליסר מתיבתא\u0004 \u0005[אנחנו שונים בעוקצין בשלוש עשרה פנים,\u0006 שלוש עשרה נוסחאות\u0005],\u0006 \u0003ואילו\u0004 לגבי נסים — \u0003רב יהודה כי הוה שליף חד מסאניה, אתי מטרא\u0004 \u0005[כאשר היה שולף את נעלו האחת\u0006 בשעת התענית על המטר מיד \u0005היה יורד הגשם],\u0006 \u0003ואנן קא מצערינן נפשין ומצוח קא צוחינן, ולית דמשגח בן\u0004 \u0005[ואנחנו מצערים את עצמנו וצווחים, ואין שמשגיח בנו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא: \u0003קמאי הוו קא מסרי נפשייהו\u0004 \u0005[הראשונים היו מוסרים\u0006 את \u0005נפשם]\u0006 על \u0003קדושת השם,\u0004 ואילו \u0003אנן לא מסרינן נפשין\u0004 \u0005[אנחנו איננו מוסרים\u0006 את \u0005נפשנו]\u0006 על \u0003קדושת השם.\u0004 שכן נהגו הראשונים, \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב אדא בר אהבה חזייה לההיא כותית דהות לבישא כרבלתא בשוקא\u0004 \u0005[ראה כותית אחת שהיתה לבושה כרבלתא,\u0006 בגד שעטנז, \u0005בשוק].\u0006 ומכיון ש\u0003סבר\u0004 \u0005[חשב]\u0006 ש\u0003בת ישראל היא, קם קרעיה מינה\u0004 \u0005[עמד\u0006 ו\u0005קרע אותו,\u0006 את הבגד, \u0005ממנה].\u0006 \u0003אגלאי מילתא\u0004 \u0005[נתגלה הדבר]\u0006 ש\u0003כותית היא\u0004 ונתבע לדין על הבושה שבייש אותה. \u0003שיימוה\u0004 \u0005[העריכו אותה]\u0006 בושה \u0003בארבע מאה זוזי. אמר לה\u0004 רב אדא לבסוף: \u0003מה שמך? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מתון. אמר לה\u0004 בשימוש בדמיון המילים, \u0003מתון\u0004 — \u0003מאתון\u0004 \u0005[מאתיים]\u0006 \u0003ארבע מאות זוזי שויא\u0004 \u0005[זוזים\u0006 היא \u0005שווה].\u0006","ועוד סופר מענין הראשונים שהיו משפילים עצמם מתוך רצון להוסיף לכבוד שמים. ש\u0003רב גידל הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה קא אזיל ויתיב\u0004 \u0005[שהיה הולך ויושב]\u0006 על \u0003שערי טבילה\u0004 של הנשים. \u0003אמר להו\u0004 \u0005[להן]:\u0006 \u0003הכי טבילו והכי טבילו\u0004 \u0005[כך תטבלו וכך תטבלו].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003:\u0004 וכי \u0003לא קא מסתפי מר\u0004 \u0005[מתיירא אדוני]\u0006 \u0003מיצר הרע? אמר להו\u0004 \u0005[להם]:\u0006 \u0003דמיין באפאי כי קאקי חיורי\u0004 \u0005[דומות\u0006 הן \u0005בעיני כאווזים לבנים].\u0006","ובדומה לכך מסופר ש\u0003ר' יוחנן הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה קא אזיל ויתיב\u0004 \u0005[שהיה הולך ויושב]\u0006 על \u0003שערי טבילה. אמר\u0004 כהסבר לכך: \u0003כי סלקן\u0004 \u0005[כאשר עולות]\u0006 \u0003בנות ישראל ואתיין\u0004 \u0005[ובאות]\u0006 \u0003מטבילה, מסתכלן בי, ונהוי להו זרעא דשפירי כוותי\u0004 \u0005[יסתכלו בי, ויהיו להן ילדים יפים כמותי],\u0006 שהיה ר' יוחנן מפורסם ביופיו המיוחד. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 וכי \u0003לא קא מסתפי מר מעינא בישא\u0004 \u0005[אין אדוני מתיירא מעין הרע]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא מזרעא\u0004 \u0005[אני מזרעו]\u0006 של \u0003יוסף קא אתינא\u0004 \u0005[אני בא],\u0006 \u0003דלא שלטה ביה עינא בישא\u0004 \u0005[שאין שולטת בו עין רעה],\u0006 \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 \u0003\"בן פרת יוסף בן פרת עלי עין\"\u0004 (בראשית מט, כב), \u0003ואמר ר' אבהו\u0004 כדרשה: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"עלי עין\", אלא \"עולי עין\"\u0004 — שהם מעולים ומסולקים משליטתה של העין.","\u0003ר' יוסי בר' חנינא\u0004 הביא ראיה אחרת מברכת יעקב לאפרים ומנשה: \u0003\"\u0004המלאך הגואל אותי מכל רע יברך את הנערים ויקרא בהם שמי ושם אבותי אברהם ויצחק \u0003וידגו לרב בקרב הארץ\"\u0004 (שם מח, טז), \u0003מה דגים שבים\u0004 ה\u0003מים מכסין עליהם ואין עין הרע שולטת בהם,\u0004 כך \u0003אף זרעו של יוסף אין עין הרע שולטת בהם.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ויש אומרים]:\u0006 \u0003עין\u0004 של יוסף \u0003שלא רצתה לזון ממה שאינו שלו\u0004 (אשת פוטיפר) — שכרו ש\u0003אין עין הרע שולטת בו.\u0004","\u0003נשים ועבדים וקטנים\u0004 שהם לגבי הלכות שונות שווים בחיובם \u0003פטורין מקריאת שמע\u0004"],["\u0003ומן התפילין, ו\u0004אולם \u0003חייבין\u0004 הם \u0003בתפילה ובמזוזה ובברכת המזון,\u0004 כאשר יבואר הדבר, ונימוקיו בגמרא.","על דברי המשנה שנשים פטורות מ\u0003קריאת שמע\u0004 מקשים: הלא דין זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שכן \u0003מצות עשה שהזמן גרמא\u0004 הוא, ועל פי הכלל כי \u0003כל מצות עשה שהזמן גרמא,\u0004 כלומר, שקיומה מותנה בזמן מסויים \u0003נשים פטורות\u0004 ממנה, ואף קריאת שמע שזמנה דווקא בבוקר ובערב, אינה מחייבת את הנשים, ומשום מה הוצרכה המשנה להזכיר את הדבר במיוחד?","ומתרצים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ואית\u0004 \u0005[ויש]\u0006 \u0003בה\u0004 בקריאת שמע קבלת עול \u0003מלכות שמים,\u0004 הרי בשל חשיבות הדבר יש אולי לחייב אף את הנשים לקרוא קריאת שמע, על כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 המשנה שלמרות זאת אין הנשים חייבות בקריאה.","\u0003ו\u0004עוד שנינו במשנה שנשים פטורות \u0003מן התפלין.\u0004 ושואלים: הלא גם דין זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי להנחת התפילין נקבע זמן (ביום ולא בלילה ולא בשבתות וחגים), ומדוע אם כן יש להדגיש את פטור הנשים מחובת תפילין? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ותפילין איתקש\u0004 \u0005[הוקשו,\u0006 הושוו\u0005]\u0006 בכתוב \u0003למזוזה,\u0004 שנאמר: \"וקשרתם לאות על ידיך והיו לטוטפות בין עיניך\" (דברים ו, ח) ומיד לאחר מכן נאמר \"וכתבתם על מזוזות ביתך ובשעריך\" (שם ט), ואפשר היה לחשוב שכשם שהנשים חייבות במזוזה תהיינה חייבות אף בתפילין, על כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 המשנה שבכל זאת נשים פטורות מתפילין.","\u0003ו\u0004עוד שנינו במשנה שנשים עבדים וקטנים \u0003חייבין בתפלה.\u0004 ומסבירים שאף שיש לה זמנים קבועים, והדבר לכאורה נותן שתיפטרנה הנשים מחובת תפילה, מכל מקום כיון \u0003דרחמי נינהו\u0004 \u0005[ש\u0006בקשת \u0005רחמים הם],\u0006 על כן כיון שאף הנשים צריכות לבקש על רחמי שמים, לכן חייבות הן בתפילה. ואולם מאחר ש\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ו\u0004על התפילה \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ערב ובקר וצהרים\u0004 אשיחה ואהמה וישמע קולי\u0003\"\u0004 (תהלים נה, יח), ואם כן אולי התפילה \u0003כמצות עשה שהזמן גרמא דמי\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 — על כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 המשנה שמצוות התפילה בעיקרה אין קבוע לה זמן והכל אם כן חייבים בה.","\u0003ו\u0004עוד שנינו במשנה שנשים חייבות \u0003במזוזה.\u0004 ושואלים: גם דין זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006! וכי משום מה לא תהיינה חייבות? והרי היא מצות עשה שלא הזמן גרמה! ומתרצים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003הואיל ואתקש\u0004 \u0005[והוקשה,\u0006 הושוותה\u0005]\u0006 במקרא פרשת מזוזה \u0003ל\u0004מצוות \u0003תלמוד תורה,\u0004 שבתורה הן פרשיות סמוכות (דברים יא, יט-כ), והיה איפוא מקום לומר שהן פטורות ממצות מזוזה כשם שהן פטורות מתלמוד תורה, על כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 המשנה במפורש שהן חייבות.","\u0003ו\u0004עוד שנינו במשנה שנשים חייבות \u0003בברכת המזון.\u0004 ושואלים: גם דין זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים כי \u0003הואיל וכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"בתת ה' לכם בערב בשר לאכל ולחם בבקר לשבע\"\u0004 (שמות טז, ח) ואפשר היה להבין שמצות ברכת המזון \u0003כמצות עשה שהזמן גרמא דמי\u0004 \u0005[נחשבת],\u0006 שהתורה קבעה זמנים מסויימים לסעודה, ועל כן גם ברכת המזון שייכת לזמנים אלה, ולכן נשים פטורות ממנה — על כן היה צורך בהדגשה החוזרת במשנה.","\u0003אמר רב אדא בר אהבה: נשים חייבות ב\u0004עשיית \u0003קידוש היום\u0004 של שבת \u0003דבר תורה.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הרי הקידוש הוא בודאי \u0003מצות עשה שהזמן גרמא, וכל מצות עשה שהזמן גרמא נשים פטורות\u0004 ממנה! \u0003אמר אביי:\u0004 הנשים אכן אינן חייבות בקידוש אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולא מדין תורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 שתי דחיות להסבר זה, ראשית, \u0003והא\u0004 \u0005[והרי]\u0006 רב אדא בר אהבה שאמר הלכה זו שהנשים חייבות בקידוש הלא הוא עצמו שהיא \"\u0003דבר תורה\" קאמר\u0004 \u0005[אמר].\u0006 \u0003ועוד,\u0004 אף עצם ההסבר אינו מובן, שאם כן שמוסיפים חכמים תקנות מסוג זה, אף \u0003כל מצות עשה\u0004 אף שפטורות הנשים מהן מדין תורה, מכל מקום \u0003נחייבינהו מדרבנן\u0004 \u0005[נחייב אותן\u0006 לקיימן \u0005מדברי סופרים]!\u0006","\u0003אלא אמר רבא:\u0004 יש לדבר הסבר מיוחד. בעשרת הדברות שבספר שמות נאמר \u0003\"זכור\u0004 את יום השבת לקדשו\u0003\"\u0004 (שמות כ, ח), ואילו בספר דברים נאמר \u0003\"שמור\u0004 את יום השבת לקדשו\" (דברים ה, יב), ושתי נוסחות אלה למדות זו מזו, ויכולים אנו להסיק מכך ש\u0003כל שישנו ב\u0004חובת \u0003שמירה\u0004 של השבת מלחללה, \u0003ישנו\u0004 גם \u0003ב\u0004מצות \u0003זכירה\u0004 של השבת בקידוש. \u0003והני נשי\u0004 \u0005[ואותן הנשים]\u0006 \u0003הואיל ואיתנהו\u0004 \u0005[וישנן]\u0006 \u0003בשמירה, איתנהו\u0004 \u0005[ישנן]\u0006 גם \u0003בזכירה.\u0004 שהרי בענין שמירת השבת כל ישראל מצווים בשווה להמנע מלחללה, ומכיון שכך נתחייבו אף הנשים בעשיית זכרון ליום השבת בקידוש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא:\u0004 מן המשנה למדנו ש\u0003נשים\u0004 חייבות \u0003בברכת המזון,\u0004 ואולם האם חיובן הוא \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 או רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים]?\u0006 \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006 למעשה\u0005]?\u0006 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 בברכתן את ה\u0003רבים ידי חובתן,\u0004 כאשר הן מברכות עבור הרבים. שכן \u0003אי אמרת בשלמא דאורייתא\u0004 \u0005[נניח אם אומר אתה\u0006 שחיובן \u0005מן התורה],\u0006 \u0003אתי דאורייתא ומפיק דאורייתא\u0004 \u0005[בא\u0006 זה שחיובו \u0005מן התורה ומוציא\u0006 את החייבים \u0005מן התורה].\u0006 \u0003אלא אי אמרת דרבנן\u0004 \u0005[אם אומר אתה\u0006 שחיובן מדברי \u0005סופרים],\u0006 אם כן הנשים \u0003הוי\u0004 \u0005[הינן]\u0006 מצד הדין שבתורה בגדר \u0003\"שאינו מחוייב בדבר\", ו\u0004כלל הוא ש\u0003כל שאינו מחוייב בדבר אינו\u0004 יכול להיות \u0003מוציא\u0004 באותו דבר \u0003את הרבים ידי חובתן.\u0004 ולכן יש חשיבות לדעת \u0003מאי\u0004 \u0005[מה]\u0006 המסקנה בדבר.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בבריתא: \u0003באמת אמרו\u0004 ש\u0003בן מברך\u0004 עבור \u0003אביו ועבד מברך לרבו ואשה מברכת לבעלה, אבל אמרו חכמים: תבא מארה לאדם\u0004 הנזקק לכך \u0003שאשתו ובניו מברכים לו\u0004 והוא אינו יודע לברך בעצמו.","ומכאן אפשר להסיק \u0003אי אמרת בשלמא דאורייתא\u0004 \u0005[נניח אם אומר אתה\u0006 שחיובן \u0005מן התורה],\u0006 \u0003אתי דאורייתא ומפיק דאורייתא\u0004 \u0005[בא\u0006 זה שחיובו \u0005מן התורה ומוציא\u0006 את החייבים \u0005מן התורה].\u0006 \u0003אלא אי אמרת דרבנן, אתי דרבנן ומפיק דאורייתא\u0004 \u0005[אם אומר אתה\u0006 שחיובן רק \u0005מדברי סופרים,\u0006 איך יתכן ש\u0005יבוא\u0006 המחוייב \u0005מדברי סופרים ויוציא\u0006 את המחויב \u0005מן התורה]?!\u0006","על הוכחה זו מקשים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 האם \u0003קטן בר חיובא\u0004 \u0005[בן חיוב\u0006 מצוות מן התורה\u0005]\u0006 \u0003הוא?\u0004 שהרי לכל הדעות קטן פטור מן התורה, ובכל זאת נאמר כאן שהוא מברך עבור אביו. ודאי יש להבין את הדבר בדרך שונה ולומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שאכל\u0004 פחות מכדי שביעה שזהו \u0003שיעורא דרבנן\u0004 \u0005[שיעור\u0006 שחייב עליו ברכת המזון רק \u0005מדברי סופרים]\u0006 ולא מדין התורה, ואז \u0003אתי רבנן ומפיק דרבנן\u0004 \u0005[בא\u0006 מי שחיובו \u0005מדברי סופרים ומוציא\u0006 אחר שחיובו \u0005מדברי סופרים].\u0006","מאחר שהוזכרה ההלכה שמדברי סופרים יש לברך אף על פחות מכדי שיעור שביעה, מביאים את מה ש\u0003דרש\u0004 בענין זה \u0003ר' עוירא,\u0004 ש\u0003זמנין\u0004 \u0005[לפעמים]\u0006 \u0003אמר לה\u0004 \u0005[אותה]\u0006 דרשה \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אמי וזמנין\u0004 \u0005[ולפעמים]\u0006 \u0003אמר לה\u0004 \u0005[אותה]\u0006 דרשה \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אסי: אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, כתוב בתורתך \"\u0004האל הגדול הגבור והנורא \u0003אשר לא ישא פנים ולא יקח שחד\"\u0004 (דברים י, יז) \u0003והלא\u0004 בכל זאת \u0003אתה נושא פנים לישראל, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ישא ה' פניו אליך\u0004 וישם לך שלום\u0003\"\u0004 (במדבר ו, כו)?! \u0003אמר להם: וכי לא אשא פנים לישראל,\u0004 והרי \u0003כתבתי להם בתורה \"ואכלת ושבעת וברכת את ה' אלהיך\"\u0004 (דברים ח, י), והרי שאין חובת ברכה אלא כשאוכל כדי שביעה, \u0003ו\u0004אילו \u0003הם מדקדקים על עצמם\u0004 לברך אפילו \u0003עד כזית ועד כביצה,\u0004 ומאחר שהם עושים לפנים משורת הדין, אף הם ראויים לנשיאת פנים.","עזרא הסופר תקן שבעל קרי לא יעסוק בדברי תורה אלא אם כן טבל וטהר לפני כן. הלכה זו עצמה היתה מקובלת במשך דורות רבים, ואולם נתעוררו מחלוקות מרובות מה הם בדיוק דברי התורה שעליהם חלה תקנה זו. ועל כך אומרת המשנה: הגיע זמן קריאת שמע והוא \u0003בעל קרי\u0004 — אינו אלא \u0003מהרהר\u0004 קריאת שמע \u0003בלבו, ואינו מברך\u0004 בדיבור פה בקריאת שמע כלל, \u0003לא\u0004 בברכות \u0003לפניה ולא לאחריה. ועל המזון\u0004 שחייב מן התורה בברכה עליו \u0003מברך לאחריו ואינו מברך לפניו,\u0004 שכן הברכה שלפני המזון הריהי אך מדברי חכמים. \u0003ור' יהודה\u0004 מתיר בכל המקרים הללו ו\u0003אומר: מברך לפניהם ולאחריהם.\u0004","\u0003אמר רבינא:\u0004 מן המשנה אפשר להסיק: \u0003זאת אומרת הרהור כדבור דמי\u0004 \u0005[נחשב].\u0006 \u0003דאי סלקא דעתך לאו כדבור דמי\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר כי \u0005אינו נחשב כדיבור]\u0006 אם כן \u0003למה מהרהר\u0004 בעל קרי? אלא ודאי ההרהור הריהו כדיבור מפורש.","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה — ש\u0003הרהור\u0004 דינו \u0003כדבור דמי\u0004 \u0005[נחשב],\u0006 הרי אם הותר הבעל קרי בהרהור והרהור הוא כדיבור, אם כן מדוע לא \u0003יוציא\u0004 כבר את הדברים במפורש \u0003בשפתיו?\u0004","ומתרצים: \u0003כדאשכחן\u0004 \u0005[כפי שמצאנו]\u0006 \u0003ב\u0004הר \u0003סיני\u0004 שכל בועל אשה פרש וטבל לפני קבלת התורה, ואף כאן תקנו שבעל קרי לא יאמר בפיו דברי תורה.","\u0003ו\u0004אילו \u0003רב חסדא אמר\u0004 שיש להוציא ממשנה זו מסקנה הפוכה, ולדעתו \u0003הרהור לאו\u0004 \u0005[לא]\u0006 \u0003כדבור דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר ש\u0003הרהור\u0004 הוא אכן \u0003כדבור,\u0004 אם כן \u0003יוציא\u0004 בעל קרי לכתחילה \u0003בשפתיו.\u0004","על הוכחה זו מקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר כי \u0003הרהור לאו\u0004 \u0005[לא]\u0006 \u0003כדבור דמי\u0004 \u0005[נחשב],\u0006 אם כן \u0003למה מהרהר?\u0004 ו\u0003אמר ר' אלעזר: כדי שלא יהו כל העולם עוסקין בו והוא יושב ובטל.\u0004","על כך שואלים: אם רק זו הכוונה, אם כן \u0003ונגרוס בפרקא אחרינא\u0004 \u0005[וילמד בפרק אחר]\u0006 ולא דווקא בקריאת שמע או ברכה! \u0003אמר רב אדא בר אהבה:\u0004 ראוי שיעסוק אדם \u0003בדבר שהצבור עוסקין בו.\u0004"],["על כך מקשים: \u0003והרי תפלה,\u0004 שאף היא \u0003דבר שהצבור עסוקין בו, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003היה עומד בתפלה, ונזכר שהוא בעל קרי\u0004 ולא טבל — \u0003לא יפסיק\u0004 את התפילה, \u0003אלא יקצר.\u0004 ויש לדייק: \u0003טעמא דאתחיל\u0004 \u0005[טעם\u0006 הדבר דווקא \u0005ש\u0006כבר \u0005התחיל]\u0006 בה, בתפילה, \u0003הא\u0004 \u0005[הרי]\u0006 אם עדיין \u0003לא אתחיל\u0004 \u0005[התחיל]\u0006 בה — \u0003לא יתחיל\u0004 ואפילו בהרהור!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003תפלה דלית\u0004 \u0005[שאין]\u0006 \u0003בה\u0004 קבלת עול \u0003מלכות שמים.\u0004 הסבר זה דוחים: \u0003והרי ברכת המזון לאחריו דלית\u0004 \u0005[שאין]\u0006 אף \u0003בה מלכות שמים, ו\u0004בכל זאת \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ש\u0003על המזון מברך לאחריו ואינו מברך לפניו! אלא\u0004 עלינו להסביר את ההבדלים באופן אחר: \u0003קריאת שמע וברכת המזון\u0004 הריהן \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ותפלה\u0004 אינה אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד. ועל כן, כשהוא טמא אינו צריך להתפלל.","\u0003אמר רב יהודה: מנין לברכת המזון לאחריה,\u0004 אחרי אכילתו, שהיא חובה \u0003מן התורה\u0004 — \u0003שנאמר: \"ואכלת ושבעת וברכת\"\u0004 (דברים ח, י).","ו\u0003מנין\u0004 שיש \u0003ל\u0004ברך \u0003ברכת התורה לפניה,\u0004 לפני קריאתה — \u0003שנאמר: \"כי שם ה' אקרא הבו גדל לאלהינו\"\u0004 (שם לב, ג), כלומר, לפני שאני קורא את שם ה' בתורה, הבו תחילה גודל לאלהינו.","\u0003אמר ר' יוחנן: למדנו\u0004 שיש לברך \u0003ברכת התורה לאחריה מן ברכת המזון\u0004 בדרך \u0003קל וחומר,\u0004 ואת חובת \u0003ברכת המזון לפניה\u0004 למדים \u0003מן ברכת התורה\u0004 בדרך \u0003קל וחומר. ברכת התורה לאחריה מן ברכת המזון מקל וחומר\u0004 בדרך זו: \u0003מה מזון שאין טעון\u0004 מן התורה ברכה \u0003לפניו,\u0004 ועם כל זה \u0003טעון\u0004 הוא ברכה \u0003לאחריו,\u0004 ה\u0003תורה שטעונה\u0004 ברכה \u0003לפניה, אינו דין\u0004 (כל שכן) \u0003שטעונה\u0004 ברכה \u0003לאחריה. ו\u0004לצד שני: \u0003ברכת המזון לפניה מן ברכת התורה\u0004 למדים \u0003מקל וחומר: ומה תורה שאין טעונה\u0004 ברכה \u0003לאחריה\u0004 מן התורה, \u0003טעונה\u0004 ברכה \u0003לפניה,\u0004 ה\u0003מזון שהוא טעון\u0004 ברכה \u0003לאחריו, אינו דין שיהא טעון לפניו.\u0004","על כך מעירים: \u0003איכא למפרך\u0004 \u0005[אפשר לפרוך,\u0006 לשבור\u0005]\u0006 את תוקף קל וחומר זה, ולומר: \u0003מה למזון שכן נהנה\u0004 באכילתו ואין אם כן ללמוד מחובת הברכה עליו לגבי דברים שאין בהם הנאה גשמית. \u0003ו\u0004כן אין ללמוד מן התורה, שכן יש לומר: \u0003מה לתורה שכן\u0004 בזכותה מגיעים ל\u0003חיי עולם\u0004 ולכן חייבים לברך, מה שאין כן המזון. \u0003ועוד, תנן\u0004 \u0005[\u0006הרי \u0005שנינו\u0006 במשנה\u0005]\u0006 שבעל קרי \u0003על המזון מברך לאחריו ואינו מברך לפניו,\u0004 הרי שהמשנה אינה משווה את ברכת המזון לפניה לברכת התורה. והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 המבטלת את דברי ר' יוחנן.","\u0003אמר רב יהודה:\u0004 מי שהיה לו \u0003ספק\u0004 אם \u0003קרא קריאת שמע, ספק לא קרא\u0004 — \u0003אינו חוזר וקורא.\u0004 ואולם אם ה\u0003ספק\u0004 אם \u0003אמר \"אמת ויציב\", ספק לא אמר\u0004 — \u0003חוזר ואומר \"אמת ויציב\". מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — משום שלדעתו חובת \u0003קריאת שמע\u0004 היא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ואנו נוהגים לפי הכלל שמקילים בכל ספק שמדבריהם. ואילו ברכת \u0003\"אמת ויציב\"\u0004 מאחר שבעיקרה הזכרת יציאת מצרים, הריהי מבטאת אם כן מצוה \u0003דאורייתא\u0004 \u0005[שמן התורה],\u0006 ובמקום ספק — יש לחזור ולאמרה.","על כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף:\u0004 איך יכול אתה לומר כי חובת קריאת שמע אינה אלא מדברי סופרים, והלא במפורש כתוב \u0003\"\u0004ושננתם לבניך ודברת בם בשבתך בביתך ובלכתך בדרך \u0003ובשכבך ובקומך\"\u0004 (דברים ו, ז). על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הפסוק \u0003ההוא בדברי תורה כתיב\u0004 \u0005[נאמר],\u0006 שאין הכרח לפרש כמקובל שפסוק זה מחייב לקרוא את שמע, אלא בחובת לימוד בדברי תורה בכלל.","ומנסים מעתה לברר את הבעיה בהבאת ראיה ממה ששנינו במשנה, \u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003בעל קרי מהרהר בלבו ואינו מברך\u0004 בשפתיו, \u0003לא לפניה,\u0004 לפני קריאת שמע, \u0003ולא לאחריה. ועל המזון מברך לאחריו ,\u0004 אחרי אכילתו, ואינו מברך לפניו, לפני אכילתו.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך]\u0006 לומר ש\u0003\"אמת ויציב\" דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003לברוך\u0004 \u0005[שיברך]\u0006 \u0003לאחריה!\u0004 ומאחר שאינו מברך, משמע שאינו חייב.","על כך עונים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 משום מה\u0005]\u0006 \u0003מברך\u0004 \"אמת ויציב\", \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום\u0004 שיש בעיקרה \u0003יציאת מצרים\u0004 — \u0003הא אדכר ליה\u0004 \u0005[הרי הזכיר אותה]\u0006 כבר \u0003בקריאת שמע\u0004 בפרשת ציצית.","ומקשים: \u0003ונימא הא\u0004 \u0005[ויאמר\u0006 את \u0005זאת,\u0006 \"אמת ויציב\"\u0005]\u0006 \u0003ולא לבעי הא\u0004 \u0005[יצטרך\u0006 את \u0005זאת,\u0006 קריאת שמע\u0005]!\u0006 ומשיבים: מאחר שאפשר להזכיר יציאת מצרים גם בקריאת שמע וגם ב\"אמת ויציב\" הרי \u0003קריאת שמע עדיפא\u0004 (עדיפה), משום \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה תרתי\u0004 \u0005[שתים],\u0006 גם הזכרת יציאת מצרים וגם קבלת עול מלכות שמים.","\u0003ור' אלעזר אמר\u0004 שיטה אחרת: ספק אם \u0003קרא קריאת שמע, ספק לא קרא\u0004 — \u0003חוזר וקורא קריאת שמע,\u0004 שלדעתו חובת קריאת שמע מן התורה. אך אם היה \u0003ספק\u0004 בידו אם \u0003התפלל\u0004 או \u0003ספק לא התפלל\u0004 — \u0003אינו חוזר ומתפלל.\u0004 שהתפילה רק מדברי סופרים. \u0003ור' יוחנן אמר:\u0004 צריך לחזור ולהתפלל, שבכל אופן \u0003ולואי שיתפלל אדם כל היום כולו.\u0004","\u0003ואמר רב יהודה אמר שמואל:\u0004 מי ש\u0003היה עומד בתפלה ונזכר ש\u0004כבר \u0003התפלל\u0004 — \u0003פוסק\u0004 מתפילתו, \u0003ואפילו\u0004 הוא עומד \u0003באמצע ברכה.\u0004 על כך מקשים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן היא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רבה בר אבוה בען מיניה\u0004 \u0005[שאלנו אותו]:\u0006 \u0003הני\u0004 \u0005[אותם]\u0006 \u0003בני בי\u0004 \u0005[בית,\u0006 מדרשו\u0005]\u0006 של \u0003רב\u0004 ש\u0003טעו ומדכרי\u0004 \u0005[והזכירו\u0006 ברכה\u0005]\u0006 של \u0003חול בשבת, מהו שיגמרו\u0004 תפילת חול? \u0003ואמר לן\u0004 \u0005[לנו]\u0006 רבה בר אבוה כפסק הלכה: \u0003גומרין כל אותה ברכה,\u0004 וכיצד אם כן אמר רב יהודה שפוסק אפילו באמצע ברכה?!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]!\u0006 \u0003התם\u0004 \u0005[שם\u0006 ביום השבת\u0005]\u0006 \u0003גברא בר חיובא\u0004 \u0005[האדם מחוייב]\u0006 \u0003הוא,\u0004 וראוי היה לו להתפלל כל שמונה עשרה ברכות, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003הוא\u0004 ש\u0003לא אטרחוהו\u0004 \u0005[הטריחוהו]\u0006 \u0003משום כבוד שבת\u0004 וקבעו נוסח מקוצר, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003הא צלי ליה\u0004 \u0005[הרי התפלל\u0006 כבר\u0005],\u0006 ולכן יכול להפסיק אף באמצע הברכה.","\u0003ואמר רב יהודה אמר שמואל:\u0004 מי שכבר \u0003התפלל ונכנס לבית הכנסת\u0004 לאחר תפילתו \u0003ומצא צבור ש\u0004עומדים ו\u0003מתפללין, אם יכול לחדש בה\u0004 בתפילה \u0003דבר\u0004 בביטויים או בבקשות — \u0003יחזור ויתפלל, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אל יחזור ויתפלל.\u0004","ומעירים: אף שרעיון זה זהה לדבר הקודם שאמר שמואל שמי שהתפלל כבר אינו צריך לחזור ולהתפלל, בכל זאת \u0003צריכא\u0004 \u0005[צריך]\u0006 היה לומר את שני הדברים, \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 את ההלכה \u0005הראשונה]\u0006 בלבד, היינו אומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 הם דווקא במקרה שהיה זה \u0003יחיד ויחיד\u0004"],["\u0003או צבור וצבור, אבל יחיד\u0004 שהתפלל לעצמו ועכשיו הוא בא למקום תפילת הציבור היינו אומרים כי \u0003לגבי צבור כמאן\u0004 \u0005[כמי]\u0006 ש\u0003לא צלי דמי\u0004 \u0005[התפלל\u0006 הוא \u0005נחשב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם במקרה זה אינו צריך לחזור. \u0003ו\u0004מצד שני, \u0003אי אשמעינן הכא\u0004 \u0005[אילו היה משמיע לנו פה\u0006 בנכנס לבית הכנסת\u0005]\u0006 היינו אומרים שטעמו \u0003משום\u0004 ש\u0003לא אתחיל\u0004 \u0005[התחיל]\u0006 \u0003בה\u0004 בתפילה, \u0003אבל התם דאתחיל\u0004 \u0005[שם שהתחיל]\u0006 \u0003בה\u0004 בתפילה, \u0003אימא\u0004 \u0005[\u0006הייתי \u0005אומר]\u0006 ש\u0003לא.\u0004 ועל כן נצרכות להיאמר שתי האמרות.","\u0003אמר רב הונא:\u0004 אדם שלא התפלל \u0003הנכנס לבית הכנסת ומצא צבור שמתפללין\u0004 תפילת שמונה עשרה, \u0003אם יכול\u0004 הוא \u0003להתחיל ולגמור\u0004 את תפילתו \u0003עד שלא יגיע שליח צבור ל\"מודים\"\u0004 — \u0003יתפלל. ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אל יתפלל. ר' יהושע בן לוי אמר: אם יכול להתחיל\u0004 להתפלל \u0003ולגמור\u0004 תפילתו \u0003עד שלא יגיע שליח הציבור ל\"קדושה\"\u0004 — \u0003יתפלל, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אל יתפלל.\u0004","ומבארים: \u0003במאי קא מפלגי\u0004 \u0005[במה הם חולקים,\u0006 מהו הבסיס העקרוני למחלוקת זו\u0005]\u0006 — \u0003מר סבר\u0004 \u0005[חכם\u0006 זה\u0005,\u0006 רב הונא \u0005סבור]\u0006 ש\u0003יחיד אומר,\u0004 רשאי לומר, \u0003\"קדושה\"\u0004 בעצמו, ולכן אינו צריך להקפיד לומר קדושה עם שליח הציבור \u0003ומר סבר\u0004 \u0005[חכם\u0006 זה\u0005,\u0006 ר' יהושע בן לוי \u0005סבור]\u0006 ש\u0003אין יחיד אומר \"קדושה\",\u0004 ולכן לדעתו הוא צריך לסיים את תפילתו לפני קדושה.","\u0003וכן אמר רב אדא בר אהבה\u0004 כדעה השניה: \u0003מנין שאין היחיד אומר \"קדושה\"\u0004 בעצמו — \u0003שנאמר: \"ונקדשתי בתוך בני ישראל\"\u0004 (ויקרא כב, לב), ומכאן למדים: \u0003כל דבר שבקדושה לא יהא\u0004 נאמר ב\u0003פחות מעשרה.\u0004","על כך שואלים: \u0003מאי משמע\u0004 \u0005[מהי המשמעות],\u0006 כלומר, כיצד אפשר להסיק מן הפסוק את ההלכה הזו? ומשיבים: יש להבין את הדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רבנאי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' חייא בר אבא\u0004 שההוכחה \u0003אתיא\u0004 \u0005[באה]\u0006 בגזירה שווה מן המילים השוות \u0003\"תוך\" \"תוך\". כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ונקדשתי בתוך בני ישראל\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 לגבי עדת קרח \u0003\"הבדלו מתוך העדה הזאת\"\u0004 (במדבר טז, כא), \u0003מה להלן עשרה\u0004 (ודבר זה עצמו נלמד מגזירה שווה מהמילים \"עדה\" \"עדה\" מפרשת המרגלים, ששם נאמר \"עד מתי לעדה הרעה הזאת\", ושם היו עשרה מרגלים. ראה מגילה כג, ב), \u0003אף כאן עשרה,\u0004 הרי ש\"תוך\" הקהל הוא עשרה לפחות.","\u0003ודכולי עלמא מיהת מפסק לא פסיק\u0004 \u0005[ולדעת הכל,\u0006 לשתי הדעות בכל אופן ברור \u0005שאינו מפסיק\u0006 מתפילתו כדי לענות קדושה\u0005].\u0006","ואולם \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמי הישיבה שאלה זו\u0005]:\u0006 \u0003מהו\u0004 הדין בענין \u0003להפסיק\u0004 מתפילתו \u0003ל\u0004צורך אמירת \u0003\"יהא שמו הגדול מבורך\"\u0004 שבקדיש? \u0003כי אתא\u0004 \u0005[\u0006כאשר \u0005בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: ר' יהודה ור' שמעון תלמידי ר' יוחנן אמרו: לכל אין מפסיקין\u0004 את התפילה \u0003חוץ מן \"יהא שמו הגדול מבורך\" שאפילו\u0004 היה אדם \u0003עוסק ב\u0004לימוד הנשגב של \u0003מעשה מרכבה\u0004 — \u0003פוסק,\u0004 ואומר. ואולם בגמרא מסכמים: \u0003ולית הלכתא כותיה\u0004 \u0005[ואין הלכה כמותו].\u0006","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 שבעל קרי \u0003מברך לפניהם ולאחריהם\u0004 בין בקריאת שמע ובין על המזון. ושואלים: \u0003למימרא דקסבר\u0004 \u0005[האם\u0006 יש \u0005לומר שסבר]\u0006 \u0003ר' יהודה\u0004 ש\u0003בעל קרי מותר בדברי תורה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי, מנין\u0004 ראיה מן התורה עצמה ש\u0003בעל קרי אסור בדברי תורה\u0004 — \u0003שנאמר: \"\u0004רק השמר לך ושמור נפשך מאד פן תשכח את הדברים אשר ראו עיניך ופן יסורו מלבבך כל ימי חייך \u0003והודעתם לבניך ולבני בניך\"\u0004 (דברים ד, ט), שמכאן לומדים אנו, בין השאר, חובת תלמוד תורה, \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק \u0003\"יום אשר עמדת\u0004 לפני ה' אלהיך בחורב\u0003\"\u0004 (שם י), וסמיכות זו באה ללמדנו, \u0003מה להלן במעמד הר סיני בעלי קריין אסורין,\u0004 שהיה עליהם לפרוש ולטבול תחילה, \u0003אף כאן\u0004 בתלמוד תורה בכל הדורות \u0003בעלי קריין אסורין!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' יהודה לא דריש\u0004 \u0005[דורש]\u0006 \u0003\"סמוכים\",\u0004 שלדעתו אין ללמוד מסמיכותם של שני פסוקים בתורה ולהסיק מכך מסקנות, \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003רב יוסף: אפילו מאן\u0004 \u0005[מי]\u0006 ש\u0003לא דריש\u0004 \u0005[דורש]\u0006 \u0003\"סמוכין\" בכל התורה כולה,\u0004 מכל מקום \u0003במשנה תורה\u0004 (בספר דברים) — \u0003דריש\u0004 \u0005[\u0006הוא \u0005דורש].\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' יהודה לא דריש\u0004 \u0005[דורש]\u0006 \u0003\"סמוכין\" בכל התורה כולה ו\u0004אילו \u0003במשנה תורה\u0004 (בספר דברים) — \u0003דריש\u0004 \u0005[דורש].\u0006","\u0003ובכל התורה כולה מנא לן\u0004 \u0005[מנין לנו]\u0006 ש\u0003לא דריש\u0004 \u0005[דורש]\u0006 ר' יהודה \"סמוכים\" — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 הדנה בעונש המכשפה, \u0003בן עזאי אומר,\u0004 בכתוב \u0003נאמר: \"מכשפה לא תחיה\"\u0004 (שמות כב, יז), אך לא פורש באיזו מיתה לדון אותה, \u0003ונאמר: \"כל שוכב עם בהמה מות יומת\"\u0004 (שם יח) — וזה ש\u0003סמכו ענין לו\u0004 הרי זה כדי \u0003לומר: מה שוכב עם בהמה\u0004 ענשו \u0003בסקילה\u0004 (עיין ויקרא כ), \u0003אף מכשפה\u0004 דינה \u0003נמי בסקילה.\u0004","ועל ראיה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה: וכי מפני שסמכו ענין לו,\u0004 ששני הפסוקים סמוכים זה לזה בתורה \u0003נוציא\u0004 אדם \u0003זה לסקילה?\u0004 שאין לדון אותו על בסיס זה לחמורה שבמיתות. \u0003אלא\u0004 כך היא הראיה: שכן הרי \u0003אוב וידעוני בכלל כל המכשפים היו, ולמה יצאו\u0004 מן הכלל שהתייחד להם פסוק לעצמם \"ואיש או אשה כי יהיה בהם אוב או ידעוני מות יומתו באבן ירגמו אותם דמיהם בם\" (ויקרא כ, כז) — כדי \u0003להקיש\u0004 (להשוות) \u0003להן ולומר לך: מה אוב וידעוני\u0004 עונשם \u0003בסקילה\u0004 — \u0003אף מכשפה\u0004 עונשה \u0003בסקילה.\u0004","\u0003ובמשנה תורה מנא לן\u0004 \u0005[מנין לנו],\u0006 \u0003דדריש\u0004 \u0005[ש\u0006הוא \u0005דורש]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003ר' אליעזר אומר\u0004 ש\u0003נושא אדם\u0004 ואפילו מלכתחילה את \u0003אנוסת אביו\u0004 או \u0003מפותת אביו, וכן את אנוסת בנו ומפותת בנו,\u0004 ואף על פי שאשת אביו ואשת בנו אסורות עליו מן התורה, הרי איסור זה חל רק על אשה המיוחדת לו בקידושין, ולא על זו שאנסה.","\u0003ור' יהודה אוסר באנוסת אביו ובמפותת אביו. ואמר רב גידל אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לא יקח איש את אשת אביו ולא יגלה (את) כנף אביו\"\u0004 (דברים כג, א), שהביטוי האחרון \"ולא יגלה כנף אביו\" בא להדגיש: \u0003כנף שראה אביו\u0004 — \u0003לא יגלה\u0004 אותו הבן. כלומר, כל אשה שנבעלה לאב — אסורה לבן.","\u0003וממאי\u0004 \u0005[וממה,\u0006 מניין לנו\u0005]\u0006 ש\u0003באנוסת אביו כתיב\u0004 \u0005[נאמר\u0006 הפסוק\u0005]\u0006 — \u0003דסמיך ליה\u0004 \u0005[שסמוך לו]\u0006 הקטע הקודם העוסק בדין אונס \u0003\"ונתן האיש השוכב עמה\u0004 לאבי הנערה חמישים כסף... תחת אשר ענה\u0003\"\u0004 (שם כב, כט). בכל אופן רואים אנו שבספר דברים דורש גם ר' יהודה את סמיכות הפרשיות, ואם כן מדוע אינו לומד מסמיכות הפסוקים שבעל קרי אסור בדברי תורה?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה: \u0003אין\u0004 \u0005[כן]\u0006 \u0003במשנה תורה\u0004 אכן \u0003דריש\u0004 \u0005[דורש]\u0006 ר' יהודה \"סמוכים\", \u0003והני\u0004 \u0005[ואלה]\u0006 ה\u0003סמוכין מבעי ליה\u0004 \u0005[צריך הוא]\u0006 \u0003לאידך\u0004 \u0005[ל\u0006דרשה \u0005אחרת]\u0006 של \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: כל המלמד לבנו תורה מעלה עליו הכתוב\u0004 ומחשיב לו \u0003כאלו קבלה\u0004 את התורה \u0003מהר חורב. שנאמר: \"והודעתם לבניך ולבני בניך\"\u0004 (שם ד,ט) וכתיב בתריה \u0005[ונאמר\u0006 בפסוק ל' \u0005אחריו]:\u0006 \u0003\"יום אשר עמדת לפני ה' אלהיך בחרב\".\u0004 ומשום כך אין ר' יהודה לומד מכאן איסור לבעל קרי לעסוק בתורה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 כי \u0003זב שראה קרי, ונדה שפלטה שכבת זרע, וכן המשמשת\u0004 עם בעלה \u0003וראתה דם\u0004 נדה, אף על פי שיש בהם טומאה חמורה ואינם נטהרים ממנה אלא לאחר שבעה ימים לפחות, אף הם \u0003צריכין טבילה\u0004 להיטהר מטומאת קרי, כדי להתירם בדברי תורה. \u0003ור' יהודה\u0004 במקרה זה \u0003פוטר\u0004 מטבילה.","ואולם \u0003עד כאן לא\u0004 שמענו ש\u0003פטר ר' יהודה\u0004 מטבילה \u0003אלא ב\u0004מקרה של \u0003זב שראה קרי, דמעיקרא לאו\u0004 \u0005[שמתחילה לא]\u0006 \u0003בר טבילה הוא,\u0004 שהרי הוא נשאר טמא בטומאת זיבה גם אחר הטבילה, \u0003אבל בעל קרי גרידא\u0004 \u0005[בלבד]\u0006 אף ר' יהודה \u0003מחייב\u0004 בו טבילה כדי להתירו בדברי תורה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הוא הדין\u0004 ש\u0003אפילו\u0004 ב\u0003בעל קרי גרידא נמי\u0004 \u0005[בלבד גם כן]\u0006 \u0003פטר ר' יהודה\u0004 מטבילה, \u0003והאי דקא מפלגי\u0004 \u0005[וזה שהם חלוקים]\u0006 \u0003בזב שראה קרי\u0004 ולא בבעל קרי עצמו — הרי זה \u0003להודיעך\u0004 את \u0003כחן\u0004 (חומרתם) \u0003דרבנן\u0004 \u0005[של חכמים]\u0006 שאפילו במקרה זה מחייבים הם טבילה. אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את סופה] של אותה משנה: \u0003המשמשת וראתה דם\u0004 נדה — \u0003צריכה טבילה,\u0004 ונברר את הדבר:","הלכה זו \u0003למאן קתני לה\u0004 \u0005[ל\u0006שיטת \u0005מי שנה אותה],\u0006 כלומר, לפי דעתו של מי הובאה הלכה זו? \u0003אילימא לרבנן\u0004 \u0005[אם תאמר\u0006 שבאה ללמד שיטת \u0005חכמים],\u0006 הרי זהו \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שכן \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003ומה זב שראה קרי, דמעיקרא לאו\u0004 \u0005[שמתחילה לא]\u0006 \u0003בר טבילה הוא,\u0004 מכל מקום \u0003מחייבי רבנן\u0004 \u0005[מחייבים חכמים]\u0006 בכל זאת שיטבול, \u0003המשמשת וראתה דם\u0004 — ש\u0003מעיקרא בת טבילה היא לא כל שכן\u0004 שיחייבוה?! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 כשיטת \u0003ר' יהודה היא, ו\u0004ודאי בא קטע זה ללמד ש\u0003דוקא\u0004 לשם דיוק והדגשה \u0003קתני לה\u0004 \u0005[שנה\u0006 אותה\u0005]\u0006 בדרך זו, ללמד כי"],["\u0003משמשת וראתה נדה\u0004 — \u0003אינה צריכה טבילה, אבל בעל קרי גרידא\u0004 \u0005[בלבד]\u0006 — \u0003מחייב\u0004 \u0005[מחוייב],\u0006 ואם כן, עלינו לפרש את דברי ר' יהודה במשנה \"מברך לפניהם ואחריהם\" באופן זה: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003\"מברך\"\u0004 בפיו דווקא, אלא הכוונה היא \u0003מהרהר,\u0004 שצריך להרהר בלבו דברי ברכות אלה.","על הסבר זה מקשים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 האם סבור\u0005]\u0006 \u0003ר' יהודה\u0004 שיש תוקף ל\u0003הרהור? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בעל קרי שאין לו מים לטבול\u0004 בהם לטהרתו — \u0003קורא קריאת שמע, ו\u0004אולם \u0003אינו מברך\u0004 את ברכות קריאת שמע, \u0003לא\u0004 אלו ש\u0003לפניה ולא\u0004 ש\u0003לאחריה. ואוכל פתו\u0004 (לחם) \u0003ומברך לאחריה\u0004 את ברכת המזון, \u0003ואינו מברך לפניה\u0004 את ברכת \"המוציא\". \u0003אבל\u0004 מכל מקום בכל המקרים הללו \u0003מהרהר\u0004 הוא \u0003בלבו ואינו מוציא בשפתיו,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר: בין כך ובין כך\u0004 בכל הברכות \u0003מוציא בשפתיו.\u0004 הרי שאין ר' יהודה רואה פתרון בהרהור הברכות ומתיר במפורש להוציא בשפתיו.","\u0003אמר רב נחמן בר יצחק:\u0004 יש לפרש את דברי ר' יהודה במשנה בדרך אחרת, ולומר כי \u0003עשאן ר' יהודה\u0004 את הברכות \u0003כהלכות דרך ארץ.\u0004 שלדעת חכמים אחדים אין הלכות אלה נחשבות לעניין זה כשאר דברי תורה, ומותר ללמדן אף בטומאה.","וכשיטה זו \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"והודעתם לבניך ולבני בניך\"\u0004 (דברים ד, ט), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו,\u0006 בפסוק הסמוך לו\u0005]\u0006 \u0003\"יום אשר עמדת לפני ה' אלהיך בחרב\"\u0004 (שם י), \u0003מה להלן\u0004 במתן תורה היה המעמד \u0003באימה וביראה וברתת ובזיע, אף כאן\u0004 לימוד התורה שבכל דור ודור צריך להיות \u0003באימה וביראה וברתת ובזיע.\u0004","\u0003מכאן אמרו\u0004 חכמים: \u0003הזבים והמצורעים ובאין על נדות,\u0004 אף שטומאתם חמורה — \u0003מותרים לקרות בתורה ובנביאים ובכתובים,\u0004 ו\u0003לשנות במשנה וגמרא ובהלכות ובאגדות. אבל בעלי\u0004 קריין אסורים, שכן הטומאות החמורות באות כדרך מחלה או אונס והטמא יכול שיהיה באימה וביראה בעת שלומד תורה, מה שאין כן טומאת קרי לסוגיה שמקורה הוא קלות ראש והסרת האימה והיראה, ולכן אין ראוי שבעל קרי יעסוק בתורה. ואולם רבו הדעות מה הוא גדרם המדוייק של דברי התורה האסורים ללימוד לבעלי קרי.","ש\u0003ר' יוסי אומר: שונה הוא\u0004 בעל הקרי \u0003ב\u0004משניות ה\u0003רגיליות\u0004 (שהוא רגיל בהן), \u0003ובלבד שלא יציע\u0004 לפני עצמו \u0003את המשנה\u0004 החדשה ללימוד בדרך עיון. \u0003ר' יונתן בן יוסף\u0004 מיקל ו\u0003אומר: מציע הוא את המשנה, ואינו מציע את הגמרא,\u0004 שהיא עומק העיון בתורה. \u0003ר' נתן בן אבישלום\u0004 מיקל ממנו ו\u0003אומר: אף מציע את הגמרא, ובלבד שלא יאמר\u0004 בפיו את \u0003אזכרות\u0004 שם ה' \u0003שבו. ר' יוחנן הסנדלר תלמידו של ר' עקיבא אומר משום\u0004 (בשם) \u0003ר' עקיבא\u0004 רבו: \u0003לא יכנס\u0004 בעל קרי \u0003למדרש,\u0004 כלומר, למדרש המקראות \u0003כל עיקר. ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 שכך אמר: \u0003לא יכנס לבית המדרש כל עיקר. ר' יהודה\u0004 מתיר לטמא קרי ו\u0003אומר: שונה הוא\u0004 את \u0003הלכות דרך ארץ\u0004 בלבד. ואם כן יש לומר ביחס לבעייה שהועלתה שגם הברכות נחשבות בעיני ר' יהודה כהלכות דרך ארץ ומותר לאמרן בפה.","בהמשך לדברים מסופר \u0003מעשה בר' יהודה\u0004 עצמו \u0003שראה קרי, והיה מהלך על גב\u0004 (שפת) \u0003הנהר\u0004 עם תלמידיו. \u0003אמרו לו תלמידיו: רבינו, שנה לנו פרק אחד בהלכות דרך ארץ,\u0004 שלשיטתו מותר לו הדבר לעשות זאת אף בטומאה. \u0003ירד וטבל\u0004 בנהר \u0003ושנה להם. אמרו לו: לא כך למדתנו רבינו, שונה הוא\u0004 שמותר לו לשנות \u0003בהלכות דרך ארץ?! אמר להם: אף על פי שמיקל אני על אחרים\u0004 ומתיר להם לשנות בלי טבילה, \u0003מחמיר אני על עצמי.\u0004","ועוד בענין לימוד תורה בטומאה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה בן בתירא היה אומר: אין דברי תורה מקבלין טומאה,\u0004 ולפיכך גם לטמא מותר לעסוק בתורה, וכן נהג גם הלכה למעשה. וכפי שמסופר \u0003מעשה בתלמיד אחד שהיה מגמגם למעלה מר' יהודה בן בתירא,\u0004 שאותו תלמיד בעל קרי היה, וכיון שנתנו לו לקרוא קרא בגמגום, משום שלא רצה לבטא את דברי התורה במפורש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה: \u0003בני, פתח פיך ויאירו דבריך, ש\u0004כן \u0003אין דברי תורה מקבלין טומאה, שנאמר: \"הלא כה דברי כאש נאום ה'\"\u0004 (ירמיהו כג, כט), \u0003מה אש אינו מקבל טומאה אף דברי תורה אינן מקבלין טומאה.\u0004","בברייתא הזאת \u0003אמר מר\u0004 \u0005[החכם]\u0006 שבעל קרי \u0003מציע,\u0004 כלומר, מותר לו להציע \u0003את המשנה ואינו מציע את הגמרא.\u0004 ומעירים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' אלעאי,\u0004 ש\u0003אמר ר' אלעאי אמר ר' אחא בר יעקב משום\u0004 (בשם) \u0003רבינו\u0004 (רב): \u0003הלכה\u0004 היא שבעל קרי \u0003מציע את המשנה ואינו מציע את הגמרא.\u0004 ומחלוקת זו היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו אף הם בנושא זה. ששנינו: בעל קרי \u0003מציע את המשנה ואינו מציע את הגמרא,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה בן גמליאל אומר משום ר' חנינא בן גמליאל: זה וזה אסור. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר: \u0003זה וזה מותר.\u0004","ובהקבלת הדעות: \u0003מאן דאמר\u0004 \u0005[זה שאומר]\u0006 ש\u0003זה וזה אסור\u0004 — הרי זה \u0003כ\u0004שיטת \u0003ר' יוחנן הסנדלר,\u0004 ו\u0003מאן דאמר\u0004 \u0005[\u0006ו\u0005זה שאומר]\u0006 ש\u0003זה וזה מותר\u0004 — הרי זה \u0003כ\u0004שיטת \u0003ר' יהודה בן בתירא.\u0004","ובסיכום ההלכה \u0003אמר רב נחמן בר יצחק: נהוג עלמא כהני תלת סבי\u0004 \u0005[נוהג העולם,\u0006 הכל נוהגים, \u0005כשלושה זקנים אלה]\u0006 — \u0003כ\u0004שיטת \u0003ר' אלעאי ב\u0004דיני \u0003ראשית הגז. כ\u0004שיטת \u0003ר' יאשיה ב\u0004דיני \u0003כלאיים, כ\u0004שיטת \u0003ר' יהודה בן בתירא בדברי תורה.\u0004","ומפרטים: \u0003כ\u0004שיטת \u0003ר' אלעאי בראשית הגז\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעאי אומר:\u0004 חובת הפרשת \u0003ראשית הגז\u0004 מן הצאן לכהן \u0003אינו נוהג אלא בארץ\u0004 ישראל ולא בחוצה לארץ, וכן נוהגים.","\u0003כ\u0004שיטת \u0003ר' יאשיה בכלאים, כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"לא תזרע כרמך כלאים\"\u0004 (דברים כב, ט), \u0003ר' יאשיה אומר:\u0004 יש לפרש ש\u0003לעולם אינו חייב\u0004 הזורע כלאים מן התורה אלא \u0003עד שיזרע חטה ושעורה וחרצן\u0004 ענבים \u0003במפולת יד,\u0004 כלומר, שבשעה שזורע את הכרם הריהו עובר באותה שעה גם על כלאי זרעים וגם על כלאי הכרם.","ו\u0003כ\u0004שיטת \u0003ר' יהודה בן בתירא\u0004 שמותר לבעל קרי לעסוק \u0003בדברי תורה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005] ,\u0006 \u0003ר' יהודה בן בתירא אומר: אין דברי תורה מקבלין טומאה.\u0004","וכפי שמסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003זעירי\u0004 מארץ ישראל לבבל, ביטא את סיכום ההלכה בענין זה בתמצית ו\u0003אמר: בטלוה לטבילותא\u0004 \u0005[לטבילה]\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003בטלוה לנטילותא\u0004 \u0005[לנטילה].\u0006 ובהסבר הדברים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003כי בטלוה לטבילותא\u0004 \u0005[לטבילה]\u0006 — משמעו קבלת שיטת \u0003ר' יהודה בן בתירא\u0004 שאין בעל קרי צריך לטבול. ו\u0003מאן דאמר\u0004 \u0005[ומי שאומר]\u0006 כי \u0003בטלוה לנטילותא\u0004 \u0005[לנטילה]\u0006 — \u0003כי הא\u0004 \u0005[הריהו]\u0006 כ\u0003רב חסדא\u0004 שהיה \u0003לייט אמאן דמהדר אמיא בעידן צלותא\u0004 \u0005[מקלל את מי שמחזר אחר מים\u0006 לנטילת ידיים \u0005בזמן התפילה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003בעל קרי שנתנו\u0004 (שפכו) \u0003עליו תשעה קבין מים\u0004 שאובים — די לו בכך כדי להיות \u0003טהור\u0004 ואינו חייב עוד לטבול במקווה. ומסופר: \u0003נחום איש גם זו לחשה\u0004 (אמר בצינעה) להלכה זו \u0003לר' עקיבא, ור' עקיבא לחשה לבן עזאי\u0004 תלמידו, \u0003ו\u0004אילו \u0003בן עזאי יצא ושנאה לתלמידיו בשוק\u0004 בפירסום. בגרסת הדבר \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה תרי אמוראי\u0004 \u0005[שני אמוראים]\u0006 \u0003במערבא\u0004 (בארץ ישראל), \u0003ר' יוסי בר אבין ור' יוסי בר זבידא. חד תני\u0004 \u0005[אחד\u0006 מהם \u0005שנה]:\u0006 בן עזאי \u0003שנאה\u0004 לתלמידיו בשוק, \u0003וחד תני\u0004 \u0005[ואחד\u0006 מהם \u0005שנה]:\u0006 \u0003בן עזאי\u0004 גם הוא \u0003לחשה\u0004 לתלמידיו.","ומסבירים את הבדלי הסברה שמאחורי הבדלי הנוסחה. \u0003מאן דתני\u0004 \u0005[מי ששנה,\u0006 אותו חכם שגרס\u0005]\u0006 שבן עזאי \u0003שנאה\u0004 להלכה זו בשוק בפרסום, הרי טעמו של דבר \u0003משום ביטול תורה,\u0004 כי מאחר שבעל קרי שלא טבל אסור בדברי תורה, הרי כל הקלה בדיני טבילתו מקילה עליו את הלימוד. \u0003ו\u0004כן \u0003משום ביטול פריה ורביה,\u0004 שמא יימנעו אנשים בגלל חובת הטבילה מפריה ורביה. \u0003ומאן דתני\u0004 \u0005[ומי ששנה,\u0006 החכם שגרס\u0005]\u0006 שבן עזאי רק \u0003לחשה\u0004 לתלמידיו ולא פירסם הלכה זו — כדי \u0003שלא יהיו תלמידי חכמים מצויים אצל נשותיהם כתרנגולים,\u0004 אם יהא קל כל כך להיטהר.","על עיקר טבילה זו \u0003אמר ר' ינאי: שמעתי שמקילין בה ושמעתי שמחמירין בה.\u0004 כלומר, לא נקבעה הלכה פסוקה בנושא זה, \u0003ו\u0004אולם \u0003כל המחמיר בה מאריכין לו ימיו ושנותיו.\u0004","מסופר ש\u0003אמר ר' יהושע בן לוי: מה טיבן של\u0004 בעלי קרי \u0003טובלי שחרין\u0004 (שחרית)? על כך תמהים: כיצד אפשר לשאול \u0003מה טיבן?! הא איהו\u0004 \u0005[הרי הוא\u0006 עצמו\u0005]\u0006 ש\u0003אמר\u0004 ש\u0003בעל קרי אסור בדברי תורה\u0004 וחייב הוא לטבול בשחרית. אלא יש לפרש ש\u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך היתה כוונתו\u0005]:\u0006 \u0003מה טיבן\u0004 בטבילה \u0003בארבעים סאה\u0004 של מים במקווה כשר, והלא \u0003אפשר\u0004 להיטהר גם \u0003בתשעה קבין.\u0004 וכן \u0003מה טיבן בטבילה\u0004 דווקא, הרי \u0003אפשר\u0004 גם \u0003בנתינה\u0004 של מים שאובים על הטמא.","על כך \u0003אמר ר' חנינא: גדר גדול גדרו בה\u0004 על ידי תקנת הטבילה בארבעים סאה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באחד שתבע אשה לדבר עבירה. אמרה לו: ריקא!\u0004 כלום \u0003יש לך ארבעים סאה שאתה טובל בהן\u0004 אחר כך להיטהר? \u0003מיד פירש\u0004 אותו אדם. הרי שחובת הטבילה גרמה למנוע אנשים מן העבירה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא\u0004 לחכמים: \u0003רבותי, מפני מה אתם מזלזלין בטבילה זו: אי\u0004 \u0005[אם]\u0006 \u0003משום צינה,\u0004 שקשה לכם לטבול במי המקוה הקרים, והלא \u0003אפשר\u0004 להיטהר מקריו \u0003במרחצאות\u0004 חמים, שאף כי אינם נחשבים כמקווה כשר לעניינים אחרים, דיים לטהרה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: וכי יש טבילה בחמין? אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: אכן, ספק בדבר כשרותה של טבילה מיוחדת זו אף במרחצאות כבר הועלה, ו\u0003רב אדא בר אהבה קאי כוותך\u0004 \u0005[עומד כמותך,\u0006 בשיטתך\u0005],\u0006 ואולם אני עומד בדעתי להכשיר.","מסופר: \u0003ר' זירא הוה יתיב באגנא דמיא בי מסותא\u0004 \u0005[היה יושב באגן\u0006 אמבטיה \u0005של מים בבית המרחץ],\u0006 \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003זיל ואייתי\u0004 \u0005[לך והבא]\u0006 \u0003לי תשעה קבין\u0004 מים \u0003ושדי עלואי\u0004 \u0005[וזרוק עלי]\u0006 להטהר מטומאת קרי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא: למה ליה\u0004 \u0005[לו]\u0006 \u0003למר כולי האי\u0004 \u0005[כל זה ]?\u0006 \u0003והא יתיב בגווייהו\u0004 \u0005[והרי\u0006 אתה \u0005יושב בתוכם]\u0006, שיש בוודאי באגן תשעה קבין מים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 דינן של תשעה קבין אלו הרי הוא \u0003כ\u0004דין \u0003ארבעים סאה\u0004 במובן זה שהלכותיהם קצובות ומוגדרות, \u0003מה ארבעים סאה\u0004 אינן כשרות לטהר אלא באופן אחד, \u0003בטבילה ולא בנתינה\u0004 — \u0003אף תשעה קבין\u0004 מטהרים בבעל קרי רק \u0003בנתינה ולא בטבילה.\u0004","מסופר כי \u0003רב נחמן תקן חצבא\u0004 \u0005[התקין כד]\u0006 \u0003בת\u0004 (קיבולת של) \u0003תשעה קבין,\u0004 כדי שיוכלו התלמידים לשפוך על עצמם את המים ולהיטהר. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 כי נמסרה הלכה בשם \u0003ר' עקיבא ור' יהודה גלוסטרא\u0004 ש\u0003אמרו: לא שנו\u0004 שמותר לבעל קרי להיטהר בשפיכת תשעה קבין \u0003אלא ל\u0004מי שהיה \u0003חולה\u0004 וראה קרי \u0003לאונסו. אבל\u0004 אפילו \u0003לחולה המרגיל,\u0004 כלומר, שהקרי בא לו מתוך משכב אשה, צריך לטבילה גמורה ב\u0003ארבעים סאה.\u0004","\u0003אמר רב יוסף:\u0004 אם כן, \u0003אתבר חצביה\u0004 \u0005[נשבר כדו]\u0006 של \u0003רב נחמן,\u0004 כלומר, אין עוד תועלת בכד זה, שהרי רק אנשים מעטים נכנסים להגדרה של חולה הרואה קרי לאונסו. ואולם \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל סיפר כי \u0003באושא הוה עובדא\u0004 \u0005[היה מעשה]\u0006"],["\u0003בקילעא\u0004 \u0005[בחדר]\u0006 של \u0003רב אושעיא\u0004, שהועלתה בעיה זו, ו\u0003אתו\u0004 \u0005[באו]\u0006 \u0003ושאלו לרב אסי. אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא שנו\u0004 חיוב נתינת מים לבעל קרי \u0003אלא לחולה המרגיל, אבל לחולה\u0004 שראה קרי \u0003לאונסו\u0004 הרי הוא \u0003פטור מכלום\u0004 ואינו צריך טבילה כלל. \u0003אמר רב יוסף:\u0004 אם כן \u0003איצטמיד חצביה\u0004 \u0005[נדבק כדו]\u0006 של \u0003רב נחמן,\u0004 כלומר, לפי סיכום זה יש תועלת בכך לצורך טהרה.","עד כה נידונו בעיות מרובות בדיני טבילת בעל קרי, ועל כך שואלים שאלה כללית: \u0003מכדי כולהו אמוראי ותנאי\u0004 \u0005[הרי כל\u0006 ה\u0005אמוראים ו\u0006ה\u0005תנאים]\u0006 \u0003ב\u0004תקנתו של \u0003עזרא קמיפלגי\u0004 \u0005[הם חולקים],\u0006 \u0003ונחזי\u0004 \u0005[ונראה]\u0006 אם כן \u0003עזרא היכי\u0004 \u0005[איך]\u0006 \u0003תקן תקנה זו,\u0004 שהרי דבר מצוי הוא ואפשר לראות כיצד נהגו בענין זה.","\u0003אמר אביי:\u0004 עזרא לא תיקן תקנה קבועה בכל דיני בעל קרי, אלא \u0003עזרא תקן לבריא המרגיל\u0004 שחייב לטבול ב\u0003ארבעים סאה, ובריא\u0004 הרואה קרי \u0003לאונסו\u0004 די לו ב\u0003תשעה קבין. ו\u0004אחר כך \u0003אתו אמוראי ופליגי\u0004 \u0005[באו האמוראים ונחלקו]\u0006 \u0003בחולה. מר סבר\u0004 \u0005[חכם אחד סבור]\u0006 ש\u0003חולה המרגיל\u0004 דינו \u0003כבריא המרגיל ו\u0004אילו \u0003חולה\u0004 שראה קרי \u0003לאונסו\u0004 דינו \u0003כבריא לאונסו. ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם אחד סבור]\u0006 ש\u0003חולה המרגיל\u0004 דינו \u0003כבריא\u0004 שראה \u0003לאונסו,\u0004 וחייב רק בנתינת תשעה קבין, \u0003ו\u0004אילו \u0003חולה לאונסו פטור מכלום,\u0004 מכל טבילה ורחיצה.","על כך מקשה \u0003רבא: נהי\u0004 \u0005[אם כי]\u0006 \u0003תקן עזרא טבילה\u0004 לבעל קרי, ואולם \u0003נתינה\u0004 של תשעה קבין \u0003מי\u0004 \u0005[האם]\u0006 \u0003תקן?! והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 כי לא שמענו מסורת בדבר אלא ש\u0003עזרא תיקן טבילה לבעלי קריין\u0004 ולא תקנה אחרת. \u0003אלא אמר רבא:\u0004 יש להסביר את השתלשלות המחלוקת לאחר תקנת עזרא. \u0003עזרא\u0004 עצמו \u0003תקן טבילה\u0004 רק \u0003לבריא המרגיל בארבעים סאה. ואתו רבנן\u0004 \u0005[ובאו חכמים]\u0006 \u0003והתקינו לבריא\u0004 שראה קרי \u0003לאונסו\u0004 רחיצה ב\u0003תשעה קבין. ואתו\u0004 \u0005[ובאו]\u0006 אחר כך \u0003אמוראי\u0004 \u0005[\u0006ה\u0005אמוראים]\u0006 \u0003וקא מיפלגי\u0004 \u0005[וחלקו]\u0006 \u0003ב\u0004דינו של \u0003חולה, מר סבר\u0004 \u0005[חכם אחד סבור]\u0006 ש\u0003חולה המרגיל\u0004 דינו \u0003כבריא המרגיל, וחולה לאונסו\u0004 — \u0003כבריא לאונסו, ו\u0004אילו \u0003מר סבר\u0004 \u0005[וחכם אחד סבור]\u0006 ש\u0003בריא המרגיל\u0004 רק הוא חייב טבילה ב\u0003ארבעים סאה,\u0004 ואילו \u0003חולה המרגיל\u0004 דינו \u0003כבריא\u0004 שראה \u0003לאונסו\u0004 — ב\u0003תשעה קבין\u0004 בלבד. \u0003אבל חולה לאונסו פטור מכלום\u0004 מכל טבילה ורחיצה.","וכן \u0003אמר רבא\u0004 לקבוע \u0003הלכתא\u0004 \u0005[הלכה]\u0006 כדעה הראשונה: \u0003בריא המרגיל וחולה המרגיל\u0004 — ב\u0003ארבעים סאה. ובריא לאונסו\u0004 — \u0003תשעה קבין. אבל לחולה לאונסו\u0004 — \u0003פטור מכלום.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003בעל קרי שנתנו עליו תשעה קבין מים\u0004 שאובים — \u0003טהור. במה דברים אמורים\u0004 שהוא נטהר — רק לענין לימוד תורה \u0003לעצמו, אבל\u0004 להיטהר כדי ללמד \u0003לאחרים\u0004 צריך הוא לטבול ב\u0003ארבעים סאה.\u0004 ואילו \u0003ר' יהודה אומר: ארבעים סאה\u0004 מטהרים את בעל הקרי \u0003מכל מקום\u0004 ובכל מקרה.","בבעיה זו נתעוררה מחלוקת בין \u0003ר' יוחנן ור' יהושע בן לוי ור' אלעזר ור' יוסי בר' חנינא. חד מהאי זוגא וחד מהאי זוגא ארישא\u0004 \u0005[אחד מזוג זה ואחד מזוג זה\u0006 נחלקו \u0005על תחילת\u0006 התוספתא\u0005]\u0006 ש\u0003חד\u0004 \u0005[\u0006צד \u0005אחד]\u0006 \u0003אמר: הא דאמרת\u0004 \u0005[זה שאמרת]\u0006 \u0003במה דברים אמורים\u0004 שנתינת תשעה קבין מטהרת רק \u0003לעצמו, אבל להוציא אחרים\u0004 יש צורך ב\u0003ארבעים סאה,\u0004 כל זה \u0003לא שנו אלא לחולה המרגיל, אבל לחולה\u0004 שראה קרי \u0003לאונסו\u0004 דיו ב\u0003תשעה קבין\u0004 אף על פי שהוא שונה לאחרים. \u0003וחד\u0004 \u0005[אחד]\u0006 \u0003אמר\u0004 ש\u0003כל\u0004 המלמד \u0003לאחרים,\u0004 ו\u0003אפילו\u0004 היה \u0003חולה לאונסו עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003ארבעים סאה\u0004 אינו נחשב לטהור.","וכן \u0003חד מהאי זוגא וחד מהאי זוגא אסיפא\u0004 \u0005[אחד מזוג זה ואחד מזוג זה,\u0006 נחלקו \u0005בסוף\u0006 הדברים\u0005].\u0006 ש\u0003חד\u0004 \u0005[\u0006צד \u0005אחד]\u0006 \u0003אמר: הא\u0004 \u0005[זה]\u0006 ש\u0003אמר ר' יהודה ארבעים סאה מכל מקום\u0004 — \u0003לא שנו אלא בקרקע\u0004 שארבעים סאה אלה יהיו בקרקע כדין מקווה מן התורה, \u0003אבל\u0004 אם הם אגורים \u0003בכלים\u0004 — \u0003לא. וחד סבר\u0004 \u0005[ואחד\u0006 האחר \u0005סבור]\u0006 שארבעים סאה \u0003אפילו בכלים נמי\u0004 \u0005[גם כן],\u0006 שדי בכלי המכיל ארבעים סאה כדי להיטהר.","בעיה זו מבררים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שארבעים סאה מטהרים \u0003אפילו בכלים\u0004 — \u0003היינו דקתני\u0004 \u0005[\u0006הרי \u0005זהו ששנה]\u0006 זהו טעם הדגשתו של \u0003ר' יהודה \"ארבעים סאה מכל מקום\". אלא למאן דאמר\u0004 \u0005[למי שאומר,\u0006 לפי הדעה\u0005]\u0006 שלדעת ר' יהודה \u0003בקרקע\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יש להתיר, ואילו \u0003בכלים\u0004 — \u0003לא,\u0004 ביטוי זה \u0003\"מכל מקום\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה],\u0006 מה הוא בא להוסיף בכך?","ומפרשים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003מים שאובין,\u0004 שאף ר' יהודה מתיר לטבול בארבעים סאה מים האגורים בקרקע אף אם נשאבו בידי אדם.","מסופר, \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע ורבא (ברבי) בר שמואל כריכו ריפתא בהדי הדדי\u0004 \u0005[אכלו לחם יחד].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: הבו\u0004 \u0005[תנו]\u0006 \u0003לי לדידי לברוך\u0004 \u0005[לעצמי לברך]\u0006 ברכת המזון, שאני טהור, לפי \u0003דנפול עילואי\u0004 \u0005[שנפלו עלי,\u0006 כלומר, שפכתי על עצמי\u0005]\u0006 \u0003תשעה קבין\u0004 מים. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא בר שמואל:\u0004 הרי על כך \u0003תנינא\u0004 \u0005[שנינו],\u0006 \u0003במה דברים אמורים\u0004 שתשעה קבין מטהרים — הרי זה דווקא לענין לימוד \u0003לעצמו, אבל ל\u0004למד או להוציא \u0003אחרים\u0004 ידי חובה — צריך \u0003ארבעים סאה. אלא, הבו\u0004 \u0005[תנו]\u0006 \u0003לי לדידי לברוך, דנפול עילואי\u0004 \u0005[לברך, שנפלו עלי\u0006 שטבלתי\u0005]\u0006 ב\u0003ארבעים סאה. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא: הבו\u0004 \u0005[תנו]\u0006 \u0003לי לדידי לברוך, דליכא עילואי\u0004 \u0005[לברך, שאין עלי]\u0006 \u0003לא האי\u0004 \u0005[זה]\u0006 \u0003ולא האי\u0004 \u0005[זה],\u0006 שטהור אני ולא הוצרכתי לטבילה כלל.","מסופר גם ש\u0003רב חמא טביל במעלי יומא דפיסחא\u0004 \u0005[היה טובל בערב פסח]\u0006 כדי \u0003להוציא רבים ידי חובתן.\u0004 ואולם מסכמים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו].\u0006 וכשיטה זו המחלקת בין טהרת עצמו לטהרה לצורך אחרים.","במשנה זו דברים אחדים על הטמאים בטומאות שונות ועל ההרחקה מן הטומאה ומן הזוהמה. \u0003היה עומד בתפלה ונזכר\u0004 בתוך תפילתו \u0003שהוא בעל קרי,\u0004 ולדעה זאת אסור בתפילה, אף על פי כן \u0003לא יפסיק\u0004 את התפילה באמצע, \u0003אלא יקצר\u0004 בכל ברכה וברכה.","כלל אמרו: \u0003ירד לטבול, אם יכול לעלות\u0004 מן הטבילה \u0003ולהתכסות\u0004 בבגדים \u0003ולקרות\u0004 קריאת שמע של שחרית \u0003עד שלא תהא הנץ החמה\u0004 — \u0003יעלה ויתכסה ויקרא, ואם לאו\u0004 \u0005[לא],\u0006 שאינו יכול — מוטב ש\u0003יתכסה במים ויקרא\u0004 שם. \u0003ו\u0004אולם \u0003לא יתכסה לא במים הרעים\u0004 (שהסריחו) \u0003ו\u0004אף \u0003לא במי המשרה\u0004 (מים ששרו בהם פשתן, משום ריחם) \u0003עד שיטיל לתוכם מים\u0004 אחרים. \u0003ו\u0004בכלל, \u0003כמה ירחיק מהן\u0004 ממים סרוחים \u0003ומן הצואה\u0004 בשעת קריאת שמע — לפחות \u0003ארבע אמות.\u0004","בברייתא מפורט יותר הדין הראשון מן המשנה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היה עומד בתפלה ונזכר שהוא בעל קרי\u0004 באמצע תפילתו — \u0003לא יפסיק, אלא יקצר.\u0004 ואם \u0003היה קורא בתורה ונזכר שהוא בעל קרי\u0004 — \u0003אינו מפסיק ועולה, אלא מגמגם וקורא,\u0004 כלומר, קורא במהירות, ולא בחיתוך מושלם של המילים. ו\u0003ר' מאיר\u0004 חולק ו\u0003אומר\u0004 ש\u0003אין בעל קרי רשאי לקרות בתורה יותר משלשה פסוקים,\u0004 שפחות משלושה פסוקים אסור לקרוא בתורה, ולאחר שסיים לקרוא שלושה פסוקים — יפסיק, ויניח לאחר לקרוא.","\u0003תניא אידך\u0004 \u0005[שנינו\u0006 בברייתא \u0005אחרת]:\u0006 \u0003היה עומד בתפלה וראה צואה כנגדו\u0004 — \u0003מהלך לפניו עד שיזרקנה,\u0004 כלומר, שתהיה \u0003לאחוריו ארבע אמות,\u0004 ועל כך הקשו \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 שדיו שיתרחק ארבע אמות \u0003לצדדין.\u0004 כדי לישב את הסתירה מסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אין סתירה בין שני המקורות, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שצריך שתהיה מאחוריו ארבע אמות, הרי זה באופן ש\u0003אפשר,\u0004 שיכול הוא ללכת קדימה עד שתהא הצואה מאחוריו, \u0003והא\u0004 \u0005[וזה]\u0006 ששנינו שדי בכך שיתרחק ארבע אמות לצדדים, הרי זה באופן ש\u0003לא אפשר\u0004 ללכת קדימה עד כדי ארבע אמות, ולכן לפחות ילך הצידה.","והלכה, נוספת שנו: מי ש\u0003היה מתפלל ומצא\u0004 אחר כך שהיתה \u0003צואה במקומו\u0004 במקום שהתפלל בו, \u0003אמר רבה: אף על פי שחטא\u0004 שלא בדק אם היה המקום נקי וראוי לתפילה (תוספות) — \u0003תפלתו תפילה,\u0004 ויצא ידי חובתו. על כך \u0003מתקיף ליה\u0004 \u0005[מקשה עליו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 נאמר: \u0003\"זבח רשעים תועבה\u0004 אף כי בזמה יביאנו\u0003\"\u0004 (משלי כא, כז), ולמדו מזה שמצוה הנעשית שלא כראוי אינה מצוה כלל, וזה שלא שם לבו כראוי אין תפילתו נחשבת! \u0003אלא אמר רבא: הואיל וחטא\u0004 אדם זה, \u0003אף על פי שהתפלל\u0004 — \u0003תפילתו תועבה,\u0004 ויחזור ויתפלל שנית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מי ש\u0003היה עומד בתפילה ומים\u0004 (מי רגליו) \u0003שותתין\u0004 מאיזו שהיא סיבה \u0003על ברכיו\u0004 — \u0003פוסק\u0004 מתפילתו \u0003עד שיכלו המים וחוזר ומתפלל.\u0004 ואולם נתעוררה השאלה: \u0003להיכן חוזר\u0004 כשממשיך בתפילתו? ובכך נחלקו \u0003רב חסדא ורב המנונא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר : חוזר לראש\u0004 התפילה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 חוזר \u0003למקום ש\u0004בו \u0003פסק.\u0004","ומעירים: \u0003לימא בהא קמיפלגי\u0004 \u0005[אולי נאמר,\u0006 ש\u0005בכך הם חולקים,\u0006 שזה הוא יסוד מחלוקתם\u0005].\u0006"],["\u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003סבר\u0004 שבדרך כלל, המפסיק בתפילתו \u0003אם שהה\u0004 בהפסקה \u0003כדי לגמור את\u0004 התפילה \u0003כולה\u0004 — \u0003חוזר לראש\u0004 התפילה. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר:\u0004 חוזר רק \u0003למקום שפסק.\u0004","אפשרות זו דחה ו\u0003אמר רב אשי:\u0004 אם כן \u0003האי\u0004 \u0005[\u0006לשון \u0005זה]\u0006 ששנינו \u0003\"אם שהה\"\u0004 בלבד חסרה, שהיה לו לחלק בין אם שהה המתפלל וכמה זמן שהה, ללא שהה בכלל, ואם כן גם את הצד של \u0003\"אם לא שהה\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אלא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אם שהה\u0004 בתוך תפילתו זמן \u0003כדי לגמור את\u0004 התפילה \u0003כולה\u0004 — \u0003חוזר לראש, והתם\u0004 \u0005[שם]\u0006 במחלוקת שלפנינו \u0003ב\u0004ש\u0003לא שהה קמיפלגי\u0004 \u0005[נחלקו],\u0006 כאשר לא שהה זמן כה רב, אלא עסקו בבעייתו המיוחדת של אותו אדם, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 אחד מהם \u0005סבור]\u0006 כי \u0003גברא דחויא\u0004 \u0005[אדם דחוי]\u0006 \u0003הוא, ואין ראוי, ואין תפלתו תפלה,\u0004 ועל כן צריך לחזור מתחילה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 האחר \u0005סבור]\u0006 כי \u0003גברא חזיא\u0004 \u0005[אדם ראוי]\u0006 \u0003הוא, ותפלתו תפלה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003הנצרך לנקביו\u0004 — \u0003אל יתפלל, ואם התפלל\u0004 — \u0003תפלתו תועבה.\u0004 דברים אלה הגביל ו\u0003אמר רב זביד ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יהודה: לא שנו\u0004 הלכה זו \u0003אלא\u0004 כ\u0003שאינו יכול לשהות\u0004 (לעכב) \u0003בעצמו\u0004 מלהתפנות, \u0003אבל אם יכול לשהות בעצמו\u0004 — \u0003תפלתו תפלה,\u0004 שאז אין הוא נחשב כמזוהם מצורך הנקבים.","על כך שואלים: \u0003ועד כמה?\u0004 כלומר, יכולת זו לשהות בעצמו מה שיעורה? על כך \u0003אמר רב ששת:\u0004 השיעור הוא \u0003עד\u0004 משך הזמן של הילוך \u0003פרסה. איכא דמתני לה אמתניתא\u0004 \u0005[יש ששונים אותה,\u0006 את ההלכה הזאת, \u0005על\u0006 מה ששנינו ב\u0005ברייתא]:\u0006 \u0003במה דברים אמורים\u0004 — \u0003כשאין יכול לעמוד על עצמו. אבל אם יכול לעמוד על עצמו\u0004 — \u0003תפלתו תפלה. ועד כמה? אמר רב זביד:\u0004 שיעור הזמן הוא \u0003עד\u0004 כדי הילוך \u0003פרסה.\u0004","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: הנצרך לנקביו\u0004 — \u0003הרי זה לא יתפלל, משום שנאמר: \"הכון לקראת אלהיך ישראל\"\u0004 (עמוס ד, יב), וצריך אדם לפנות דעתו מכל מונע ולהיות מוכן בשעת התפילה לקבל פני ה'.","בהקשר לדברים אלה מביאים מה ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"שמור רגלך כאשר תלך אל בית האלהים\u0004 וקרוב לשמוע מתת הכסילים זבח כי אינם יודעים לעשות רע\u0003\"\u0004 (קהלת ד, יז) — יש לפרשו: כאשר תלך אל בית האלהים, \u0003שמור עצמך שלא תחטא, ואם תחטא\u0004 — \u0003הבא קרבן לפני\u0004 לכפרה. את המשך הפסוק \u0003\"וקרוב לשמע דברי חכמים\",\u0004 פירש ו\u0003אמר רבא: הוי קרוב לשמוע דברי חכמים, ש\u0004כן \u0003אם\u0004 הם \u0003חוטאים\u0004 הם \u0003מביאים קרבן ועושים תשובה.\u0004 ופירוש המשך הפסוק \"מתת הכסיל זבח\" — \u0003אל תהי ככסילים שחוטאים ומביאים קרבן\u0004 (\"מתת... זבח\"), \u0003ואין עושים תשובה.\u0004","ועל הנאמר בפסוק \"כי אינם יודעים לעשות רע\", תמהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלא \u0003צדיקים נינהו\u0004 \u0005[הם]!\u0006 \u0003אלא\u0004 יש להבין: \u0003אל תהי ככסילים שחוטאים ומביאים קרבן, ואינם יודעים אם על הטובה\u0004 וההודאה \u0003הם מביאים,\u0004 או \u0003אם על הרעה\u0004 כתשובה וכפרה \u0003הם מביאים,\u0004 וזהו פירוש הכתוב: \"כי אינם יודעים לעשות רע\" — שאינם יודעים אם ומתי מה שעשו הוא רע. ועליהם \u0003אמר הקדוש ברוך הוא: בין טוב לרע אינן מבחינים, והם מביאים קרבן לפני?!\u0004","על אותו פסוק דרש \u0003רב אשי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב חנינא בר פפא\u0004 הוא ש\u0003אמר\u0004 זאת: \u0003שמור נקביך בשעה שאתה עומד בתפלה לפני.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנכנס לבית הכסא, חולץ תפיליו ברחוק ארבע אמות\u0004 משם, \u0003ונכנס. אמר רב אחא בר רב הונא אמר רב ששת: לא שנו אלא\u0004 כשנכנס ל\u0003בית הכסא קבוע, אבל\u0004 הנכנס ל\u0003בית הכסא עראי\u0004 והוא רוצה לעשות צרכיו בו — \u0003חולץ\u0004 את התפילין, \u0003ונפנה\u0004 לצרכיו \u0003לאלתר\u0004 \u0005[מיד].\u0006 ואולם \u0003כשהוא יוצא\u0004 משם — \u0003מרחיק ארבע אמות\u0004 מאותו בית הכסא, ומניחן, ואינו רשאי להניחן מיד \u0003מפני ש\u0004בכך כבר \u0003עשאו\u0004 (הכשירו) למקום כ\u0003בית הכסא קבוע.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמי הישיבה \u0005]\u0006 שאלה זו: \u0003מהו\u0004 הדין לענין \u0003שיכנס אדם בתפילין לבית הכסא קבוע להשתין מים\u0004 בלבד? ובכך נחלקו חכמים: \u0003רבינא שרי\u0004 \u0005[התיר],\u0006 ואילו \u0003רב אדא בר מתנא אסר. אתו שיילוה\u0004 \u0005[באו,\u0006 ו\u0005שאלו\u0006 שאלה זו\u0005]\u0006 \u0003לרבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003אסור,\u0004 וטעם הדבר — כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא יפנה בהן\u0004 לצרכים גדולים. \u0003ואמרי לה\u0004 \u0005[ויש אומרים אותה,\u0006 הלכה זו\u0005]\u0006 כי החשש הוא, שמאחר שהוא נמצא שם ישכח שהתפילין בראשו ו\u0003שמא יפיח בהן.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הנכנס לבית הכסא קבוע — חולץ תפיליו ברחוק ארבע אמות\u0004 משם, \u0003ומניחן בחלון\u0004 בית הכסא \u0003הסמוך לרשות הרבים, ונכנס. וכשהוא יוצא\u0004 — \u0003מרחיק ארבע אמות, ומניחן,\u0004 אלה \u0003דברי בית שמאי. ובית הלל אומרים:\u0004 חולץ את התפילין אך \u0003אוחזן בידו, ונכנס. ר' עקיבא אומר: אוחזן בבגדו, ונכנס.\u0004","על כך תמהים: \u0003בבגדו סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! והרי יש לחשוש כי \u0003זימנין מישתלי להו ונפלי\u0004 \u0005[לפעמים שוכח אותם ו\u0006הם \u0005נופלים]!\u0006 \u0003אלא אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 \u0003אוחזן בבגדו ובידו.\u0004 כלומר, מכסה אותם בבגדו ומחזיקם בידו, \u0003ו\u0004כך הוא \u0003נכנס.\u0004","וקבעו: \u0003ו\u0004אם יש לו מקום להניחם — \u0003מניחם בחורין הסמוכים לבית הכסא, ולא יניחם בחורים הסמוכים לרשות הרבים, שמא יטלו אותם,\u0004 את התפילין, \u0003עוברי דרכים, ויבא לידי חשד.\u0004","\u0003 ו\u0004כעין \u0003מעשה\u0004 זה שהיה\u0003בתלמיד אחד שהניח תפיליו בחורין הסמוכים לרשות הרבים, ובאת\u0004 \u0005[ובאה]\u0006 \u0003זונה אחת, ונטלתן\u0004 את התפילין, \u0003ובאת\u0004 \u0005[באה]\u0006 \u0003לבית המדרש ואמרה: ראו מה נתן לי פלוני בשכרי! כיון ששמע אותו תלמיד\u0004 דברים אלה, מרוב בושה על חשד זה \u0003עלה לראש הגג ונפל ומת. באותה שעה התקינו שיהא אוחזן בבגדו ובידו, ונכנס,\u0004 שלא יקרו עוד מכשולים כעין זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על נושא זה, כך: \u0003בראשונה היו מניחין תפילין בחורין הסמוכין לבית הכסא, ו\u0004אולם אז היו \u0003באין עכברים ונוטלין אותן\u0004 את התפילין, או מכרסמים אותם. על כן \u0003התקינו שיהו מניחין אותן בחלונות הסמוכות לרשות הרבים,\u0004 שאין העכברים מצויים שם. אלא שאז היו \u0003באין עוברי דרכים ונוטלין אותן\u0004 את התפילין. ומשום כך \u0003התקינו\u0004 לבסוף \u0003שיהא אוחזן בידו ונכנס.\u0004","באותו ענין \u0003אמר ר' מיאשא בריה\u0004 \u0005[בנו]\u0006, של \u0003ר' יהושע בן לוי: הלכה,\u0004 שבמקרה זה \u0003גוללן\u0004 את התפילין ברצועותיהן \u0003כמין ספר, ואוחזן בימינו כנגד\u0004 (מול) \u0003לבו. אמר רב יוסף בר מניומי אמר רב נחמן: ובלבד,\u0004 צריך להקפיד רק \u0003שלא תהא רצועה\u0004 של התפילין \u0003יוצאת\u0004 ונראית \u0003מתחת ידו\u0004 כדי שיעור \u0003טפח.\u0004","והעיר עוד \u0003ר' יעקב בר אחא אמר ר' זירא: לא שנו\u0004 שגולל את התפילין \u0003אלא\u0004 כ\u0003שיש\u0004 לו עוד \u0003שהות ביום ללובשן, אבל\u0004 כאשר \u0003אין\u0004 עוד \u0003שהות ביום ללבשן,\u0004 שיגיע קודם לכן הלילה שאינו זמן תפילין — \u0003עושה להן כמין כיס\u0004 שחללו \u0003טפח\u0004 אחד, \u0003ומניחן\u0004 באותו כיס.","וכן \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ביום גוללן\u0004 את התפילין \u0003כמין ספר ומניחן בידו כנגד לבו, ובלילה עושה להן כמין כיס\u0004 ששיעורו \u0003טפח, ומניחן\u0004 בו.","על כך \u0003אמר אביי: לא שנו\u0004 שיש צורך בשיעור טפח \u0003אלא\u0004 כש\u0003כלי\u0004 זה \u0003הוא כליין\u0004 של התפילין, שהוא עטיפתם הרגילה, \u0003אבל בכלי\u0004 אחר \u0003שאינו כליין, אפילו\u0004 היה שיעורו \u0003פחות מטפח,\u0004 מותר להכניס בו את התפילין.","וראיה לדבר \u0003אמר מר זוטרא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שראיה זו הביא \u0003רב אשי\u0004 מהלכה אחרת \u0003תדע שהרי\u0004 בדיני טומאה רק חלל טפח חוצץ בפני טומאת מת, ובכל זאת \u0003פכין קטנים\u0004 וסגורים הפחותים מטפח \u0003מצילין\u0004 את הנמצא בהם מטומאה אף שהם נמצאים \u0003באוהל המת.\u0004 ואם כן ראיה היא שחלל קטן ומסויים גם הוא יכול להיות חציצה מפני טומאה ואפילו כשהוא פחות מטפח.","\u0003אמר רבה בר בר חנה: כי הוה אזלינן בתריה\u0004 \u0005[כאשר היינו הולכים אחריו],\u0006 אחרי \u0003ר' יוחנן,\u0004 היינו רואים \u0003כי הוה בעי למיעל\u0004 \u0005[כשהיה רוצה להיכנס]\u0006 \u0003לבית הכסא כי הוה נקיט ספרא דאגדתא\u0004 \u0005[כאשר היה מחזיק ספר אגדה]\u0006 בידו — \u0003הוה יהיב לן\u0004 \u0005[היה נותן לנו]\u0006 אותו, \u0003כי הוה נקיט\u0004 \u0005[כשהיה מחזיק]\u0006 \u0003תפילין\u0004 — \u0003לא הוה יהיב לן\u0004 \u0005[היה נותן לנו]\u0006 אותם, ש\u0003אמר: הואיל ושרונהו רבנן\u0004 \u0005[והתירום חכמים] —\u0006"],["\u0003נינטרן\u0004 \u0005[ישמרוני],\u0006 שאף שהיה לו למי לתת את התפילין, המשיך להחזיקם בידו כשמירה מהסכנה. וכן \u0003אמר רבא: כי הוה אזלינן בתריה\u0004 \u0005[כאשר היינו הולכים אחריו],\u0006 אחרי \u0003ר' נחמן,\u0004 היינו רואים \u0003כי הוה נקיט ספרא דאגדתא\u0004 \u0005[כאשר היה מחזיק ספר אגדה]\u0006 בידו — \u0003יהיב לן\u0004 \u0005[היה נותן לנו],\u0006 \u0003כי הוה נקיט\u0004 \u0005[כאשר היה מחזיק]\u0006 \u0003תפילין\u0004 — \u0003לא יהיב לן\u0004 \u0005[היה נותן לנו],\u0006 שכן \u0003אמר: הואיל ושרונהו רבנן\u0004 \u0005[שהתירום חכמים],\u0006 \u0003נינטרן\u0004 \u0005[ישמרוני].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יאחז אדם תפילין בידו\u0004 או \u0003ספר תורה בזרועו ויתפלל.\u0004 שמתוך הפחד שמא יפלו מידיו, אין דעתו פנויה לתפילה. \u0003ו\u0004כן כשמחזיק דברי קדושה אלה בידו \u0003לא ישתין בהם מים, ולא יישן בהם לא שינת קבע ולא שינת עראי. אמר שמואל:\u0004 לענין תפילה לא רק זה שמחזיק תפילין לא יתפלל, אלא גם המחזיק \u0003סכין\u0004 או \u0003מעות\u0004 או \u0003קערה\u0004 או \u0003ככר\u0004 לחם, \u0003הרי אלו כיוצא בהן,\u0004 שאף אז דואג הוא לחפץ שבידו שלא יישמט, ואין לבו פנוי לתפילה.","על ברייתא זו \u0003אמר רבא אמר רב ששת: לית הלכתא כי הא מתניתא\u0004 \u0005[אין הלכה כברייתא זו],\u0006 משום שעל פי שיטת \u0003בית שמאי היא. דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא לשיטת \u0003בית הלל\u0004 — \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי ב\u0003בית הכסא קבוע שרי\u0004 \u0005[התירו]\u0006 חכמים להחזיק תפילין בידו, אם כן ב\u0003בית הכסא עראי מיבעיא\u0004 \u0005[צריך]\u0006 לומר שמותר?!","על מסקנה זו הקשו מתוך המשכה של הברייתא, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בהקשר לנושא זה: \u0003דברים שהתרתי לך כאן, אסרתי לך כאן.\u0004 כלומר, יש דברים שהתירו אותם לגבי בית הכסא קבוע, ולא בבית הכסא ארעי. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן לגבי \u0003תפילין?\u0004 ואז, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי האיסור להטיל מים בתפילין הריהו כדעת \u0003בית הלל,\u0004 הרי נבין את הברייתא כך: דברים ש\u0003התרתי לך כאן\u0004 להחזיק תפילין בבית הכסא \u0003קבוע, אסרתי לך כאן\u0004 ב\u0003בית הכסא\u0004 ה\u0003עראי. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שברייתא זו כדברי \u0003בית שמאי\u0004 היא \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא שרו\u0004 \u0005[התירו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]\u0006 בבית הכסא קבוע, ואם כן, מה פירוש \"מה שהתרתי לך כאן\"?","קושיה זו דוחים בהסבר, \u0003כי תניא ההיא\u0004 \u0005[כאשר נשנתה אותה\u0006 אימרה\u0005]\u0006 לא לענין תפילין, כי אם \u0003לענין טפח וטפחיים.\u0004 כמבואר, \u0003דתני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003כשהוא נפנה\u0004 לצרכיו אף אז צריך לנהוג בצניעות — \u0003מגלה\u0004 מבשרו \u0003לאחריו טפח ולפניו טפחיים. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 אינו מגלה אלא \u0003לאחריו טפח ולפניו ולא כלום.\u0004","\u0003מאי לאו אידי ואידי\u0004 \u0005[האם לא זה וזה]\u0006 מדובר \u0003באיש\u0004 (גבר), \u0003ולא קשיא\u0004 \u0005[ואין קושיה\u0006 סתירה\u0005]\u0006 בין הברייתות, שכן \u0003כאן,\u0004 בברייתא האומרת שמגלה טפח לאחריו ולפניו ולא כלום, מדובר בצרכים \u0003גדולים, וכאן\u0004 בברייתא האחרת האומרת שלאחריו מגלה טפח ולפניו מגלה טפחיים — בצרכים \u0003קטנים. ולפי דברים אלה ייצא שאף על פי שמגלה אדם עצמו בבית הכסא ארעי יותר (\"מה שהתרתי לך כאן\"), אין לו להתגלות בבית הכסא קבוע (\"מה שאסרתי לך כאן\"). את ההסבר הזה דוחים מיד:\u0004","\u0003ותסברא\u0004 \u0005[וכי תסבור כך]?!\u0006 וכי יכול אתה באמת לקבל הסבר זה? שהרי \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003ב\u0004צרכים \u0003קטנים, לאחריו\u0004 גילוי \u0003טפח למה לי,\u0004 לשם מה עליו לגלות? \u0003אלא\u0004 יש לומר כי \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 שתי ברייתות אלה מדברות \u0003ב\u0004צרכים \u0003גדולים, ולא קשיא\u0004 \u0005[קשה,\u0006 אין ביניהן סתירה\u0005],\u0006 שכן \u0003הא\u0004 \u0005[\u0006ברייתא זו] האומרת שמגלה לפניו טפחיים, מדברת \u0003באיש\u0004 הצריך להתגלות גם מלפניו אז מחשש מי רגלים, \u0003והא\u0004 \u0005[וזו]\u0006 האחרת שנאמר בה שאין מגלה לפניו ולא כלום — \u0003באשה,\u0004 שאינה צריכה כלל להתגלות מלפניה.","על כך מקשים: \u0003אי הכי הא דקתני עלה\u0004 \u0005[אם כן, זה ששנו עליה],\u0006 שבברייתא שמדובר בה כאן מובא הביטוי \u0003\"זה הוא קל וחומר שאין עליו תשובה\",\u0004 כלומר, אף שהיה ראוי להחמיר בבית כסא קבוע (בצרכים גדולים) יותר מבארעי, מצד קל וחומר — אין עושים כן. ואם נפרש כדרך שהסברנו, \u0003מאי\u0004 \u0005[מה\u0006 טעם אמרו\u0005]\u0006 \u0003\"אין עליו תשובה\"?\u0004 הרי \u0003דרכא דמלתא הכי איתא\u0004 \u0005[דרכו של הדבר כן הוא],\u0006 שיש הבדל בצורך הגילוי בין איש ואשה,","\u0003אלא לאו\u0004 אין ללמוד מקרה ממקרה בדרך קל וחומר. ועל כן חייבים להסביר כי \"מה שהתרתי לך כאן אסרתי לך כאן\" כוונתו לענין \u0003תפילין\u0004 כפי שהסברנו קודם, \u0003ו\u0004הרי זאת \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבא\u0004 ש\u0003אמר\u0004 בשם \u0003רב ששת\u0004 שלא כך פירש. ומסכמים: אכן זו \u0003תיובתא\u0004 \u0005[קושיה חמורה].\u0006","ושואלים:\u0003 מכל מקום\u0004, ביסודו של דבר \u0003קשיא\u0004 \u0005[קשה],\u0006 שכן \u0003השתא\u0004 \u0005[עכשיו]\u0006 ב\u0003בית הכסא קבוע שרי\u0004 \u0005[מותר]\u0006 להכניס תפילין, ואם כן ב\u0003בית הכסא ארעי לא כל שכן\u0004 שיהא הדבר מותר!","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003בית הכסא קבוע דליכא\u0004 \u0005[שאין]\u0006 \u0003ניצוצות\u0004 של מי רגלים על בגדיו או נעליו כי שם הוא יושב ועושה צרכיו, הרי אינו צריך ללכלך את ידיו בניקוי הבגד, ולכן \u0003שרי\u0004 \u0005[מותר]\u0006 להכניס בו תפילין. ואולם \u0003בית הכסא עראי דאיכא\u0004 \u0005[שיש]\u0006 שעומד בו ולכן נתזים \u0003ניצוצות,\u0004 שעשוי לנגוע בהם בידו — \u0003אסרי\u0004 \u0005[אסרו]\u0006 בו.","על כך מקשים: \u0003אי הכי, אמאי\u0004 \u0005[אם כן\u0006, משום מה] אמרו שזה הוא קל וחומר ש\u0003\"אין עליו תשובה\"?\u0004 הלא \u0003תשובה מעליתא\u0004 \u0005[מעולה]\u0006 \u0003היא\u0004 להסביר את ההבדל!","ומסבירים כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003הא מילתא תיתי לה\u0004 \u0005[דבר זה הבא\u0006 למד \u0005אותו ]\u0006 \u0003בתורת\u0004 (בתור) \u0003טעמא\u0004 \u0005[טעם]\u0006 לפי מהות ענין הדברים בטבעם, \u0003ולא תיתי לה\u0004 \u0005[תלמד אותו]\u0006 \u0003ב\u0004דרך \u0003קל וחומר, דאי אתיא לה\u0004 \u0005[שאם\u0006 רוצה אתה \u0005ללמוד אותו]\u0006 \u0003בתורת קל וחומר,\u0004 הרי \u0003זהו קל וחומר שאין עליו תשובה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרוצה ליכנס לסעודת קבע\u0004 הנמשכת זמן רב, מנהג דרך ארץ ש\u0003מהלך עשרה פעמים ארבע אמות, או ארבע פעמים עשר אמות\u0004 לזרז את פעולת המעיים, \u0003ויפנה\u0004 לצרכיו, \u0003ואחר כך נכנס\u0004 לסעודה. שאם לא כן שמא יצטרך לצאת באמצע, ויגרום לעצמו אי נעימות.","באותו ענין \u0003אמר ר' יצחק: הנכנס לסעודת קבע, חולץ תפיליו ואחר כך נכנס.\u0004 שאין זה נאה לשבת בסעודה שיש בה גם קלות ראש כשהוא חבוש בתפילין. \u0003ו\u0004דבר זה \u0003פליגא\u0004 \u0005[חולק]\u0006 על שיטת \u0003ר' חייא,\u0004 ש\u0003אמר ר' חייא:\u0004 בסעודת קבע \u0003מניחן\u0004 את התפילין \u0003על שלחנו, וכן הדור\u0004 (ראוי) \u0003לו,\u0004 כדי שיהיו מזומנים לפניו, שמיד כשירצה להניחם יוכל להניחם בלא עיכוב.","ושואלים: \u0003ועד אימת\u0004 \u0005[מתי]\u0006 בסעודה יהיו תפיליו חלוצים? \u0003אמר רב נחמן בר יצחק: עד זמן ברכה,\u0004 ברכת המזון.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003צורר אדם תפיליו עם מעותיו באפרקסותו\u0004 \u0005[עטיפת ראש].\u0006 \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא יצור\u0004 אדם תפילין וכסף יחד.","ומסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 שיש לחלק ולומר כי \u0003הא\u0004 \u0005[ברייתא זו]\u0006 האוסרת מדברת באופן \u0003דאזמניה\u0004 \u0005[שהזמינו\u0006 לכלי\u0005],\u0006 שהכין את הכלי לצורך תפילין. ואילו \u0003הא\u0004 \u0005[ברייתא זו]\u0006 המתירה מדברת באופן ש\u0003לא אזמניה\u0004 \u0005[הזמינו]\u0006 לצורך זה. ש\u0003אמר רב חסדא: האי סודרא\u0004 \u0005[סודר זה]\u0006 של \u0003תפילין דאזמניה למיצר ביה\u0004 \u0005[שהזמינו לצרור בו]\u0006 \u0003תפילין,\u0004 אם כבר \u0003צר ביה\u0004 \u0005[צרר בו]\u0006 \u0003תפילין\u0004 — \u0003אסור למיצר ביה פשיטי\u0004 \u0005[לצרור בו מעות],\u0006 ואם רק \u0003אזמניה\u0004 \u0005[הזמינו]\u0006 לצורך זה \u0003ו\u0004עדיין \u0003לא צר ביה\u0004 \u0005[צרר בו\u0006 תפילין\u0005],\u0006 או \u0003צר ביה\u0004 \u0005[צרר בו\u0006 תפילין\u0005]\u0006 אלא ש\u0003לא אזמניה\u0004 \u0005[הזמינו\u0006 מלכתחילה לשם כך\u0005]\u0006 — \u0003שרי למיצר ביה זוזי\u0004 \u0005[מותר\u0006 עוד \u0005לצרור בו מעות].\u0006","\u0003ו\u0004אילו \u0003ל\u0004שיטת \u0003אביי\u0004 ש\u0003אמר\u0004 ככלל כי \u0003הזמנה מילתא היא\u0004 \u0005[דבר הוא],\u0006 שלשיטתו, אם מכינים חפץ לצורך מסויים — חלים עליו כל הדינים השייכים בשימוש זה אף אם עדיין לא השתמש בו בפועל, אם כן לשיטתו יש לפסוק כך להלכה: \u0003אזמניה\u0004 \u0005[הזמינו]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא צר ביה\u0004 \u0005[צרר בו]\u0006 — אסור להניח בו כסף. ואולם אם כבר \u0003צר ביה\u0004 \u0005[צרר בו\u0006 תפילין\u0005],\u0006 \u0003אי אזמניה\u0004 \u0005[אם הזמינו\u0006 לכך\u0005]\u0006 — \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא אזמניה\u0004 \u0005[הזמינו]\u0006 — \u0003לא.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחוניא מרב יהודה: מהו\u0004 הדין לענין \u0003שיניח אדם תפיליו\u0004 במיטתו \u0003תחת מראשותיו\u0004 כשהוא ישן? והוא עצמו מסביר: \u0003תחת מרגלותיו לא קא מיבעיא לי\u0004 \u0005[אין זו שאלה עבורי],\u0006 \u0003ש\u0004כן \u0003נוהג בהן מנהג בזיון,\u0004 ובוודאי אסור לעשות כן. \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלה זו, לענין להניחם \u0003תחת מראשותיו מאי\u0004 \u0005[מהו]\u0006 הדין בכגון זה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה: הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: מותר,\u0004 ו\u0003אפילו\u0004 כאשר \u0003אשתו עמו\u0004 באותה מיטה.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא \u0005:\u0006 \u0003לא יניח אדם תפיליו תחת מרגלותיו מפני שנוהג בהם דרך בזיון, אבל מניחם תחת מראשותיו.\u0004 ואף תחת מראשותיו \u0003אם היתה אשתו עמו\u0004 — \u0003אסור.\u0004 ורק אם \u0003היה מקום\u0004 שהניח בו תפילין \u0003גבוה שלשה טפחים\u0004 מעל ראשו \u0003או נמוך שלשה טפחים\u0004 מראשו — \u0003מותר,\u0004 שרווח זה יוצר מקום לעצמו.","ועל כל פנים, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא על \u0003שמואל\u0004 על דבריו אלה. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","\u0003אמר רבא: אף על גב דתניא תיובתא\u0004 \u0005[ששנויה קושיה חמורה]\u0006 על \u0003שמואל,\u0004 מכל מקום \u0003הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 בענין זה. \u0003מאי טעמא\u0004 \u0005[מהו טעם\u0006 הדבר]?"],["\u0003כל\u0004 שיש בו \u0003לנטורינהו טפי\u0004 \u0005[לשמרם\u0006 טוב \u0005יותר]\u0006 \u0003עדיף\u0004 מאשר הבזיון שעשוי להיגרם בכך. \u0003ו\u0004תחת מראשותיו \u0003היכא מנח להו\u0004 \u0005[היכן מניח אותם]?\u0006 \u0003אמר ר' ירמיה:\u0004 מניחן \u0003בין כר לכסת, שלא כנגד ראשו,\u0004 אלא בריחוק קצת.","על כך שואלים: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 שבמקרה זה \u0003מניחן בכובע,\u0004 כלומר, בנרתיק או כיס של תפילין \u0003תחת מראשותיו\u0004 ממש! ומשיבים: \u0003דמפיק ליה למורשא\u0004 \u0005[שמוציא אותה, את בליטת]\u0006 ה\u0003כובע\u0004 המקום שהתפילין בולטים ונראים, \u0003לבר\u0004 \u0005[כלפי חוץ].\u0006","ובהקשר לכך מסופר כי \u0003בר קפרא צייר להו בכילתא, ומפיק למורשהון לבר\u0004 \u0005[היה צורר אותם ב\u0006תוך \u0005הכילה\u0006 של המיטה, \u0005ומוציא את בליטתם כלפי חוץ].\u0006 ואילו \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי מנח להו אשרשיפא, ופריס סודרא עילוייהו\u0004 \u0005[היה מניח אותם על ספסל, ופורש סודר עליהם].\u0006","\u0003אמר רב המנונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף: זימנא חדא הוה קאימנא קמיה\u0004 \u0005[פעם אחת הייתי עומד לפני]\u0006 \u0003רבא, ואמר לי: זיל אייתי\u0004 \u0005[לך\u0006 ו\u0005הבא]\u0006 \u0003לי\u0004 את ה\u0003תפילין\u0004 שלי. \u0003ואשכחתינהו\u0004 \u0005[ומצאתין]\u0006 במיטתו \u0003בין כר לכסת, שלא כנגד ראשו. והוה ידענא\u0004 \u0005[וידעתי]\u0006 ש\u0003יום טבילה\u0004 במקווה לטהרת אשתו מנידותה \u0003הוה\u0004 \u0005[היה]\u0006 זה, ובוודאי שימש מיטתו לקיום המצווה, \u0003ו\u0004כדי \u0003לאגמורן\u0004 \u0005[ללמדנו]\u0006 \u0003הלכה למעשה הוא דעבד\u0004 \u0005[שעשה]\u0006 כן, ששלחני להביא לו את התפילין, כדי שידעו התלמידים כיצד יש לנהוג במקרה זה.","\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחוניא מרב יהודה,\u0004 אשר מקודם הוזכרה שאלה אחרת ששאל: \u0003שנים שישנים במטה אחת\u0004 והריהם עירומים, \u0003מהו\u0004 הדין, האם מותר \u0003שזה יחזיר פניו\u0004 (יסתובב לצד אחר) \u0003ויקרא קריאת שמע, וזה יחזיר פניו ויקרא קריאת שמע,\u0004 או מאחר שהם עירומים, אפילו היו מכוסים מלמעלה, אין הם ראויים כך לקריאת שמע? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל:\u0004 דבר זה מותר \u0003ואפילו\u0004 היתה \u0003אשתו עמו\u0004 באותה מיטה.","על ביטוי זה \u0003מתקיף לה\u0004 \u0005[מקשה עליו]\u0006 \u0003רב יוסף: אשתו ולא מיבעיא\u0004 \u0005[ואין צריך\u0006 לומר\u0005]\u0006 שמותר עם אדם \u0003אחר?!\u0004 וכי כשפסק הלכה זו לגבי אשתו — מובן הדבר מאליו לגבי אחר? \u0003אדרבה\u0004 (להיפך), הלא \u0003אשתו כגופו\u0004 ואינו מהרהר בה, ולכן מותר, ואילו \u0003אחר לאו\u0004 \u0005[לא]\u0006 \u0003כגופו\u0004 הוא, ואסור.","ו\u0003מיתיבי\u0004 \u0005[ומקשים]\u0006 מתוך הסברת סתירה בין שתי ברייתות, באחת שנינו ש\u0003שנים שישנים במטה אחת\u0004 והם ערומים — \u0003זה מחזיר פניו\u0004 לצד אחד \u0003וקורא\u0004 קריאת שמע, \u0003וזה מחזיר פניו וקורא. ותניא אחריתי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 ש\u0003הישן במטה, ובניו ובני ביתו בצדו\u0004 כשהם ערומים, \u0003הרי זה לא יקרא קריאת שמע, אלא אם כן היתה טלית\u0004 (בגד) \u0003מפסקת ביניהן. ואם היו בניו\u0004 או \u0003בני ביתו קטנים\u0004 עדיין והם אתו במטה — \u0003מותר\u0004 בלי חציצה זו.","ואם כן, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב יוסף לא קשיא\u0004 \u0005[אין\u0006 זו \u0005קושיה\u0006 ואין סתירה בין הברייתות\u0005],\u0006 שיש להסביר ולומר כי \u0003הא\u0004 \u0005[זו]\u0006 אחת מהן מדברת כשהיתה \u0003אשתו\u0004 באותה מיטה, \u0003והא\u0004 \u0005[וזו\u0006 האחרת\u0005]\u0006 מדברת \u0003ב\u0004שהיה \u0003אחר\u0004 עמו במטה, שיש לחשוש להרהור. \u0003אלא ל\u0004דעת \u0003שמואל\u0004 המתיר בכל מקרה \u0003קשיא\u0004 \u0005[קשיה]\u0006 כיצד יבין את הברייתא האוסרת?","על כך עונים, \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר,\u0006 להשיב\u0005]\u0006 \u0003לך שמואל: לרב יוסף מי ניחא\u0004 \u0005[האם נוח]?\u0006 \u0003והתניא\u0004 \u0005[והרי\u0006 באותה ברייתא \u0005שנינו]\u0006 שאם \u0003היה ישן במטה, ובניו ובני ביתו במטה\u0004 לצידו — \u0003לא יקרא קריאת שמע אלא אם כן היתה טליתו מפסקת ביניהן.\u0004 והרי לדעת רב יוסף אשתו כגופו ואינו צריך חציצה?! \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 לשיטת רב יוסף — שבענין \u0003אשתו לרב יוסף\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא, לדידי נמי תנאי\u0004 \u0005[לדעתי גם כן\u0006 מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 ואיני מקבל אלא ברייתא אחת.","מעתה מבררים קטע מן הדברים שנאמרו בדרך אגב קודם. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא \u0003זה מחזיר פניו וקורא קריאת שמע.\u0004 על כך מקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003עגבות\u0004 (אחוריים) חשופים! אלא ודאי \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003ל\u0004דברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: עגבות אין בהם משום ערוה. לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 כי נוכל \u0005לסייע לו]\u0006 \u0003ל\u0004דברי \u0003רב הונא\u0004 ממה ששנינו במשנה הבאה: \u0003האשה יושבת וקוצה\u0004 (חותכת, קוצצת) \u0003לה\u0004 את \u0003חלתה\u0004 כשהיא \u0003ערומה,\u0004 אף על פי שהיא צריכה לברך על הפרשת החלה, \u0003מפני שיכולה לכסות פניה\u0004 (כינוי בלשון נקיה למקום הערוה) \u0003בקרקע, אבל לא האיש,\u0004 שהוא אינו יכול לעשות כן מפני שבישיבתו אין ערוותו מכוסה. ואם כן, רואים מדברי המשנה שהעגבות, אף על פי שאינן מכוסות — אין בהן משום ערווה.","\u0003תרגמה\u0004 \u0005[פירש אותה]\u0006 את דברי משנה זו \u0003רב נחמן בר יצחק\u0004 באופן מסויים, ו\u0003כגון שהיו פניה טוחות\u0004 (דבוקות, מכוסות) \u0003בקרקע\u0004 והריהי איפוא מכוסה גם מאחריה. ולכן, אין להביא מכאן ראיה לדברי רב הונא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אם היו בניו ובני ביתו קטנים,\u0004 אף על פי שהיו ערומים, \u0003מותר\u0004 לקרוא קריאת שמע כשהם עימו במיטה. על כך שואלים: \u0003עד כמה,\u0004 עד איזה גיל נחשבים הם לקטנים לענין זה? \u0003אמר רב חסדא: תינוקת\u0004 עד \u0003בת שלש שנים ויום אחד, ותינוק\u0004 עד \u0003בן תשע שנים ויום אחד,\u0004 שהם הגילים שבהם נחשבים הם כראויים לביאה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003תינוקת בת אחת עשרה שנה ויום אחד, ותינוק בן שתים עשרה שנה ויום אחד,\u0004 שאז הם כבר נחשבים כבוגרים לענין זה. ולא קבעו גיל זה אלא בקירוב, ש\u0003אידי דאידי\u0004 \u0005[זה וזה]\u0006 גם בתינוק וגם בתינוקת הזמן שאפשר להגדירו כתחילת בגרותם מבחינה זו הוא כדברי הכתוב \u0003עד כדי \"שדים נכנו ושערך צמח\"\u0004 (יחזקאל טז, ז).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב אשי: התם\u0004 \u0005[שם,\u0006 בדין התפילין\u0005]\u0006 \u0003אמר רבא: אף על גב דתיובתא\u0004 \u0005[שקושיה חמורה]\u0006 על \u0003שמואל,\u0004 מכל מקום \u0003הלכתא כוותיה\u0004 \u0005[ההלכה כמו]\u0006 \u0003שמואל. הכא מאי\u0004 \u0005[כאן מה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו כולהו בחדא מחתא מחתינהו\u0004 \u0005[האם כולם באריגה אחת אתה אורג אותם],\u0006 האם כל הדברים כולם שווים זה לזה? \u0003אלא היכא דאיתמר\u0004 \u0005[במקום שנאמר]\u0006 — \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003והיכא\u0004 \u0005[ובמקום]\u0006 ש\u0003לא איתמר\u0004 \u0005[נאמר]\u0006 — \u0003לא איתמר\u0004 \u0005[נאמר]\u0006 ואין להשוות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרי לרב פפא:\u0004 אם היה \u0003שער\u0004 הערווה מבצבץ ו\u0003יוצא בבגדו מהו?\u0004 היש לראות בזה משום ערווה, או לא? אמר לו רב פפא: \u0003קרא עליה\u0004 \u0005[עליו]:\u0006 \u0003שער, שער,\u0004 כלומר, מדקדק אתה בדברים שאין להם חשיבות.","\u0003אמר ר' יצחק: טפח\u0004 מגולה \u0003באשה\u0004 הרי הוא בכלל \u0003ערוה.\u0004 על כך שואלים: \u0003למאי\u0004 \u0005[למה]\u0006 לאיזו הלכה נאמר דבר זה? \u0003אילימא לאסתכולי\u0004 \u0005[אם לומר\u0006 ש\u0005ל\u0006ענין \u0005הסתכלות]\u0006 \u0003בה,\u0004 שאסור להסתכל בטפח מגולה באשה, \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמר רב ששת: למה מנה הכתוב\u0004 \"אצעדה וצמיד טבעת עגיל וכומז\" (במדבר לא, נ) \u0003תכשיטין שבחוץ\u0004 כמו צמיד \u0003עם תכשיטין שבפנים\u0004 שהם במקום ערווה כגון כומז — \u0003לומר לך\u0004 ש\u0003כל המסתכל באצבע קטנה של אשה,\u0004 הריהו \u0003כאילו מסתכל במקום התורף\u0004 (הערווה), שאם כוונתו לאיסור אין הבדל באיזה מקום הוא מסתכל.","\u0003אלא\u0004 יש לומר שהמדובר הוא אפילו \u0003באשתו ול\u0004דין \u0003קריאת שמע,\u0004 כלומר, שטפח המגולה אף באשתו אסור לקרוא קריאת שמע כנגדו.","מעין זה \u0003אמר רב חסדא:\u0004 אף \u0003שוק\u0004 מגולה \u0003באשה\u0004 נחשב ל\u0003ערוה, שנאמר: \"גלי שוק עברי נהרות\"\u0004 (ישעיהו מז, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 על כך: \u0003\"תגל ערותך וגם תראה חרפתך\"\u0004 (שם, ג). ו\u0003אמר שמואל\u0004 עוד בנושא זה: \u0003קול\u0004 שיר \u0003באשה\u0004 — \u0003ערוה,\u0004 והוא לומד זאת מן השבח שנאמר אודות קול אשה בכתוב, \u0003שנאמר: \"כי קולך ערב ומראך נאוה\"\u0004 (שיר השירים ב, יד). וכן \u0003אמר רב ששת\u0004 בענין: אף \u0003שער באשה ערוה,\u0004 שכן אף הוא זוכה לשבח בכתוב, \u0003שנאמר: \"שערך כעדר העזים\u0004 שגלשו מהר גלעד\u0003\"\u0004 (שם ד, א).","ומעתה חוזרים לדון בענין תפילין. \u0003אמר ר' חנינא: אני ראיתי את רבי\u0004 (רבינו יהודה הנשיא) \u0003שתלה תפיליו.\u0004 על כך \u0003מיתיבי\u0004 \u0005[הקשו]:\u0006 והרי שנינו בברייתא ש\u0003התולה תפיליו\u0004 על דבר \u0003יתלו לו חייו!\u0004","ועוד, \u0003דורשי חמורות\u0004 (דרשנים שהיו מפרשים את הפסוקים בדרך מליצה) \u0003אמרו\u0004 על הכתוב \u0003\"והיו חייך תלאים לך מנגד\"\u0004 (דברים כח, סו) ש\u0003זה\u0004 עונשו של \u0003התולה תפיליו.\u0004","על כך עונים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זו \u0005קושיה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שדיברו בגנותו הוא שתולה אדם את התפילין הרי זה כשתולה אותם \u0003ברצועה\u0004 ובתי התפילין (קציצה) תלויים בדרך בזיון למטה, שזה בוודאי אסור. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שסופר שרבי תלה תפיליו ובוודאי שהותר הדבר, הרי זה באופן שתולה אותם \u0003בקציצה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 תירוץ אחר\u0005]:\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 הדין ב\u0003רצועה ולא שנא\u0004 \u0005[שונה]\u0006 ב\u0003קציצה\u0004, בזה ובזה — \u0003אסור. וכי\u0004 \u0005[וכאשר]\u0006 \u0003תלה רבי\u0004 את התפילין — \u0003בכיסתא\u0004 \u0005[בכיס,\u0006 בנרתיק\u0005]\u0006 \u0003תלה.\u0004","על כך שואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כן, מה יש לומר],\u0006 מהו החידוש בכך? ומשיבים: \u0003מהו דתימא\u0004 \u0005[הייתי אומר]\u0006 \u0003תיבעי\u0004 \u0005[\u0006ש\u0005יצטרכו]\u0006 \u0003הנחה\u0004 על גבי דבר מסוים \u0003כ\u0004דרך שנוהגים ב\u0003ספר תורה\u0004 — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין צורך בכך.","מאחר שסיפר ר' חנינא אודות רבי, מובא כאן מה שסיפר ו\u0003אמר ר' חנינא\u0004 עוד על רבי: \u0003אני ראיתי\u0004 בשעת תפלה \u0003את רבי שגיהק ופיהק ונתעטש ורק\u0004 (ירק)"],["\u0003ו\u0004היה \u0003ממשמש בבגדו, אבל לא היה מתעטף\u0004 בטליתו שנפלה באמצע התפילה. \u0003וכשהוא מפהק היה מניח ידו על סנטרו\u0004 שלא ייראה פיו הפתוח.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003המשמיע קולו בתפלתו\u0004 (בשמונה— עשרה) \u0003הרי זה מקטני אמנה,\u0004 שנראה שאינו מאמין שה' שומע תפילתו גם בשקט. ו\u0003המגביה קולו בתפלתו הרי זה\u0004 נחשב \u0003מנביאי השקר\u0004 שאף הם דרכם בצווחה בקריאתם.","ולענייננו, ה\u0003מגהק ומפהק\u0004 בתפילה — \u0003הרי זה מגסי הרוח. המתעטש בתפלתו\u0004 — \u0003סימן רע לו. ויש אומרים: ניכר שהוא מכוער.\u0004 ועוד, כל \u0003הרק\u0004 (היורק) \u0003בתפלתו\u0004 — \u0003כאילו רק בפני המלך.\u0004 ואם כן איך עשה רבי כל אלו בתפלתו?","את הדברים האלה מיישבים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין \u0003מגהק ומפהק לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן אפשר לומר: \u0003כאן לאונסו\u0004 התירו, ו\u0003כאן\u0004 שראו בכך משום גסות הרוח, הרי זה כשהוא עושה זאת \u0003לרצונו.\u0004 ואולם \u0003מתעטש\u0004 על \u0003מתעטש קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003מתעטש\u0004 על מתעטש \u0003נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 \u0003כאן\u0004 שמתעטש \u0003מלמעלה\u0004 מותר, \u0003כאן\u0004 שסימן רע הוא לו הרי זה כמתעטש \u0003מלמטה\u0004 (בנפיחה). וכעין ש\u0003אמר רב זירא: הא מילתא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003אבלעא\u0004 \u0005[נבלע,\u0006 נלמד בדרך אגב\u0005]\u0006 \u0003לי בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב המנונא ותקילא\u0004 \u0005[ושקול]\u0006 הוא \u0003לי כי כולי תלמודאי\u0004 \u0005[ככל תלמודי]:\u0006 \u0003המתעטש בתפלתו סימן יפה לו,\u0004 כי \u0003כשם שעושים לו נחת רוח מלמטה,\u0004 שכן לאחר העיטוש הגירוי נפסק, רמז הוא לו ש\u0003כך עושים לו נחת רוח מלמעלה.\u0004 ומכיון שהיה ר' זירא רגיל להתעטש, נהנה ביותר לשמוע דבר זה.","\u0003אלא\u0004 מענין \u0003רק\u0004 על \u0003רק קשיא\u0004 \u0005[קשה]!\u0006 ומשיבים: גם בענין היריקה אין סתירה הכרחית, ו\u0003רק\u0004 על \u0003רק נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קשיא [\u0004\u0005[קשה],\u0006 שכן \u0003אפשר\u0004 להסבירו \u0003כ\u0004דברי \u0003רב יהודה.\u0004 ש\u0003אמר רב יהודה:\u0004 אם \u0003היה עומד בתפילה ונזדמן לו רוק\u0004 בפיו — הריהו \u0003מבליעו בטליתו. ואם טלית נאה הוא\u0004 וחס עליה שלא תתלכלך — \u0003מבליעו באפרקסותו\u0004 (סודר שעל הראש), ובאופן זה מותר לירוק. ומסופר כי \u0003רבינא הוה קאי אחוריה\u0004 \u0005[היה עומד אחרי]\u0006 \u0003רב אשי\u0004 בתפילה, \u0003נזדמן לו רוק, פתקיה לאחוריה\u0004 \u0005[זרקו לאחוריו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר לה מר\u0004 \u0005[אין אדוני סבור]\u0006 \u0003להא\u0004 \u0005[כ\u0006דעת \u0005זו]\u0006 של \u0003רב יהודה\u0004 ש\u0003מבליעו באפרקסותו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא אנינא דעתאי\u0004 \u0005[אני אנינה דעתי],\u0006 ועצם הידיעה שיש רוק בסודרי מפריעה לי לתפילה.","בברייתא שנינו: \u0003המשמיע קולו בתפלתו הרי זה מקטני אמנה.\u0004 על כך \u0003אמר רב הונא: לא שנו\u0004 שאינו יכול להשמיע קולו בתפילתו, \u0003אלא\u0004 רק באופן \u0003שיכול לכוון את לבו\u0004 גם בלא כן, \u0003אבל\u0004 אם \u0003אין\u0004 הוא \u0003יכול לכוון את לבו\u0004 כאשר הוא מתפלל \u0003בלחש\u0004 — \u0003מותר\u0004 לו להשמיע קולו. ואולם \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 היתר זה\u0005],\u0006 נאמרו \u0003ביחיד\u0004 המתפלל לבדו, \u0003אבל\u0004 כאשר הוא מתפלל \u0003בציבור\u0004 — \u0003אתי למיטרד ציבורא\u0004 \u0005[יבוא להטריד\u0006 את הציבור] בקולו, ואסור.","מסופר כי \u0003ר' אבא הוה קא משתמיט מיניה\u0004 \u0005[היה משתמט,\u0006 נמנע מלהיראות \u0005ממנו]\u0006 מרבו \u0003רב יהודה,\u0004 מפני \u0003דהוה קא בעי למיסק לארעא\u0004 \u0005[שהיה\u0006 ר' אבא רוצה לעלות לארץ] \u0003ישראל, ו\u0004אולם כיון ש\u0003אמר רב יהודה\u0004 ש\u0003כל העולה מבבל לארץ ישראל\u0004 — \u0003עובר בעשה שנאמר: \"בבלה יובאו ושמה יהיו עד יום פקדי אותם נאם ה'\"\u0004 (ירמיהו כז, כב), לא רצה ר' אבא לבוא לכלל דיון עם רבו, רב יהודה, בדבר עלייתו ארצה. ובכל זאת \u0003אמר: איזיל\u0004 \u0005[אלך]\u0006 \u0003ואשמע מיניה מילתא\u0004 \u0005[ממנו דבר]\u0006 \u0003מבית וועדא\u0004 \u0005[הוועד\u0006 של החכמים\u0005]\u0006 בלי שיראה אותי, \u0003והדר אפיק\u0004 \u0005[ואחר כן אצא\u0006 מבבל\u0005].\u0006","\u0003אזל, אשכחיה לתנא דקתני קמיה\u0004 \u0005[הלך, מצא את שונה המשניות שהיה שונה בפני]\u0006 \u0003ר' יהודה\u0004 ברייתא זו: \u0003היה עומד בתפלה ונתעטש\u0004 מלמטה — \u0003ממתין עד שיכלה הרוח וחוזר ומתפלל. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאם \u0003היה עומד בתפלה וביקש\u0004 (חש בצורך) להתעטש — \u0003מרחיק לאחריו ארבע אמות, ומתעטש, וממתין עד שיכלה הרוח, וחוזר ומתפלל, ואומר\u0004 לפני התפילה: \u0003\"רבונו של עולם, יצרתנו נקבים נקבים חלולים חלולים, גלוי וידוע לפניך חרפתנו וכלימתנו בחיינו, ובאחריתנו רמה ותולעה\",\u0004 ואם כן אין איפוא לדוננו לחובה, \u0003ומתחיל\u0004 להתפלל \u0003ממקום שפסק.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 על כך ר' אבא: \u0003אילו לא באתי\u0004 לבית הועד \u0003אלא לשמוע דבר זה\u0004 — \u0003דיי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003היה ישן בטליתו,\u0004 שהיה ישן ערום, מכוסה בבגד \u0003ואינו יכול להוציא את ראשו\u0004 מתחת לבגד \u0003מפני הצנה\u0004 שבחוץ — \u0003חוצץ,\u0004 מותר לו לחצוץ \u0003בטליתו על צוארו וקורא קריאת שמע\u0004 בתוך המיטה. \u0003ויש אומרים:\u0004 צריך לחצוץ בבגד \u0003על לבו.\u0004","ושואלים: והרי לדעת \u0003תנא קמא\u0004 יש לחשוש מן האיסור ש\u0003הרי לבו רואה את הערוה,\u0004 ואין הפסק ביניהם! על כך השיבו: אכן אותו תנא \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 שאם \u0003לבו רואה את הערוה\u0004 — \u0003מותר,\u0004 וחציצה דרושה רק בין פיו וערוותו.","\u0003אמר רב הונא אמר ר' יוחנן:\u0004 מי ש\u0003היה מהלך במבואות המטונפות\u0004 וצריך לקרוא קריאת שמע — \u0003מניח ידו על פיו וקורא קריאת שמע. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: האלהים\u0004 (לשון שבועה)! גם \u0003אם אמרה לי ר' יוחנן בפומיה\u0004 \u0005[בפיו]\u0006 דבר זה — \u0003לא צייתנא ליה\u0004 \u0005[הייתי מציית לו].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאת ההלכה הזאת \u0003אמר\u0004 (מסר) \u0003רבה בר בר חנה אמר ר' יהושע בן לוי:\u0004 מי ש\u0003היה מהלך במבואות המטונפות\u0004 וצריך לקרוא קריאת שמע — \u0003מניח ידו על פיו וקורא קריאת שמע. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: האלהים\u0004 (לשון שבועה)! גם \u0003אם אמרה לי ר' יהושע בן לוי בפומיה\u0004 \u0005[בפיו]\u0006 דבר זה — \u0003לא צייתנא ליה\u0004 \u0005[הייתי מציית לו].\u0006","על כך מקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הונא הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: תלמיד חכם אסור לו לעמוד במקום הטנופת לפי שאי אפשר לו לעמוד בלא הרהור תורה,\u0004 וקריאת שמע בפיו חמורה היא מהרהור בלבד! על כך משיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זו \u0005קושיה],\u0006 \u0003כאן\u0004 שאסר רב הונא — מדובר \u0003בעומד\u0004 במקום הטינופת, \u0003כאן\u0004 שהתיר — מדובר \u0003במהלך.\u0004","ועוד שאלו: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: בכל מקום מותר להרהר בדברי תורה, חוץ מבית המרחץ ומבית הכסא.\u0004 הרי שמקום המטונף אסור אף בהרהור תורה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לחלק ולומר כי \u0003כאן בעומד כאן במהלך\u0004 — \u0003איני\u0004 \u0005[וכי כן הוא],\u0006 \u0003והא ר' אבהו הוה קא אזיל בתריה\u0004 \u0005[היה הולך אחרי]\u0006 \u0003ר' יוחנן והוה קא קרי\u0004 \u0005[והיה\u0006 ר' אבהו \u0005קורא]\u0006 \u0003קריאת שמע. כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003במבואות המטונפות אשתיק\u0004 \u0005[שתק].\u0006 אחר כך כשיצאו משם \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו \u0003לר' יוחנן: להיכן אהדר\u0004 \u0005[אחזור]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם שהית\u0004 בלי קריאה שיעור זמן \u0003כדי לגמור את כולה\u0004 — \u0003חזור לראש\u0004 הקריאה. ומתוך שלא אמר לו ר' יוחנן שלא היה לו להפסיק מקריאתו, הרי שאף הוא אסר לקרוא קריאת שמע בתוך הילוכו במבואות המטונפות!","ומשיבים: מכאן אין ראיה, כי \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003לדידי לא סבירא לי\u0004 \u0005[אני איני סבור\u0006 כך שצריך להפסיק לקרוא\u0005],\u0006 ואולם \u0003לדידך דסבירא לך\u0004 \u0005[אתה שהנך סבור\u0006 כן\u0005],\u0006 \u0003אם שהית בלי קריאה כדי לגמור את כולה\u0004 — \u0003חזור לראש.\u0004 לשתי השיטות, המתירה והאוסרת, גילו מקורות ראשונים.","\u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב הונא, תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב חסדא. תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב הונא: המהלך במבואות המטונפות\u0004 — \u0003מניח ידו על פיו ויקרא קריאת שמע. תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב חסדא: היה מהלך במבואות המטונפות\u0004 — \u0003לא יקרא קריאת שמע, ולא עוד אלא שאם היה קורא ובא,\u0004 שהוא בתוך כדי קריאה — \u0003פוסק\u0004 באותו מקום מלקרוא.","ושאלו: ואם \u0003לא פסק\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 אפשר להגיד עליו\u0005]\u0006 \u0003אמר ר' מיאשה בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' יהושע בן לוי, עליו הכתוב אומר: \"וגם אני נתתי להם חקים לא טובים ומשפטים לא יחיו בהם\"\u0004 (יחזקאל כ, כה), שההחזקה בחוקים ובמשפטים גורמת במקרה זה לחטא ולא למצווה.","ו\u0003רב אסי אמר,\u0004 הדבר נלמד ממאמר הכתוב: \u0003\"הוי מושכי העון בחבלי השוא\"\u0004 (ישעיה ה, יח), כלומר, לשוא מושך אדם זה עוון על עצמו. \u0003רב אדא בר אהבה אמר מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]\u0006 נלמד הדבר]: \u0003\"כי דבר ה' בזה\"\u0004 (במדבר טו, לא), שאמירת דבר ה' במקום המטונף בזיון הוא לו.","ושואלים: \u0003ואם פסק\u0004 מלקרוא \u0003מה שכרו?\u0004 על כך השיב ו\u0003אמר ר' אבהו: עליו הכתוב אומר: \"ובדבר הזה תאריכו ימים\"\u0004 (דברים לב, מז), שעל ידי זהירות בדיבור זוכה אדם לאריכות ימים.","\u0003אמר רב הונא:\u0004 מי ש\u0003היתה טליתו חגורה לו על מתניו\u0004 אף על פי שלמעלה ממותניו הוא מגולה — \u0003מותר לקרות קריאת שמע.\u0004 ואכן, \u0003תניא נמי הכי\u0004 \u0005[כך שנינו גם\u0006 בברייתא\u0005]\u0006 שאם \u0003היתה טליתו, של בגד\u0004 או \u0003של עור\u0004 או \u0003של שק\u0004 מכל חומר שהוא \u0003חגורה על מתניו\u0004 —\u0003 מותר לקרות קריאת שמע.\u0004"],["\u0003אבל ל\u0004שם \u0003תפלה\u0004 צריך הוא ש\u0003יכסה את לבו,\u0004 שבתפילה פונה הוא בלשון נוכח אל ה' וצריך להתלבש בדרך המתאימה לכך.","\u0003ו\u0004עוד \u0003אמר רב הונא:\u0004 מי ש\u0003שכח ונכנס בתפילין לבית הכסא\u0004 — \u0003מניח ידו עליהן עד שיגמור.\u0004 על כך תמהים: \u0003עד שיגמור סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003אלא כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב נחמן בר יצחק: עד שיגמור עמוד ראשון\u0004 של צואה ואז יצא ויחלוץ את התפילין. ושואלים: \u0003ולפסוק לאלתר וליקום\u0004 \u0005[ושיפסיק מיד ויעמוד\u0006 ויצא משם\u0005]?\u0006 ומשיבים: טעמו דבר הוא כפי שאמר \u0003רבן שמעון בן גמליאל\u0004 שלימד, ש\u0003עמוד\u0004 צואה \u0003החוזר\u0004 בלא שעשה אדם את צרכיו — \u0003מביא את האדם לידי\u0004 מחלת \u0003הדרוקן,\u0004 ו\u0003סילון\u0004 מי רגלים \u0003החוזר\u0004 — \u0003מביא את האדם לידי\u0004 מחלת \u0003ירקון.\u0004 ומכיוון שיש בדבר זה סכנה — לא הצריכוהו לצאת מיד.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בענין מי שהיתה \u0003צואה על בשרו, או\u0004 שהיתה \u0003ידו\u0004 בלבד \u0003מונחת בבית הכסא, רב הונא אמר: מותר\u0004 לו \u0003לקרות קריאת שמע\u0004 באופן כזה. ואילו \u0003רב חסדא אמר: אסור לקרות קריאת שמע. אמר רבא: מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003רב הונא\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל הנשמה תהלל יה הללויה\"\u0004 (תהלים קנ, ו) שהוא מפרשו \"כל הנשימה\", וכשהפה שבו אדם מהלל נמצא במקום טהור — אין זה חשוב היכן שאר אבריו.","\u0003ורב חסדא אמר: אסור לקרות קריאת שמע. מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003רב חסדא\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל עצמותי תאמרנה ה' מי כמוך\"\u0004 (שם לה, י), שתהילת ה' הריהי בכל הגוף כולו, ואפילו כאשר אבר אחד איננו נקי כראוי — אסור לקרוא.","עוד \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בנושא דומה: מה דין \u0003ריח רע שיש לו עיקר,\u0004 כלומר, שריח רע זה בא מדבר הנראה לעין — \u0003רב הונא אמר: מרחיק ארבע אמות\u0004 מעיקרו של הריח הרע, \u0003וקורא קריאת שמע. ורב חסדא אמר: מרחיק ארבע אמות ממקום שפסק הריח,\u0004 בלי לשים לב איפה היה מקור הריח הרע, \u0003וקורא קריאת שמע.\u0004","ומעירים כי \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב חסדא: לא יקרא אדם קריאת שמע\u0004 כנגד דבר שיש בו משום מיאוס, \u0003לא כנגד צואת אדם, ולא כנגד צואת כלבים, ולא כנגד צואת חזירים, ולא כנגד צואת תרנגולים, ולא כנגד צואת אשפה שריחה רע.\u0004 ואולם \u0003אם היה\u0004 הדבר המטונף ב\u0003מקום גבוה עשרה טפחים או נמוך עשרה טפחים\u0004 ממקומו — \u0003יושב בצדו וקורא קריאת שמע,\u0004 שכן הבדל גובה של עשרה טפחים מייחד לו רשות נפרדת לעצמו. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהיה אותו דבר באותו גובה — \u0003מרחיק ממנו מלוא עיניו,\u0004 כלומר, עד שלא יראנו. \u0003וכן לתפלה.\u0004 ואילו \u0003ריח רע שיש לו עיקר\u0004 — \u0003מרחיק ארבע אמות ממקום הריח, וקורא קריאת שמע.\u0004","\u0003אמר רבא: לית הלכתא כי הא מתניתא בכל הני שמעתתא\u0004 \u0005[אין הלכה כברייתא זו בכל השמועות,\u0006 ההלכות \u0005הללו],\u0006 \u0003אלא כי הא דתניא\u0004 \u0005[כאותה\u0006 הלכה \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יקרא אדם קריאת שמע לא כנגד צואת אדם, ולא כנגד צואת חזירים, ולא כנגד צואת כלבים בזמן שנתן עורות לתוכן\u0004 לעבד, אבל שאר דברים אינם נחשבים למלכלכים את מקום התפילה.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב ששת: ריח רע שאין לו עיקר\u0004 שאין מקור הריח בדבר נראה לעין אלא בדבר אחר, כגון נפיחה, \u0003מהו\u0004 דינו? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אתו חזו הני ציפי דבי\u0004 \u0005[בואו וראו אותן מחצלות של בית]\u0006 ה\u0003רב,\u0004 בית המדרש, \u0003דהני גנו והני גרסי\u0004 \u0005[שאלה ישנים ואלה לומדים]\u0006 ואין חוששים לריח רע. \u0003ו\u0004אולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 נאמרו \u0003בדברי תורה, אבל בקריאת שמע\u0004 — \u0003לא. ו\u0004כן \u0003דברי תורה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 להתיר, \u0003אלא\u0004 כשהריח הוא \u0003דחבריה\u0004 \u0005[של חבירו],\u0006 \u0003אבל\u0004 כשהריח הרע הוא \u0003דידיה\u0004 \u0005[של עצמו]\u0006 — \u0003לא\u0004 הותר הדבר.","\u0003אתמר\u0004 \u0005[נאמר] [נאמר]\u0006 שנחלקו חכמים בנושא דומה: אם היתה \u0003צואה עוברת\u0004 לפניו ונעה ממקום למקום, מה דינה? \u0003אביי אמר: מותר לקרות קריאת שמע\u0004 כנגדה, ו\u0003רבא אמר: אסור לקרות קריאת שמע\u0004 כנגדה.","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מניין אני אומר אותה,\u0006 את ההלכה הזו\u0005]\u0006 — על בסיס דברי המשנה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 המצורע מטמא כל מקום שהוא נמצא בתוכו, ופסקו הלכה שאם היה \u0003הטמא\u0004 (המצורע) \u0003עומד תחת האילן והטהור עובר\u0004 תחת אותו אילן — \u0003טמא,\u0004 שהמקום שמתחת לאילן נחשב כבית הנטמא כולו. ואולם אם היה ה\u0003טהור עומד תחת האילן וטמא עובר\u0004 — \u0003טהור. ואם עמד\u0004 הטמא — הטהור נהיה מיד \u0003טמא. וכן\u0004 הדין \u0003באבן המנוגעת\u0004 בנגע צרעת (עיין ויקרא י״ד:נ״ז) שאם היתה רק עוברת במקום — אינה מטמאה, ואם כן, נראה מכאן כי הטומאה נחשבת כמתפשטת בכל צד דווקא כאשר היתה קבועה במקום אחד.","\u0003ו\u0004אילו \u0003רבא אמר לך\u0004 כתשובה לכך: \u0003התם בקביעותא תליא מילתא\u0004 \u0005[שם בקביעות\u0006 המקום \u0005תלוי הדבר],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על המצורע \u0003\"בדד ישב מחוץ למחנה מושבו\"\u0004 (ויקרא יג, מו), וטומאתו — במקום בו הוא יושב וקבוע. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי הצורך להרחיק מדבר המטונף, הלא \u0003\"והיה מחניך קדוש\"\u0004 (דברים כג, טו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ככלל לדבר, \u0003והא ליכא\u0004 \u0005[והרי אין]\u0006 קדושה וטהרה במקום זה.","בענין זה \u0003אמר רב פפא: פי חזיר כצואה עוברת דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 על כך שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006 הלכה זו\u0005]\u0006 \u0003אף על גב דסליק מנהרא\u0004 \u0005[כשעלה\u0006 החזיר מן הנהר], ואף שסביר להניח שבכגון זה נתנקה פיו במי הנהר, מכל מקום אין הוא מגיע לנקיון גמור.","\u0003אמר רב יהודה: ספק צואה,\u0004 כלומר, שספק בידו אם היתה זו צואה או לא, והשאלה היא אם כן אם אסורה היא לענין אמירת דברים שבקדושה סמוך לה, או שאינה אסורה — \u0003אסורה.\u0004 ואילו \u0003ספק מי רגלים\u0004 — \u0003מותרים. איכא דאמרי\u0004 \u0005[יש שאומרים,\u0006 גרסה אחרת\u0005],\u0006 ש\u0003אמר רב יהודה: ספק צואה, בבית\u0004 — \u0003מותרת,\u0004 שיש להניח שמן הסתם לא היתה צואה בתוך הבית, ואילו \u0003באשפה\u0004 — הרי היא \u0003אסורה.\u0004 ואילו \u0003ספק מי רגלים\u0004 — \u0003אפילו באשפה נמי\u0004 \u0005[גם כן]\u0006","\u0003מותרים. סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כי הא\u0004 \u0005[כעין זה]\u0006 שאמר \u0003רב המנונא,\u0004 ש\u0003אמר רב המנונא:\u0004 במי רגלים \u0003לא אסרה תורה אלא כנגד עמוד\u0004 הקילוח \u0003בלבד.\u0004","\u0003וכ\u0004דברי \u0003ר' יונתן.\u0004 ש\u0003ר' יונתן רמי\u0004 \u0005[השליך,\u0006 הראה סתירה בין שני כתובים\u0005]:\u0006 מצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויד תהיה לך מחוץ למחנה ויצאת שמה חוץ\"\u0004 (שם, יג), הרי שלצרכיו די רק שיצא מחוץ למחנה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר: \u0003\"ויתד תהיה לך\u0004 על אזנך והיה בשבתך חוץ וחפרת בה ושבת \u0003וכסית את צאתך\".\u0004 (שם, יד), הרי שיש גם חובת כיסוי!","ומתרץ: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — \u0003כאן\u0004 שחייבו אף \u0003לכסות\u0004 — הרי זה \u0003ב\u0004צרכים \u0003גדולים, כאן\u0004 שלא חייבו לכסות — \u0003ב\u0004צרכים \u0003קטנים. אלמא\u0004 \u0005[מכאן]\u0006 שבצרכים \u0003קטנים לא אסרה תורה אלא כנגד עמוד בלבד. הא נפול לארעא\u0004 \u0005[הרי\u0006 אם \u0005נפלו לארץ]\u0006 — \u0003שרי\u0004 \u0005[מותרים],\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003הוא\u0004 ש\u0003גזרו בהו\u0004 \u0005[בהם],\u0006 \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 — \u0003בודאן, אבל בספיקן\u0004 — \u0003לא גזור\u0004 \u0005[גזרו].\u0006","ושואלים: \u0003ובודאן עד כמה\u0004 זמן ובאיזה מצב אסורים מי רגלים באמירת דברי קדושה סמוך להם? \u0003אמר רב יהודה אמר שמואל: כל זמן שמטפיחין,\u0004 שהם לחים עד כדי שיש בהם כדי להרטיב את הידים. \u0003וכן אמר רבה בר בר חנה אמר ר' יוחנן: כל זמן שמטפיחין. וכן אמר עולא: כל זמן שמטפיחין.\u0004 ואילו \u0003גניבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר:\u0004 אסורים הם \u0003כל זמן שרשומן\u0004 (סימן שלהן) \u0003ניכר\u0004 על הארץ.","על כך \u0003אמר רב יוסף: שרא ליה מריה\u0004 \u0005[ימחול לו אדונו\u0006 ה'\u0005]\u0006 \u0003לגניבא,\u0004 שוודאי לא יתכן שאמר רב דבר מעין זה, שהרי אפילו \u0003השתא\u0004 \u0005[עכשיו]\u0006 ב\u0003צואה אמר רב יהודה אמר רב\u0004 שמ \u0003כיון שקרמו פניה\u0004 והתיבשה במידה ידועה — \u0003מותר\u0004 לקרוא כנגדה, ואם כן, \u0003מי רגלים מיבעיא\u0004 \u0005[צריך\u0006 להשמיענו\u0005]?!\u0006","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי חזית\u0004 \u0005[מה ראית]\u0006 \u0003דסמכת אהא\u0004 \u0005[שאתה סומך על\u0006 הלכה \u0005זו]\u0006 \u0003סמוך אהא\u0004 \u0005[על\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רבה בר רב הונא אמר רב: צואה, אפילו\u0004 היא יבשה \u0003כחרס\u0004 — \u0003אסורה.\u0004","ושאלו: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 מה בדיוק \u0005נחשב]\u0006 \u0003צואה כחרס? אמר רבה בר בר חנה אמר ר' יוחנן: כל זמן שזורקה ואינה נפרכת,\u0004 נחשבת היא כלחה עדיין. \u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 \u0003כל זמן שגוללה\u0004 ממקום למקום, \u0003ואינה נפרכת.\u0004","\u0003אמר רבינא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003רב יהודה מדיפתי חזא\u0004 \u0005[ראה]\u0006 \u0003צואה, אמר לי: עיין\u0004 (ראה) \u0003אי\u0004 \u0005[אם]\u0006 \u0003קרמו פניה אי\u0004 \u0005[\u0006או \u0005אם]\u0006 \u0003לא. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003הכי אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עיין אי מפלאי אפלויי\u0004 \u0005[אם סדוקה\u0006 היא סדקים], שאז נחשבת היא ליבשה.","מאחר שהביעו כבר דעות שונות בדברים, שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 בסיכומה של הלכה זו\u0005]?\u0006 \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בכך הדעות. ששנינו: צואה היבשה \u0003כחרס, אמימר אמר: אסורה, ומר זוטרא אמר מותרת. אמר רבא, הלכתא\u0004 \u0005[הלכה]:\u0006 \u0003צואה כחרס אסורה, ומי רגלים כל זמן שמטפיחין\u0004 אסורים.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003מי רגלים כל זמן שמטפיחין\u0004 — \u0003אסורין, נבלעו\u0004 בקרקע \u0003או יבשו\u0004 במקומם — \u0003מותרים. מאי לאו\u0004 \u0005[האם לא]\u0006 דין מי רגלים ש\u0003נבלעו דומיא\u0004 \u0005[דומה]\u0006 לאלה ש\u0003יבשו? מה יבשו ש\u0004אז \u0003אין\u0004 כבר \u0003רשומן ניכר, אף נבלעו\u0004 — ש\u0003אין רשומן ניכר.\u0004 ואם כן, בכל מקרה \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003רשומן ניכר\u0004 — \u0003אסור, אף על גב\u0004 ש\u0003אין מטפיחין\u0004 עוד!","על כך מקשים קושיה שכנגד: \u0003ולטעמיך אימא רישא\u0004 \u0005[ולטעמך,\u0006 לשיטתך, \u0005אמור\u0006 את \u0005ההתחלה],\u0006 שנאמר שם: \u0003כל זמן שמטפיחין\u0004 — \u0003הוא\u0004 ש\u0003אסור,\u0004 ואפשר להסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם אינם מטפיחים ורק \u0003רשומן ניכר\u0004 — \u0003שרי\u0004 \u0005[מותר]!\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מזו אין לשמוע ממנה],\u0006 כלומר, אין להסיק מסקנות בדרך דיוק ממה שנאמר על מה שלא נאמר, אלא ללמוד כפשוטו בלבד.","ומעירים: \u0003לימא כתנאי\u0004 \u0005[נאמר\u0006 שיש פה מחלוקת \u0005תנאים].\u0006 ששנינו בברייתא: \u0003כלי שנשפכו ממנו מי רגלים, אסור לקרות קריאת שמע כנגדו.\u0004 ואולם \u0003מי רגלים עצמן שנשפכו,\u0004 אם כבר \u0003נבלעו\u0004 — \u0003מותר,\u0004 ואם עדיין \u0003לא נבלעו\u0004 — \u0003אסור. ר' יוסי\u0004 חולק ו\u0003אומר:\u0004 אסורים \u0003כל זמן שמטפיחין.\u0004","ומעתה מבררים את גוף הדברים: \u0003מאי\u0004 \u0005[מה]\u0006 פירושו של \u0003\"נבלעו\" ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"לא נבלעו\" דקאמר\u0004 \u0005[שאמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003נבלעו\u0004 פירושו ש\u0003אין מטפיחין,\u0004 ו\u0003לא נבלעו\u0004 פירושו שעדיין הם \u0003מטפיחין\u0004 — \u0003ו\u0004אם כן \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 \u0003כל זמן שמטפיחין הוא\u0004 ש\u0003אסור,\u0004 אבל \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003רשומן ניכר\u0004 בלבד — \u0003שרי\u0004 \u0005[מותר],\u0006 ואם כן, \u0003היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ואין איפוא מחלוקת כלל! \u0003אלא\u0004 יש לפרש \u0003\"נבלעו\"\u0004 פירושו ש\u0003אין רשומן ניכר, \"לא נבלעו\"\u0004 — שעדיין \u0003רשומן ניכר. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי\u0004 והקל \u0003למימר\u0004 \u0005[לומר]\u0006 ש\u0003כל זמן שמטפיחין הוא\u0004 ש\u0003אסור, הא\u0004 \u0005[הרי]\u0006 אם היה \u0003רשומן ניכר\u0004 — \u0003שרי\u0004 \u0005[מותר]\u0006 ואם כן, דברים אלה שנאמרו קודם קשורים במחלוקת בין התנאים.","את ההכרח בפירוש זה דוחים: \u0003לא,\u0004 אין הדבר מחוייב. אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כל זמן שמטפיחין הוא\u0004 ש\u0003אסור הא\u0004 \u0005[הרי]\u0006 אם היה \u0003רשומן ניכר\u0004 בלבד — \u0003שרי\u0004 \u0005[מותר],\u0006"],["\u0003והכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004מצב של \u0003טופח על מנת להטפיח,\u0004 כלומר, רטוב עד כדי כך שיכול להרטיב אחרים, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, שלדעת תנא קמא צריך שהרטיבות תהיה טופח על מנת להטפיח ואילו ר' יוסי סבור שאף אם היה זה מטפיח בלבד — אסור.","שנינו במשנה שאם \u0003ירד לטבול\u0004 לקריו, צריך הוא לעשות את החישוב \u0003אם יכול לעלות\u0004 ולהתלבש ולקרוא קריאת שמע עד הנץ החמה. על כך שואלים: \u0003לימא תנא סתמא\u0004 \u0005[האם לומר\u0006 ש\u0005שנה\u0006 ר' יהודה הנשיא במשנה שיטה זו ב\u0005סתם,\u0006 ללא ציון שם\u0005]\u0006 ונלמד מכאן שהריהו סבור \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 שסוף זמן קריאת שמע הריהו \u0003עד הנץ החמה?\u0004","הנחה זאת נדחית מיד, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא סבור \u0003כ\u0004דברי \u0003ר' יהושע\u0004 החולק על ר' אליעזר ולדעתו זמן קריאת שמע של שחרית עד שלוש שעות, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 שיטת המשנה כאן נשנתה לנוהגים \u0003כותיקין.\u0004 שכן \u0003אמר ר' יוחנן: ותיקין היו גומרין אותה,\u0004 את קריאת שמע, \u0003עם הנץ החמה.\u0004","\u0003ו\u0004עוד שנינו במשנה ש\u0003אם\u0004 לחשבונו הוא \u0003לאו\u0004 \u0005[לא]\u0006 יכול להספיק לעלות ולהתלבש — \u0003יתכסה במים ויקרא.\u0004 ושואלים: כיצד יכול הוא לקרוא, \u0003והרי\u0004 אף על פי שראשו מעל למים מכל מקום זאת \u0003לבו רואה את הערוה,\u0004 שהלא אין חציצה ביניהם כלל?","על כך \u0003אמר ר' אלעזר, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אחא בר אבא בר אחא משום\u0004 (בשם) \u0003רבינו\u0004 (רב): כאן \u0003במים עכורין שנו, דדמו כארעא סמיכתא\u0004 \u0005[שנחשבים כאדמה סמיכה],\u0006 והריהם מהווים חציצה גמורה, ובכך די \u0003שלא יראה לבו ערותו.\u0004","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אם היה יושב ב\u0003מים צלולין\u0004 — \u0003ישב בהן עד צוארו וקורא\u0004 קריאת שמע. \u0003ויש אומרים\u0004 ש\u0003עוכרן\u0004 את המים \u0003ברגלו.\u0004","על כך שואלים: \u0003ותנא קמא\u0004 \u0005[הראשון],\u0006 \u0003והרי לבו רואה את הערוה\u0004 במים הצלולים! ומשיבים: \u0003קסבר\u0004 \u0005[הוא סבור,\u0006 לדעתו\u0005]\u0006 גם אם \u0003לבו רואה את הערוה\u0004 — \u0003מותר.\u0004 שוב שואלים: \u0003ו\u0004במים הצלולים \u0003הרי עקבו רואה את הערוה!\u0004 ומשיבים: גם בענין זה \u0003קסבר\u0004 \u0005[הוא\u0006 התנא קמא \u0005סבור]\u0006 \u0003עקבו רואה את הערוה\u0004 ש\u0003מותר.\u0004","ומעירים: אמנם \u0003אתמר\u0004 \u0005[נאמר]\u0006 שאם \u0003עקבו רואה את הערוה\u0004 — \u0003מותר,\u0004 ואולם עדיין צריך לברר מה יהיה הדין בשהיה עקבו \u0003נוגע\u0004 בערווה האם מותר בכגון זה לקרוא קריאת שמע, או לא? \u0003אביי אמר: אסור, ורבא אמר: מותר.\u0004 ומעירים: \u0003רב זביד מתני לה להא שמעתא הכי\u0004 \u0005[היה לומד את השמועה,\u0006 ההלכה, \u0005הזו כך]\u0006 כפי שנאמר כאן. ואילו \u0003רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא מתני לה הכי\u0004 \u0005[היה שונה כך,\u0006 בגרסה אחרת\u0005]:\u0006 שביחס לעקבו \u0003נוגע\u0004 בערווה — ל\u0003דברי הכל אסור,\u0004 והמחלוקת היתה בכגון שעקבו \u0003רואה\u0004 את הערווה, ש\u0003אביי אמר: אסור,\u0004 ו\u0003רבא אמר: מותר,\u0004 וטעמו: לפי ש\u0003לא נתנה תורה למלאכי השרת,\u0004 והאדם באשר יש לו, בניגוד למלאכי השרת, ערווה, אינו יכול להישמר מכל זה. \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 שבעקבו \u0003נוגע\u0004 — \u0003אסור,\u0004 וב\u0003רואה\u0004 בלבד — \u0003מותר.\u0004","\u0003אמר רבא:\u0004 אם היתה \u0003צואה\u0004 מונחת \u0003בעששית\u0004 (כיסוי שקוף), \u0003מותר לקרות קריאת שמע כנגדה.\u0004 אך אם היתה \u0003ערוה\u0004 מכוסה \u0003בעששית\u0004 שקופה, \u0003אסור לקרות קריאת שמע כנגדה.\u0004 וטעם הדבר: \u0003צואה בעששית מותר לקרות קריאת שמע כנגדה\u0004 שכן \u0003צואה בכיסוי תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 \u0003והא מיכסיא\u0004 \u0005[והרי\u0006 היא \u0005מכוסה],\u0006 ואין זה חשוב אם היא נראית, וכפי שנאמר \"וכיסית את צאתך\" (דברים כג, יד). ואילו \u0003ערוה בעששית אסור לקרות קריאת שמע כנגדה,\u0004 שכן \u0003\"ולא יראה בך ערות דבר\"\u0004 (שם פסוק טו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה].\u0006 \u0003והא קמיתחזיא\u0004 \u0005[והרי היא נראית].\u0006","\u0003אמר אביי: צואה כל שהו,\u0004 כלומר, שהיה שיעורה קטן ביותר \u0003מבטלה ברוק,\u0004 וכל עוד מכוסה היא ברוק אין בה איסור. על כך \u0003אמר רבא: ו\u0004צריך שיהא זה \u0003רוק עבה\u0004 דווקא. \u0003אמר רבא:\u0004 אם היתה \u0003צואה\u0004 מונחת \u0003ב\u0004תוך \u0003גומא\u0004 — אם רוצה, \u0003מניח\u0004 את \u0003סנדלו עליה\u0004 על הגומה ולכסות אותה, \u0003וקורא קריאת שמע. בעא\u0004 \u0005[שאל]\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא:\u0004 אם היתה ה\u0003צואה דבוקה\u0004 ממש \u0003בסנדלו\u0004 — \u0003מאי\u0004 \u0005[מה]\u0006 הדין? שמא במקרה זה נחשב הוא עצמו כמלוכלך. לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה ללא פתרון.","\u0003אמר רב יהודה: גוי ערום אסור לקרות קריאת שמע כנגדו.\u0004 על כך שואלים: \u0003מאי איריא\u0004 \u0005[מדוע לימד\u0006 דווקא\u0005]\u0006 ב\u0003גוי? אפילו ישראל נמי\u0004 \u0005[גם כן\u0006 אסור\u0005]!\u0006 ומשיבים: \u0003ישראל פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 ש\u0003אסור\u0004 לו לקרוא כנגד ערוותו, \u0003אלא גוי איצטריכא ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]\u0006 שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 אפשר היה לחשוב כי \u0003הואיל וכתיב בהו\u0004 \u0005[ונאמר בהם,\u0006 בגויים\u0005]\u0006 \u0003\"אשר בשר חמורים בשרם\"\u0004 (יחזקאל כג, כ), ועל כן אולי \u0003אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003כחמור בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא\u0004 ואין בו משום גילוי ערווה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאינהו נמי איקרו\u0004 \u0005[שהם,\u0006 אצלם \u0005גם כן\u0006 הרי זו \u0005נקראת]\u0006 \u0003ערוה.\u0004 וראיה לדבר ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבני נח: \u0003\"וערות אביהם לא ראו\"\u0004 (בראשית ט, כג), והרי אף שלא היה נח יהודי, בכל זאת מזכירים בו \"ערווה\".","\u0003ו\u0004עוד שנינו במשנה ש\u0003לא יתכסה\u0004 אדם שנמצא בתוך מים וצריך לקרוא את שמע \u0003לא במים הרעים ולא במי המשרה\u0004 של פשתן \u0003עד שיטיל לתוכן מים.\u0004 ושואלים: \u0003וכמה מיא רמי ואזיל\u0004 \u0005[מים שופך והולך]?\u0006 שהרי אם הוא נמצא בתוך מי המישרה ודאי הם רבים, ובוודאי צריך להוסיף להם מים נקיים רבים כדי לבטל את המים הרעים! \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003לא יתכסה לא במים הרעים ולא במי המשרה כלל. ו\u0004אילו \u0003מי רגלים\u0004 מאוסים \u0003עד שיטיל לתוכן מים\u0004 נקיים, \u0003ו\u0004אז \u0003יקרא\u0004 את שמע.","ולעומת זאת \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא מחלוקת בענין זה: \u0003כמה יטיל לתוכן מים\u0004 כדי לבטל את מי הרגלים — \u0003כל שהוא,\u0004 ודי בכך. ואילו \u0003ר' זכאי אומר:\u0004 יש להוסיף \u0003רביעית.\u0004","על כך \u0003אמר רב נחמן: מחלוקת\u0004 זו היא דווקא \u0003לבסוף,\u0004 כשהיו כבר מי רגלים בכלי והוא רוצה לבטל אותם. \u0003אבל\u0004 אם היו מים נקיים \u0003בתחילה,\u0004 הרי מי הרגלים הנופלים שם מתבטלים והולכים עם נפילתם בכלי, ועל כן אין צורך אלא שיהא בכלי \u0003כל שהן\u0004 (משהו) מים נקיים.","\u0003ו\u0004אילו \u0003רב יוסף אמר:\u0004 שה\u0003מחלוקת\u0004 היא לגבי כמות המים שצריכים להיות בכלי \u0003לכתחילה. אבל לבסוף\u0004 ל\u0003דברי הכל\u0004 צריך \u0003רביעית.\u0004 ומסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003לי רביעיתא דמיא\u0004 \u0005[רביעית המים]\u0006 בתחילה, \u0003כ\u0004שיטת \u0003ר' זכאי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא בענין אותה בעיה בהרחבה: \u0003גרף\u0004 (כלי המיוחד לכך) \u0003של רעי\u0004 (צואה) או \u0003עביט של מי רגלים\u0004 — \u0003אסור לקרות קריאת שמע כנגדן, ואף על פי שאין בהם כלום,\u0004 שהם כמטונפים בכל עת. \u0003ו\u0004כנגד \u0003מי רגלים עצמן\u0004 — אסור \u0003עד שיטיל לתוכן מים. וכמה יטיל לתוכן מים\u0004 — \u0003כל שהוא. ר' זכאי אומר: רביעית.\u0004 דבר זה נאמר \u0003בין לפני המטה בין לאחר המטה,\u0004 כלומר, בין שהיה הכלי גלוי לפני המטה, ובין כשהיה מכוסה מתחת המטה. ואילו \u0003רבן שמעון בן גמליאל אומר: לאחר המטה\u0004 — \u0003קורא,\u0004 אבל \u0003לפני המטה\u0004 — \u0003אינו קורא, אבל מרחיק הוא ארבע אמות וקורא.\u0004 ו\u0003ר' שמעון בן אלעזר\u0004 מחמיר יותר ו\u0003אומר: אפילו בית\u0004 ששיעורו \u0003מאה אמה\u0004 — \u0003לא יקרא עד שיוציאם או שיניחם תחת המטה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: \u0003היכי קאמר\u0004 \u0005[כיצד אמר,\u0006 מה היתה כוונתו\u0005]\u0006 של רבן שמעון בן גמליאל. האם לפרש שאם היה הכלי \u0003אחר המטה\u0004 — \u0003קורא מיד,\u0004 ו\u0003לפני המטה\u0004 — \u0003מרחיק ארבע אמות וקורא, או דילמא הכי קאמר\u0004 \u0005[שמא כך אמר]:\u0006 אם היה כלי זה \u0003לאחר המטה\u0004 — \u0003מרחיק ארבע אמות וקורא,\u0004 ואולם אם היה \u0003לפני המטה\u0004 — \u0003אינו קורא כלל.\u0004 כדי לפתור בעיה זו מביאים ברייתא אחרת.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו, \u0003ר' שמעון בן אלעזר אומר: אחר המטה\u0004 — \u0003קורא מיד, לפני המטה\u0004 — \u0003מרחיק ארבע אמות. רבן שמעון בן גמליאל אומר: אפילו\u0004 ב\u0003בית\u0004 גדול של \u0003מאה אמה\u0004 — \u0003לא יקרא עד שיוציאם או שיניחם תחת המטה.\u0004 ואם כן, למדנו מברייתא שאם היה הכלי תחת המטה — מותר לו לקרוא מיד.","על כך מעירים: \u0003בעיין איפשיטא לן, מתנייתא קשיין אהדדי\u0004 \u0005[בעייתנו נפתרה לנו,\u0006 ואולם \u0005הברייתות קשות זו על זו],\u0006 שהדברים שנאמרו בברייתא אחת בשם רבן שמעון בן גמליאל נאמרו באחרת בשם ר' שמעון בן אלעזר. על כך מתרצים: \u0003איפוך בתרייתא\u0004 \u0005[הפוך\u0006 את \u0005האחרונה]\u0006 ואמור שנשתבשו שמות בעלי הדעות.","תירוץ זה מעורר את התמיהה: \u0003מה חזית דאפכת בתרייתא\u0004 \u0005[ראית שהפכת\u0006 את \u0005האחרונה]?\u0006 \u0003איפוך קמייתא\u0004 \u0005[הפוך\u0006 את \u0005הראשונה]!\u0006","ומוכיחים כי הדבר נעשה בהתאם לשיטות החכמים הללו בכלל כי \u0003מאן שמעת ליה\u0004 \u0005[מי שמעת אותו]\u0006 ש\u0003אמר\u0004 כי \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003בית כארבע אמות דמי\u0004 \u0005[נחשב]\u0006 — \u0003ר' שמעון בן אלעזר היא,\u0004 שזו דעתו בהלכות עירובין (רב נסים), ובכן נראה שגם בהלכות אלו תהא זו דעתו, ויש איפוא לגרוס בברייתא בהתאם לכך.","\u0003אמר רב יוסף: בעאי מיניה\u0004 \u0005[שאלתי אותו]\u0006 את \u0003רב הונא: מטה\u0004 שיש מתחתיה חלל פחות \u0003משלשה\u0004 טפחים \u0003פשיטא\u0004 \u0005[ברור]\u0006 \u0003לי\u0004 ש\u0003כלבוד דמי\u0004 \u0005[נחשב],\u0006 כלומר, כאילו חלל זה אינו קיים. כי להלכה נחשב חלל פחות משלושה טפחים כסתום. ועל מה היתה השאלה? במקרה שהיה גובה חלל זה \u0003שלשה\u0004 טפחים, או \u0003ארבעה, חמשה, ששה, שבעה, שמנה, תשעה\u0004 טפחים, \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא\u0004 \u0005[איני יודע].\u0006 ואילו בחלל שגובהו \u0003עשרה\u0004 טפחים \u0003ודאי לא מבעיא\u0004 \u0005[נצרכה]\u0006 \u0003לי\u0004 לשאול, שברור לי שהדבר נחשב כתחום אחר. \u0003אמר\u0004 לו \u0003אביי: שפיר עבדת\u0004 \u0005[יפה עשית]\u0006 ש\u0003לא איבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לך,\u0004 שכן הלכה היא שכל הגבוה \u0003עשרה\u0004 טפחים \u0003רשותא אחריתא\u0004 \u0005[רשות אחרת]\u0006 \u0003היא.\u0004","\u0003אמר רבא\u0004 לסיכום הדברים: \u0003הלכתא\u0004 \u0005[הלכה]\u0006 אם כן, \u0003פחות משלשה\u0004 טפחים \u0003כלבוד דמי\u0004 \u0005[נחשב]\u0006 הוא ומותר. \u0003עשרה\u0004 — \u0003רשותא אחריתא\u0004 \u0005[רשות אחרת]\u0006 \u0003היא.\u0004 ואילו \u0003משלשה עד עשרה\u0004 — \u0003היינו דבעא מיניה\u0004 \u0005[זהו ששאל ממנו]\u0006 \u0003רב יוסף מרב הונא ולא פשט ליה\u0004 \u0005[פתר לו].\u0006 ולעיקר הלכה זו, \u0003אמר רב: הלכה כר' שמעון בן אלעזר. וכן אמר\u0004 החכם \u0003באלי אמר רב יעקב ברה\u0004 \u0005[בנה]\u0006 של \u0003בת שמואל: הלכה כר' שמעון בן אלעזר. ו\u0004אילו \u0003רבא אמר: אין הלכה כר' שמעון בן אלעזר.\u0004","מסופר: \u0003רב אחאי איעסק ליה לבריה\u0004 \u0005[עסק אתו עם בנו]\u0006 להשיאו ל\u0003בי\u0004 \u0005[לביתו]\u0006 של \u0003רב יצחק בר שמואל בר מרתא, עייליה\u0004 \u0005[הכניסו]\u0006 \u0003לחופה, ולא הוה מסתייעא מילתא\u0004 \u0005[היה מצליח הדבר]\u0006 של הבעילה. \u0003אזל בתריה לעיוני\u0004 \u0005[הלך אחריו לבדוק],\u0006 \u0003חזא\u0004 \u0005[ראה]\u0006 \u0003ספר תורה דמנחא\u0004 \u0005[שמונח\u0006 שם\u0005].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איכו השתא\u0004 \u0005[אם עכשיו]\u0006 \u0003לא אתאי\u0004 \u0005[\u0006הייתי \u0005בא]\u0006 \u0003סכנתון לברי\u0004 \u0005[\u0006הייתם \u0005מסכנים את בני]\u0006 להיענש בעוון זה במיתה. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית\u0004 (חדר) \u0003שיש בו ספר תורה או תפילין אסור לשמש בו את המטה עד שיוציאם\u0004 מן החדר \u0003או שיניחם כלי בתוך כלי.\u0004","בענין זה \u0003אמר אביי: לא שנו\u0004 שכלי בתוך כלי נחשב ככיסוי מספיק \u0003אלא בכלי שאינו כליין\u0004 הקבוע של ספר התורה או התפילין, \u0003אבל בכלי שהוא כליין\u0004 — \u0003אפילו עשרה מאני\u0004 \u0005[כלים]\u0006 \u0003כחד מאנא דמי\u0004 \u0005[כ\u0006כלי \u0005אחד נחשבים],\u0006 וצריך לכסותם בכלי נוסף, שאין רגילים להשתמש בו לצורך זה. \u0003אמר רבא: גלימא\u0004"]]};
